INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3ZvItmKGdVR', 4, '{"title":"第400106415条・卷之十四_木部下品","description":"<p>15、石南</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106415,"note":"      味辛、苦，平，有毒。主养肾气，内伤阴衰，利筋骨皮毛，疗脚弱，五藏邪气，除热。女子不可久服，令思男。\n\n       疏：石南得火金之气，故其味辛、苦，气平有毒。然观其用，当是金胜火微，其性应云有小毒。可升可降，阴中阳也。入足厥阴，足少阴经。少阴属水，得金气之厚者能生水，故主养肾气。又肾为阴中之阴，肝为阴中之阳，二经俱在下而主筋骨。二经得所养，则内伤阴衰自起，筋骨皮毛自利，而脚弱自健也。湿热之邪留滞五脏，则筋骨、皮毛、气血，皆为之病矣。邪热散，则诸病自瘳。女子久服思男者，以其补肾气，助阳火耳。\n\n【主治参与】\n同巴戟天、肉苁蓉、锁阳、鹿茸、枸杞子、山茱萸，治肾经虚寒，精滑精冷。\n\n同白蒺藜、桑叶、何首乌、淫羊藿、巴戟天、五加皮、菟丝子、威灵仙、虎骨，治肝肾为风寒湿所乘，以致痹弱不能行动。\n\n【简误】\n肾虚而阳道数举者，不宜用。脚弱由于肝肾虚，而不由于风寒湿客下部者，不宜用。\n","videoMemo":"","fangList":[],"bieMing":"石南"}}', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '15、石南', '2024-12-28T01:36:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'yTR9oWoVJLx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0lWSY5vRq0a', 4, '{"title":"第400106414条・卷之十四_木部下品","description":"<p>14、橡实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106414,"note":"      味苦，微温，无毒。主下痢，厚肠胃，肥健人。其壳为散，及煮汁服，亦主痢。并堪染用。\n\n       疏：橡实感天地微阳之气，兼得秋时收敛之性，故其味苦，气微温，性无毒，气薄味厚，阳中阴也。入手足阳明，足太阴、少阴经。夫脾胃为五脏根本，一身之最要，喜温暖而恶寒湿，寒湿则违其性，故宜急食苦以燥之。此药味苦能除其所恶，气温能遂其所喜，故主厚肠胃，肥健人也。得收敛之性，故又主下痢，及日华子涩肠止泻诸治，兼能涩精。煮食复能止饥御歉岁。\n壳：气味与实相同，而涩则过于实。故亦主下痢。并堪染皂也。\n\n【主治参与】\n《圣惠方》水谷下痢，日夜百余行者：橡实二两，楮叶炙一两，为末。每服一钱，食前乌梅汤调下。\n\n《直指方》下痢脱肛：橡斗子，烧存性，研末，猪脂和傅。\n\n【简误】\n      湿热作痢者不宜用。","videoMemo":"","fangList":[],"bieMing":"橡实"}}', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '14、橡实', '2024-12-28T01:36:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'yTR9oWoVJLx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uG1VSX5DxuI', 4, '{"title":"第400106413条・卷之十四_木部下品","description":"<p>13、南烛枝叶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106413,"note":"      味苦，平，无毒。止泄，除睡，强筋，益气。久服轻身，长年，令人不饥，变白去老。取茎叶捣碎渍汁，浸粳米，九浸九蒸九曝，米粒紧小，正黑如瑿珠。袋盛之，可适远方。日进一合，不饥，益颜色，坚筋骨能行。取汁炊饭，名乌饭。亦名乌草，亦名牛筋，言食之健如牛筋也。\n\n       疏：南烛禀春生之气以生，本经言其味苦气平，性无毒。然尝其味，亦多带微涩。其气平者，平即凉也。入心脾肾三经之药。十剂云：涩可去脱。非其味带涩，则不能止泄；非其气本凉，则不能变白。发者，血之余也；颜色者，血之华也。血热则鬓发早白，而颜枯槁，脾弱则困倦嗜卧而气力不长，肾虚则筋骨软弱而行步不前。入心凉血，入脾益气，入肾添精，其云轻身长年，令人不饥者，非虚语矣。凡变白之药，多是气味苦寒，有妨脾胃，惟南烛气味和平，兼能益脾，为修真家所须。\n子：味甘、酸。其功效尤胜枝叶。真变白、驻颜、轻身却老之良药也。牧童食之，辄止饥渴，亦一验矣。\n\n【主治参与】\n       孙思邈《千金月令》方：南烛煎：益髭发及容颜，兼补暖。三月三日采叶并蕊子，入大净瓶中，以童子小便浸满瓶，固济其口。置闲处，经一周年取开。每用一匙，温酒调服，极有效验。同旱莲草、没食子、地黄、桑堪、枸杞、山茱萸、何首乌、白蒺藜，为乌须发之圣药。\n\n气味和平，性复无毒，除变白外，无他用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"南烛枝叶"}}', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '13、南烛枝叶', '2024-12-28T01:36:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'yTR9oWoVJLx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9AOmfjdtE6G', 4, '{"title":"第400106412条・卷之十四_木部下品","description":"<p>12、胡椒</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106412,"note":"    味辛，大温，无毒，主下气，温中，去痰，去脏腑中风冷。\n\n     疏：胡椒禀天地纯阳之气以生，故其味辛、气大温。性虽无毒，然辛温太甚，过服未免有害。气味俱厚，阳中之阳也。入手足阳明经。其主下气，温中，去痰，除脏腑中风冷者，总因肠胃为寒冷所乘，以致脏腑不调，痰气逆上，辛温暖肠胃而散风冷，则痰气降，脏腑和，诸证悉瘳矣。\n\n【主治参与】\n《食疗》治心腹冷痛：胡椒三七枚，清酒吞之。\n\n《卫生易简方》夏月冷泻及霍乱：用胡椒碾细，饭丸梧子大，每米饮下四十丸。\n\n【简误】\n        胡椒，辛温大热纯阳之药也。凡胃冷呕逆，宿食不消，或霍乱气逆，心腹冷痛，或大肠虚寒，完谷不化，或寒痰冷积，四体如冰，兼杀一切鱼、肉、鳖、蕈等毒，诚为要品。然而血分有热，与夫阴虚发热咳嗽，吐血，咽干口渴，热气暴冲目昏，口臭，齿浮，鼻衄，肠风脏毒，痔漏泄澼等证，切勿轻饵。误服之，能令诸病即时作剧。慎之！慎之！","videoMemo":"","fangList":[],"bieMing":"胡椒"}}', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '12、胡椒', '2024-12-28T01:36:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'yTR9oWoVJLx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p2dvuwuULl7', 4, '{"title":"第400106411条・卷之十四_木部下品","description":"<p>11、苏方木</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106411,"note":"      味甘、咸，平，无毒。主破血。产后血胀闷欲死者，水煮、苦酒煮五两，取浓汁服之效。\n \n       疏：苏方木禀水土之气以生，故其味甘咸，气平无毒。好古加辛。降多于升，阳中阴也。入足厥阴，兼入手少阴，足阳明经。凡积血，与夫产后血胀闷欲死，无非心肝二经为病。此药咸主入血，辛能走散，败浊瘀积之血行，则二经清宁，而诸证自愈。日华子主妇人血气心腹痛，月候不调，及蓐劳，排脓止痛，消痈肿，扑损瘀血，女人失音血噤。《海药》主虚劳，血癖，气壅滞，产后恶露不净，心腹搅痛，及经络不通。悉取其入血行血，辛咸消散，亦兼有软坚润下之功，故能祛一切凝滞留结之血，妇人产后，尤为所须耳。\n\n【主治参与】\n同泽兰、川芎、麦门冬、生地黄、蒲黄、人参、童便、益母草、牛膝、黑豆、荆芥穗，治产后血晕，有神。\n\n同山查、延胡索、牡丹皮、泽兰、当归、五灵脂、赤芍药、红花，治产后儿枕作痛。加入乳香、没药，治产后血癖不消，因寒而得者，加炒黑干姜，桂各少许。\n\n同延胡索、牡丹皮、牛膝、当归、地黄、芍药、续断，治妇人月候不调。煎浓汁，加入乳香、没药、血竭、自然铜、䗪虫、麻皮灰、黄荆子等末，量病轻重，调服四五钱，治跌扑损伤如神。\n\n胡氏方：产后气喘，面黑欲死，乃血入肺也，用苏木二两，水二碗，煮一碗，入人参末五钱服。随时加减，神效不可言。名参苏饮。\n\n【简误】\n产后恶露已尽，由血虚腹痛者，不宜用。","videoMemo":"","fangList":[],"bieMing":"苏方木"}}', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '11、苏方木', '2024-12-28T01:36:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'yTR9oWoVJLx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g8JYtsyqmcJ', 4, '{"title":"第400106410条・卷之十四_木部下品","description":"<p>10、雷丸</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106410,"note":"      味苦、咸，寒、微寒，有小毒。主杀三虫，逐毒气，胃气热。利丈夫，不利女子。作摩膏，除小儿百病，逐邪气恶风汗出，除皮中热，结积蛊毒，白虫寸白自出不止。久服令人阴痿。\n\n      疏：雷丸禀竹之余气，兼得地中阴水之气以生。《本经》味苦气寒。\n   \n     《别录》加咸，有小毒。黄帝、岐伯、桐君、扁鹊云甘。详其所主，应是苦咸为胜。气薄味厚，阴也，降也。入手足阳明经。其主杀三虫，白虫寸白自出者，肠胃湿热甚也。逐毒气，胃中热，邪气恶风汗出，皮中热，结积者，肠胃邪热盛也。苦寒能除二经湿热邪气，则上来诸证自除。作摩膏治小儿百病者，以小儿好食甘肥，肠胃类多湿热虫积，苦能杀虫除湿，咸寒能清热消积，故主之也。凡蛊毒必热，必辛苦寒能除辛热，故又主解蛊毒也。利丈夫，不利女子者，盖以男子属阳，得阴而生，故喜阴寒之味。女子属阴，得阳而长，故不利阴寒之物也。《别录》又云：久服令人阴痿，正见其过于苦寒，偏至之气能令阳道痿也。\n\n【主治参与】\n同芜荑、使君子、芦会、五谷虫、胡黄连、青黛，治小儿疳蛔，有神。\n\n同槟榔、鹤虱、楝根、贯众、牵牛、锡灰、薏苡根，杀肠胃一切虫。\n\n《经验方》下寸白虫：雷丸水浸去皮，切焙为末。五更初，食炙肉少许，以稀粥饮服一钱匕。须上半月服，虫乃下。\n\n除杀虫外，他用甚稀，故不著 “简误”。惟赤色者能杀人，用时细择去之。\n","videoMemo":"","fangList":[],"bieMing":"雷丸"}}', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '2024-12-28T01:36:06.000Z', '10、雷丸', '2024-12-28T01:36:06.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'yTR9oWoVJLx');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8U0QIafookB', 4, '{"title":"第400106513条・卷之十五_人部","description":"<p>13、初生脐带</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106513,"note":"      主疟。烧为灰，饮下之。\n\n       疏：脐者，命蒂也。当心肾之中，为真元归宿之处。胎在母腹，脐连于胞，喘息呼吸滋养之妙，从此而通。胎出母腹，脐带剪断，则一点真元之气，从此而归入命门丹田。故脐为命蒂，而脐带亦真气会聚之所也。本经以之治疟者，应是久疟虚寒之甚，借其气以补不足也。今世以小儿脱下脐带，烧灰与服，可解胎中一切毒，及免惊风痘患，亦取裨补真元耳。\n\n【主治参与】\n《全幼心鉴》脐汁不干：绵裹落下脐带，烧研一钱，入当归头末一钱，麝香一字，掺之。\n\n《保幼大全》预解胎毒：脐带烧灰，以乳汁调服。或入辰砂少许，可免痘患。\n\n无毒而主疗甚稀，不著“简误”。","videoMemo":"","fangList":[],"bieMing":"初生脐带"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '13、初生脐带', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RgCAUVn2zT0', 4, '{"title":"第400106512条・卷之十五_人部","description":"<p>12、人胞</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106512,"note":"      主血气羸瘦，妇人劳损，面䵟皮黑，腹内诸病渐瘦瘁者，以五味和之，如䭔（饣甲）法与食之，勿令知。一名紫河车。\n\n       疏：夫人有生之初，揽父精母血以成胚胎，外即有衣一层裹之，即胞也。至十月降生时，随儿后出。其味甘咸，气温无毒。血气羸瘦，妇人劳损，面䵟皮黑，腹内诸病渐瘦瘁者，皆荣血不足，精气亏损也。此药得精血之气而结，能从其类以补之，是以主诸证也。今世以之治男女一切虚损劳极，为益血补精气之用。\n\n【主治参与】\n同人参、黄耆、鹿茸、白胶、当归、补骨脂、五味子、巴戟天，治真阳虚极，畏寒足冷。\n\n吴球大造丸：治虚劳骨蒸，女人无子，及多生女，月水不调，小产难产。服之必主有子。危疾将绝者，一二服可更活一二日，其补气血之功力可见也。久服耳目聪明，须发乌黑，延年益寿，有夺造化之功，故名大造丸。用紫河车一具，男用女胎，女用男胎，初生者，米泔洗净，淡酒蒸熟，捣晒研末。败龟板、童便浸三日，酥炙黄二两，黄檗、杜仲各一两半，牛膝一两二钱；生地黄二两半入砂仁六钱，白茯苓二两，绢袋盛入瓦罐酒煮七次，去茯苓、砂仁不用，杵地黄为膏听用，天门冬、麦门冬、人参各一两二钱净，夏月加五味子七钱，俱忌铁器，为细末，地黄膏加酒、米糊，丸小豆大。每服八九十丸，空心盐汤下。女人去龟板，加当归二两。男子遗精，女人漏下，并加牡蛎粉一两，去人参。\n\n【简误】\n人胞乃补阴阳两虚之药，以其形质亦得男妇坎离之气而成，如阴阳两虚者，服之有返本还元之功，诚为要药也。然而阴虚精涸，水不制火，发为咳嗽、吐血、骨蒸、盗汗等证，此属阳盛阴虚，法当壮水之主以制阳光，不宜服此并补之剂，以耗将竭之阴也。胃火齿痛，法亦忌之。\n\n胞衣水　味辛，无毒。主小儿丹毒，诸热毒发寒热不歇，狂言妄语，头上无辜发竖，虚痞等证。天行热病，饮之立效。此即胞衣埋地下久远化为水者，得地中之阴气，其气必寒，辛寒而走足阳明经，故主如上诸证也。南人以甘草、升麻和人胞，瓶盛埋之，三五年后掘出，取为药也。\n","videoMemo":"","fangList":[],"bieMing":"人胞"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '12、人胞', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lo3YNyuPO5Z', 4, '{"title":"第400106511条・卷之十五_人部","description":"<p>11、天灵盖</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106511,"note":"      味咸，平，无毒。主传尸尸疰，鬼气伏连，久瘴劳疟，寒热无时者。烧令黑，细研，白饮和服，亦合丸散用。\n\n      疏：天灵盖，乃死人脑盖骨也。不用他骨，而用此者，以人生时，脑为诸阳之会，而此骨则一身众骨之主也。其主传尸尸疰，鬼气伏连者，取其同类之气，引出邪魅，则其魂魄飞越，不复附人，故得瘥也。久瘴劳疟，寒热无时者，亦邪恶之气侵人也。辟恶散邪是其能事，故亦主之。\n\n【主治参与】\n同鬼臼、干漆、象胆、獭肝、丹砂、胡黄连，入滋阴药内治传尸劳。\n\n同牛黄、象牙末、蛀竹屑、血竭、乳香、没药、黄蜡、明矾、真珠，作丸。治杨梅结毒。\n\n《痘疮经验方》：痘疮陷伏，灰平不长，此系虚寒证。用天灵盖烧研，酒服三分。\n\n附：化尸场上人骨，取为细末，傅金疮，止血长肉，及恶疮不收敛。并能治打扑折伤，人受杖时服之，不痛，不肿，不烂。\n\n【简误】\n       天灵盖治劳瘵者，以其有尸鬼劳虫为害，取其逐散邪也。今人虚损劳怯，皆系色欲过度，损伤真阴，实无鬼气淹伏，何得用此幽暗不祥之物治之哉？其痘疮虚寒陷伏，或为邪气所触发不出者，不过借其阳气所结之余，逐散其邪以发出耳，非正治也。若血热烦躁，疮干紫黑者，用之必致危殆不救。慎之！慎之！","videoMemo":"","fangList":[],"bieMing":"天灵盖"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '11、天灵盖', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gNnbRgyw2Pf', 4, '{"title":"第400106510条・卷之十五_人部","description":"<p>10、怀妊妇人爪甲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106510,"note":"      取细末，置目中去翳障。\n\n       疏：爪者，筋之余，肝胆之外候也。《经》曰：多食辛，则筋急而爪枯。以辛能散真气而走筋也。本经独用怀妊妇人者，盖妇人气血充实，乃能受孕，取其有生长力紧之意也。其味甘咸，气平无毒。目中翳障，肝经血虚也。爪甲乃肝之余气所生，而性又带散，故点目能去翳障也。寇宗奭：以众人甲，刮取细末㗜鼻内，治鼻衄立愈。兼能催生，利小便，止尿血，散乳痈等用。\n\n【主治参与】\n        《圣惠方》胞衣不下，取本妇手足爪甲，烧灰，酒服。又方，一切目疾：以木贼草擦取爪甲末，同丹砂等分，研匀，以露水搜丸芥子大。每以一粒，点入目内。或用乳汁和亦得。并治飞丝入目。","videoMemo":"","fangList":[],"bieMing":"怀妊妇人爪甲"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '10、怀妊妇人爪甲', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ljZmvUoQCN', 4, '{"title":"第400106509条・卷之十五_人部","description":"<p>9、浣裈汁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106509,"note":"        解箭毒，并女劳复亦善。\n\n        妇人裈裆，主阴易病。当阴上割取，烧末服方寸匕。童女裈益佳。若女患阳易，即须男子裈也。阴易病者，人患时行，病起后交合，阴阳便即相著，甚于本病。其候小便赤涩，寒热甚，头痛，腰痛，耳鸣，眼花，服此便通利。\n\n        疏：裈裆居下体，得阴气胜，取其以类相从、气相感，能导邪热，故主阴阳易病也。\n\n【主治参与】\n          仲景方：阴阳易病，身体重，少气，腹里急，或引阴中拘急，热上冲胸，头重不欲举，眼中生花，膝胫拘急者，烧裈散主之。取中裈近阴处，烧灰，水服方寸匕，日三服，小便即利，阴头微肿则愈。男用女，女用男。\n\n《千金方》胞衣不下，以本妇裈，覆井上即下。","videoMemo":"","fangList":[],"bieMing":"浣裈汁"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '9、浣裈汁', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ccjeqcdtaHd', 4, '{"title":"第400106508条・卷之十五_人部","description":"<p>8、妇人月水</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106508,"note":"       解箭毒，并女劳复。\n\n        陈藏器云：经衣：主金疮血涌出，炙热熨之。又烧灰傅虎狼伤疮，及箭镞毒入腹。\n\n       疏：《经》云：女子二七天癸至，任脉通，太冲脉盛，月事以时下。谓之天癸者，乃天一所生之水也。上应太阴，下应海潮，月有盈亏，潮有朝汐，故月事一月一行，与之相符也。其味咸，咸为水化，凡毒得水则解，故能解箭毒也。女劳复者，热病新瘥后交感而得。其证发热烦躁，少腹阴囊牵引而痛，以前病余热未除，阴精复损，故有是证。月水乃阴中有阳之物，能补阴除热，故主之也。金疮及虎狼伤疮，皆血分受伤为病，以类相从，乃所以补其不足也。童女首经，名红铅，能回垂绝之阳气，第一时难得耳。如女子自受胎时，算至十四岁足，即于是日是时经至者，此为正鼎，其经为上药。用法招摄，于经将至时，真气先到，采入身中，名得大药，可以接命。即《首楞经》所载精仙是也。绝非入炉交感，亦非情想得通，故亦成仙道耳。\n\n【主治参与】\n扁鹊方：丈夫热病后，交接复发，忽卵缩入腹，腹痛欲死。烧女人月经赤衣为末，热水服方寸匕，即定。并治女劳色疸。\n\n《千金方》男子阴疮，因不忌月事行房，阴物溃烂：用室女血衲，瓦上烧存性，研末，麻油调傅。\n\n《博物志》：交广夷人，以焦铜和毒药于箭镞上，中人即沸烂，须臾骨坏而死。但服月水、屎汁解之。\n\n【简误】\n         月水虽能治病，然秽污不洁之物，故女子入月时，人宜远之。其升丹煎膏治药，及小儿出痘，切须避忌。如犯之，则药不灵，痘变坏也。红铅，其性质乃阳气凝结而成，火盛人不宜单服，须多服人乳，并入童溺乃佳。","videoMemo":"","fangList":[],"bieMing":"妇人月水"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '8、妇人月水', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fIVRkrHC34Q', 4, '{"title":"第400106507条・卷之十五_人部","description":"<p>7、溺白垽</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106507,"note":"     疗鼻衄，汤火灼疮。\n \n     疏：溺白垽，即人中白，乃人溺之积气结成。其味咸，气凉，无毒，能泻肝、肾、三焦、膀胱有余之火。本经疗鼻衄。及大明治传尸劳热，肺痿，心膈热，吐血，羸瘦，渴疾者，以其能入诸经泻去火邪也。凉能除热，故又治汤火灼疮。今人以之治口舌生疮，疳䘌等证，多效，是其除热降火之验也。\n\n【主治参与】\n同冰片、硼砂、青黛、黄檗、牙硝、白矾，治口舌生疮，及小儿走马牙疳口臭。\n\n《经验方》鼻衄不止：人中白焙干，入麝香少许，温酒调服，立效。\n\n又方，小儿口疳：人中白煅，黄檗蜜炙焦，为末，等分，入冰片少许，以青布拭净，掺之，累效。\n","videoMemo":"","fangList":[],"bieMing":"溺白垽"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '7、溺白垽', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k5JIXupyKxj', 4, '{"title":"第400106506条・卷之十五_人部","description":"<p>6、人溺</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106506,"note":"     疗寒热头疼温气。童男者尤良。\n\n     疏：人溺，乃津液之浊者，渗入膀胱而出。其味咸，气寒无毒，为除劳热骨蒸，咳嗽吐血，及妇人产后血晕闷绝之圣药。晋・褚澄《劳极论》云：降火甚速，降血甚神，饮溲溺百不一死，服凉药百不一生。言其功力之优胜也。《经》云：饮入于胃，游溢精气，上输于脾，脾气散精，上归于肺，通调水道，下输膀胱。故人服小便入胃，亦随脾之气上归于肺，下通水道而入膀胱，乃循其旧路也。故能治肺病引火下行。凡人精气，清者为血，浊者为气，浊之清者为津液，清之浊者为小便，与血同类也。故其味咸而走血，咸寒能伏虚热，使火不上炎而血不妄溢，是以能疗诸血证也。苏恭：主久嗽上气，失声。及日华子止劳渴，润心肺，疗血闷热狂，扑损瘀血在内晕绝，止吐血，鼻衄，皮肤皴裂，难产，胞衣不下诸证，悉由此故。本经主寒热头疼温气者，咸寒能除邪热故耳。法当热饮，热则于中尚有真气在，其行自速，冷则惟存咸味、寒性矣。\n\n【主治参与】\n同枇杷叶、天门冬、麦门冬、苏子、桑白皮、沙参、五味子、生地黄、款冬花、百部，治阴虚咳嗽声哑，喉间血腥气。\n\n同苏木、番降香、续断、牛膝、牡丹皮、蒲黄，治内伤吐血，或瘀血停留作痛。\n\n同泽兰、荆芥、白芷、续断、延胡索、牛膝、苏木、黑豆，治产后血晕，虚者加人参。\n\n凡产后温饮一杯，可免血晕，至三日后止之。\n\n中暍昏倒，以热小便灌下即活。\n\n《圣济总录》头痛至极：童便一盏，豉心半合，同煎至五分，温服。\n\n孟诜《必效方》骨蒸发热：童便五升，煎取一升，以蜜三匙和之。每服二碗，半日更服。此后常服自己小便，轻者二十日，重者五十日瘥。\n\n《圣惠方》绞肠痧痛：童便乘热服之，即瘥。\n\n仲景方：中暑昏闷，夏月在途中热死，急移阴处，就掬道上热土，拥脐上作窝，令人溺满，暖气透脐即苏。乃服地浆、蒜水等药。\n\n《千金方》金疮出血不止，饮人尿五升。\n\n《外科发挥》折伤跌扑，童便入少酒饮之，推陈致新，其功甚大。\n\n《千金方》火烧闷绝，不省人事者，新尿顿服二三升良。\n\n《通变要法》人咬手指，瓶盛热尿浸一宿，即愈。\n\n《普济方》赤眼肿痛。自己小便乘热抹洗，即闭目少顷。此以咸寒内有真气，故能退去邪热也。\n\n【简误】\n        人溺滋阴降火，除骨蒸，解劳乏，治诸吐衄，咯血唾血，其效甚速。《褚澄遗书》云：人喉有窍则咳血杀人。喉不停物，毫发芥蒂必咳，血既渗入，愈渗则愈咳，愈咳愈渗，惟饮溲溺则百不一死。若服寒凉则百不一生。其为肺肾有火者必须之物。第其性稍寒，惟不利于脾胃虚寒，或溏泄，及阳虚无火食不消者，咸在所忌。今世人类用秋石，此乃水澄火炼，真元之气尽失，其功不逮童便多矣。况难多服，久服则咸能走血，使血凝泣为病。","videoMemo":"","fangList":[],"bieMing":"人溺"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '6、人溺', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XVVyGGTV8b7', 4, '{"title":"第400106505条・卷之十五_人部","description":"<p>5、人屎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106505,"note":"     寒。主疗时行大热狂走，解诸毒。宜用绝干者，捣末，沸汤沃服之。\n\n      疏：人之五谷入胃，津液上升为气血，糟粕下降而成粪。其本原以化过，但存极苦大寒之气味耳。入足阳明经。《经》曰：阳明实热，则登高而歌，弃衣而走。苦寒能除阳明之热，故疗时行大热狂走也。凡毒必热必辛，苦寒能除辛热，故又主解诸毒也。苏恭云：新者封疔肿，一日根烂。盖疔肿乃风火之毒气结成，得大寒极苦之气，则风火散，根自烂也。今世人又以之治痘疮血热，紫黑倒靥者，殊效。\n粪清：腊月截淡竹，去青皮，塞口，纳粪坑中，积年得汁，甚黑而苦。主天行热狂，热疾，中恶，蕈毒，恶疮，瘟病垂死者，皆瘥，一名黄龙汤，俗名金汁。\n\n人中黄：即多年厕坑中，砖上所凝结黄垽是也。药性治疗大约与人屎同，解胃家热毒有效。\n\n【主治参与】\n《斗门方》热病发狂，奔走似癫，如见鬼神，久不得汗，及不知人事者：以人中黄入大罐内，以泥固济，煅半日，去火毒，研末。新汲水服三钱。未退再服。\n\n寇宗奭《衍义》大热狂渴：干陈人屎，为末，于阴地净黄土中作五六寸小坑，将末三两匙于坑中，以新汲水调匀，良久澄清，细细与饮，即解。\n\n《儒门事亲》四灵无价散：治痘疮黑陷，腹胀危笃者，此为劫剂。用人粪、猫粪、猪犬粪等分，腊月初旬收埋高燥黄土窖内，至春取出，砂罐盛之，盐泥固济，炭火煅，令烟尽为度。取出为末，入麝香少许，研匀，瓷器密封收之，一岁一字，二岁半钱，三岁一钱，蜜水调下，须臾疮起。\n\n《千金方》疔肿初起：刮破，以热屎傅之，干即易。\n\n又方，五色丹毒：黄龙汤饮二合，并涂之良。\n\n陶弘景：解药箭毒，交广夷人用焦铜为箭镞，更以毒药物汁渍之，射人才伤皮便死。惟饮粪汁即解。\n\n【简误】\n       伤寒、温疫，非阳明实热者不宜用。痘疮，非火热郁滞，因而紫黑干陷倒靥者，不宜用，以其苦寒之极耳。","videoMemo":"","fangList":[],"bieMing":"人屎"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '5、人屎', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tw9rZvbWSSX', 4, '{"title":"第400106504条・卷之十五_人部","description":"<p>4、人牙齿</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106504,"note":"    平。除劳，治疟，蛊毒气。入药烧用。\n\n     疏：牙齿者，肾之标，骨之余也。《经》云：男子三八肾气平，而真牙生；五八肾气衰，而齿槁。以肾主骨故也。其味甘咸，气热有小毒。其主除劳治疟者，盖劳乃劳极精气乏绝，肾家亏损所致也。齿牙为肾气所生，以类相从，适还其本，故主之也。疟亦因劳而发，非夏伤暑、秋为疟之比，故亦主之。味甘而咸，所以能解蛊毒气也。今世又以之治痘疮倒靥、乳痈未溃，为必须之药。\n\n【主治参与】\n钱氏《小儿方》痘疹倒靥：人牙烧存性，入麝香少许，温酒服半钱。\n\n闻人规《痘疹论》人牙散：治痘疮方出，为风寒外袭，或变黑，或青紫，此倒靥也。宜温肌发散，使热气复行而斑自出。用人牙不拘多少，瓦罐固济，煅过，出火毒，研末。出不快而黑陷者，獖猪血调下一钱；因误服凉药，血涩倒陷者，入麝香，温酒服之，其效如神。\n\n《肘后方》乳痈未溃：人牙齿烧研，酥调敷之。\n\n《直指方》阴疽不发，头凹沉黯，不疼无热，内服补散不起，用人牙烧过，穿山甲炙，各一分，为末。分作二服，用当归、麻黄煎汤下。外以姜汁和面傅之。\n\n【简误】\n          近世用人牙治痘疮陷伏，称为神品。然一概用之，贻害不浅。夫齿者，肾之标，骨之余也。痘疮则毒自肾出，方长之际，外为风寒秽气所冒，腠理闭塞，血涩不行，毒不能出，或变黑倒靥，宜用此以酒、麝达之，窜入肾经，发出毒气，使热令复行，而疮自红活，盖劫剂也。若伏毒在心，昏冒不省人事，及气虚色白痒塌，不能作脓，热沸紫泡之证，止宜解毒补虚。苟误用此，则郁闷声哑，反成不治之证，可不慎哉！其除劳治疟，本经虽言之，今世亦稀用。","videoMemo":"","fangList":[],"bieMing":"人牙齿"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '4、人牙齿', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6bM9fNBQ3Zp', 4, '{"title":"第400106503条・卷之十五_人部","description":"<p>3、头垢</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106503,"note":"     主淋闭不通。（梳上者，名百齿霜。）\n \n      疏：头垢，头上垢腻也。其性滑润而下走，故本经主淋闭不通，及弘景疗噎疾。其味苦温，能走阳明，故又主劳复，及妇人吹乳也。\n\n【主治参与】\n同白芷、贝母、半夏为丸，酒下。治妇人吹乳。\n\n同山茨菰、橘叶、鼠粪、人爪、蒲公英、柴胡、山豆根、白芷、连翘、贝母、夏枯草、忍冬藤，治乳岩、乳痈，神效。\n\n《类要方》天行热病后劳复：含头垢枣核大一枚，良。\n\n《外台秘要》预防劳复：伤寒初愈，欲令不劳复者，头垢烧研，水丸梧子大，饮服一丸。\n\n《卫生宝鉴》妇人吹乳：百齿霜，以无根水丸梧子大，每服三丸。\n\n数条之外无别用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"头垢"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '3、头垢', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tKHco4C5xUD', 4, '{"title":"第400106502条・卷之十五_人部","description":"<p>2、人乳汁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106502,"note":"     主补五藏，令人肥白悦泽。（《唐本》注：疗目赤痛多泪，解独肝牛肉毒，合豉浓汁饮之，神效。）\n\n      疏：人乳乃阴血所化，生于脾胃，摄于冲任，未受孕则下为月水，既受孕则留而养胎，已产则赤变为白，上为乳汁。此造化玄微之妙，人身转运之神也。其味甘，气平无毒。入心、入肾、入脾、润肺，益寿延年之圣药也。气血之液，故能补五脏，五脏得补，则气血充实而体自肥白悦泽也。《经》曰：目得血而能视。乳为血化，故能疗目赤痛多泪，甘能解毒，故又主解独肝牛肉毒也。\n\n【主治参与】\n《摄生众妙方》接命丹：治男妇气血衰弱，痰火上升，虚损之证；又治中风瘫痪，手足疼痛，不能动履等证。用人乳二杯，香甜白者为佳，以好梨汁一杯，和匀，银石器内顿滚。每日五更一服，能消痰补虚，生血延寿。此以人补人之妙法也。《圣惠方》眼热赤肿：人乳半合，古文钱十文，铜器中磨令变色，稀稠成煎，瓶收，日点数次。或以乳浸黄连，蒸热洗之。\n\n《万氏家抄方》一切虚损劳证，太乙神应丸：人乳一碗，磁器煮干焙燥，牛乳一碗，同前制，杜仲三两，破故纸二两半，白鲜皮、白茯苓、牛膝、当归各二两，黍米金丹一个晒干，即初生儿口中血珠，共为末，蜜丸桐子大。每服一丸，夜间噙化。\n\n【简误】\n       乳属阴，其性凉而滋润，血虚有热，燥渴枯涸者宜之。若脏气虚寒，滑泄不禁，及胃弱不思食，脾虚不磨食，并不宜服。","videoMemo":"","fangList":[],"bieMing":"人乳汁"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2、人乳汁', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yNOCGDJEVU6', 4, '{"title":"第400106501条・卷之十五_人部","description":"<p>1、发髲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106501,"note":"     味苦，温、小寒，无毒。主五癃关格不通，利小便水道，疗小儿痫，大人痉。仍自还神化。合鸡子黄煎之，消为水，疗小儿惊热。（雷斅云：是男子二十已来无疾患，颜色红白，于顶心剪下者。入丸药膏中用，先以苦参水浸一宿，漉出，入瓶子以火煅赤，放冷研用。）\n\n      疏：发者，血之余也。《经》曰：男子八岁，肾气盛，齿更发长。是发因人之血气以为生长荣枯也。故血盛之人则发润而黑，血枯之人则发燥而黄。《本经》用发髲之意，为是故尔。其味苦气温。《别录》小寒，无毒。入手足少阴经。大人痉，小儿惊痫，皆心肝二经血虚而有热也。发为血之余，故能入心、入肝益血。微寒而苦又能泄热，所以疗小儿惊痫及大人痉也。心与小肠为表里，肾与膀胱为表里，心肾有热则二腑亦受病。此药能入心除热，入肾益阴，则水道利，五癃关格俱通矣。是以古人治惊，多用茯苓、琥珀、竹叶之类，取其分利心经之热自小肠出也。日华子主止血闷血晕，金疮伤风，及煎膏长肉消瘀血者，悉取其入心走肝，益血除热之功耳。自还神化之事，未见别方，大抵以火煅之，复化而凝成血质，此即自还神化之谓。是因血而生，复还为血，非神化而何？\n\n       乱发：微温。主咳逆，五淋，大小便不通，小儿惊痫，止血。鼻衄，烧之吹内立已。\n\n       疏：乱发即常人头上堕下者。其气味所主，与发髲相似，第其力稍不及耳。以发髲一时难得，故《别录》重出此条，以便临时取用。疗体实不甚相远也。\n\n【主治参与】\n《和剂局方》肠风黑散：治肠风泻血，用乱发一两半，荆芥二两，槐花、槐角各一两，以上共煅为末。枳壳、甘草各一两半，为末，和前末匀。每服二钱，水一盏，煎七分，空心服，温酒调下亦得。\n\n刘禹锡《传信方》孩子热疮：乱发一团如梨子大，鸡子黄十个煮熟，同于铫子内熬至甚干，始有液出，旋置盏中，液尽为度。用敷疮上，外即以苦参粉掺之，神效。\n\n又方，小儿断脐，即用清油调发灰傅之，不可伤水。脐湿不干，亦傅之效。\n\n《千金方》小儿惊啼：乱油发烧研，乳汁或酒服少许，良。\n\n《圣惠方》鼻血不止：血发烧灰，吹之。\n\n又方，诸窍出血：头发、败棕、陈莲蓬，并烧灰，等分。每服三钱，童便、温酒调下。\n\n《妇人良方》女人漏血：乱发洗净，烧研，空心温酒服一钱。\n\n入诸膏药内，能消毒止痛，长肉生肌。\n\n《肘后方》女劳黄疸，膏发煎：用猪膏半斤，乱发鸡子大三团，和煎，发消药成矣。分再服，病从小便中出也。\n\n【简误】\n           发灰，走血分而带散。其主诸血证，亦是血见灰则止，取其治标之义居多。若欲全仗其补益，未必能也。经熬煅成末后，气味不佳，胃弱者勿服。入外科药殊有神效。","videoMemo":"","fangList":[],"bieMing":"发髲"}}', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '2024-12-28T02:17:14.000Z', '1、发髲', '2024-12-28T02:17:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'X9TmWkzpwuI');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Urnns765vIT', 4, '{"title":"第400106611条・卷之十六_兽部上品","description":"<p>11、酥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106611,"note":"     微寒。补五脏，利大肠，主口疮。\n\n      疏；酥乃牛乳所出，乳之精华也。其味甘，气微寒无毒。性滑泽。五脏皆属阴，酥乃阴血之精华，故能补五脏。血枯火盛，大肠燥结，乃口舌生疮，甘寒除热补血，故主利大肠、口疮也。\n\n     按：酥酪醍醐，总成于牛乳，但有精粗之别耳。其性大抵皆滋润滑泽，宜于血热枯燥之人。其功不甚相远，故二物不复载。\n\n【主治参与】\n       凡一切药，用酥炙者，取其润燥兼能益精髓，补血脉，又有渗入骨肉，使骨易糜之功。《外台秘要》；一切肺病咳嗽，脓血不止。用好酥五十斤，炼三遍，当出醍醐。每服一合，日三服，以瘥为度，神效。\n\n【简误】\n性能利窍，骤食之使人遗精。","videoMemo":"","fangList":[],"bieMing":"酥"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '11、酥', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MsRzuRex3gz', 4, '{"title":"第400106610条・卷之十六_兽部上品","description":"<p>10、乳腐</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106610,"note":"      味甘，微寒，无毒，主润五脏，利大小便，益十二经脉。\n\n      疏：牛乳，乃牛之血液所化，其味甘，其气微寒，无毒，甘寒。能养血脉，滋润五脏，故主补虚羸止渴。及乳腐所主皆同也。日华子主养心肺，解热毒，润皮肤者，亦此意耳。\n\n      肝：味苦、甘，气和平，食之能补肝，治雀盲。\n\n【主治参与】\n同人乳、羊乳、梨汁、芦根汁、蔗浆，熬膏，治反胃噎膈，大便燥结。宜时时饮之，兼能止消渴。\n\n夏子益《奇疾方》肉人怪病：人顶生疮，五色如樱桃状，破则自顶分裂，连皮剥脱至足，名曰肉人。常饮牛乳自消。\n\n【简误】\n        患冷气人忌之，与酸物相反，令人腹中癥结。脾胃作泄者，亦不得服。","videoMemo":"","fangList":[],"bieMing":"乳腐"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '10、乳腐', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XjVJQE4sFpH', 4, '{"title":"第400106609条・卷之十六_兽部上品","description":"<p>9、牛乳</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106609,"note":"     微寒。补虚羸，止渴。\n\n      酥   微寒。补五脏，利大肠，主口疮。\n\n     疏：酥乃牛乳所出，乳之精华也。其味甘，气微寒无毒，性滑泽。五脏皆属阴，酥乃阴血之精华，故能补五脏。血枯火盛，大肠燥结，乃口舌生疮，甘寒除热补血，故主利大肠、口疮也。\n\n按：酥酪醍醐，总成于牛乳，但有精粗之别耳。其性大抵皆滋润滑泽，宜于血热枯燥之人。其功不甚相远，故二物不复载。\n\n【主治参与】\n       凡一切药用酥炙者，取其润燥兼能益精髓，补血脉，又有渗入骨肉，使骨易糜之功。\n\n《外台秘要》一切肺病咳嗽，脓血不止。用好酥五十斤，炼三遍，当出醍醐。每服一合，日三服，以瘥为度，神效。\n\n【简误】\n    性能利窍，骤食之使人遗精。","videoMemo":"","fangList":[],"bieMing":"牛乳"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '9、牛乳', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2mbi23vi47D', 4, '{"title":"第400106608条・卷之十六_兽部上品","description":"<p>8、阿胶,傅致胶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106608,"note":"      味甘，平、微温，无毒。主心腹内崩，劳极洒洒如疟状，腰腹痛，四肢酸疼，女子下血，安胎，丈夫小腹痛，虚劳羸瘦，阴气不足，脚酸不能久立，养肝气。久服轻身益气。一名傅致胶。（得火良，薯蓣为之使。畏大黄。凡用以蛤粉炒，或酒化成膏亦得。）\n\n       疏：阿胶，旧云煮牛皮作之。藏器与苏颂皆云是乌驴皮，其说为的。其功专在于水。按阿井在山东兖州府东阿县，乃济水之伏者所注，其水清而重，其色正绿，其性趋下而纯阴，与众水大别。\n\n   《本经》味甘气平。《别录》微温无毒。元素云：性平味淡。气味俱薄。可升可降，阳中阴也。入手太阴，足少阴、厥阴经。其主女子下血，腹内崩，劳极洒洒如疟状，腰腹痛，四肢酸疼，胎不安，及丈夫少腹痛，虚劳羸瘦，阴气不足，脚酸不能久立等证。皆由于精血虚，肝肾不足，法当补肝益血。\n\n     《经》曰：精不足者，补之以味。味者，阴也。补精以阴，求其属也。此药得水气之阴，具补阴之味，俾入二经而得所养，故能疗如上诸证也。血虚则肝无以养，益阴补血，故能养肝气。入肺肾补不足，故又能益气，以肺主气，肾纳气也。气血两足，所以能轻身也。今世以之疗吐血、衄血、血淋、尿血、肠风下血、血痢、女子血气痛、血枯、崩中、带下、胎前产后诸疾，及虚劳咳嗽。肺痿，肺痈脓血杂出等证神效者，皆取其入肺入肾，益阴滋水，补血清热之功也。\n\n【主治参与】\n同天、麦门冬、栝楼根、白药子、五味子、桑白皮、剪草、生地黄、枸杞子、百部、苏子、白芍药，治肺肾俱虚，咳嗽吐血。\n\n同杜仲、枸杞子、白芍药、山药、麦门冬、地黄、黄耆、人参、青蒿、续断、黄檗，治妇人崩中漏血。\n\n同白芍药、炙甘草、麦冬、地黄、白胶、当归、枸杞子、杜仲、续断，治妇人胎痛，或胎漏下血。\n\n《直指方》老人虚秘：阿胶炒二钱，葱白三根，水煎化，入蜜二匙，温服。\n\n仲景方：黄连阿胶汤，治少阴病，得之二三日以上，心中烦，不得卧者。用阿胶三两，黄连四两，黄芩一两，芍药二两，鸡子黄二枚，以水五升，先煮三物，取二升，去滓，内胶烊尽，小冷，内鸡子黄，搅令相得。温服七合，日三。《和剂局方》治肠胃气虚，冷热不调，下痢赤白，里急后重腹痛，小便不利，用阿胶二两炒，黄连三两，茯苓二两，为末，捣丸梧子大。每服五十丸，米汤下，日三。\n\n《千金翼》吐血不止：阿胶炒二两，蒲黄六合，生地黄三两，水五升，煮三升，分服。兼治衄血。\n\n《梅师方》妊娠下血不止：阿胶三两炙为末，酒一升煎化，服即愈。\n\n《产宝方》胶艾汤：妊娠胎动，阿胶、艾叶各二两，葱白一升，水四升，煮一升，分服。\n\n【简误】\n      此药多伪造，皆杂以牛马皮、旧革鞍靴之类，其气浊秽，不堪入药。当以光如瑿漆，色带油绿者为真。真者折之即断，亦不作臭气，夏月亦不甚湿软。如入调经丸药中，宜入醋，重汤顿化和药。其气味虽和平，然性粘腻，胃弱作呕吐者，勿服。脾虚食不消者，亦忌之。","videoMemo":"","fangList":[],"bieMing":"阿胶,傅致胶"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '8、阿胶,傅致胶', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DH5ypzaxi0Y', 4, '{"title":"第400106607条・卷之十六_兽部上品","description":"<p>7、白胶,鹿角胶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106607,"note":"      味甘，平、温，无毒。主伤中，劳绝，腰痛，羸瘦，补中益气，妇人血闭无子，止痛安胎。疗吐血下血，崩中不止，四肢酸疼，多汗淋露，折跌伤损。久服轻身延年。一名鹿角胶。（得火良，畏大黄。）\n\n       疏：白胶是熬鹿角而成，故其味甘，气平。《别录》温，无毒。气薄味厚，降多升少，阳中之阴也。入足厥阴、少阴，手少阴、厥阴经。经曰：劳则喘且汗出，内外皆越，中气耗矣。故凡作劳之人，中气伤绝，四肢作痛多汗，或吐血下血，皆肝心受病。此药味甘气温，入二经而能补益中气，则绝伤和，四肢利，血自止，汗自敛也。折跌伤损，则血瘀而成病，甘温入血通行，又兼补益，故折跌伤损自愈。妇人血闭无子，乃崩中淋露，胎痛不安，腰痛羸瘦者，皆血虚肝肾不足之候。温肝补肾益血，则诸证自退而胎自得所养也。血气生，真阳足，故久服能轻身延年耳。更治尿血，溺精，疮疡肿毒及漏下赤白。妇人久服，能令有子。\n\n【主治参与】\n同牛膝、牡丹皮、麦门冬、地黄、真苏子、郁金、白芍药、当归、童便、续断，治劳伤吐血。\n\n同山茱萸、枸杞子、鹿茸、地黄、麦冬、杜仲、补骨脂、怀山药、车前子、五味子、巴戟天、莲须，治肾虚阳痿，精寒无子。加入当归、紫石英，治妇人血闭，子宫冷，服之受孕。\n\n《外台秘要》虚劳尿精及尿血：白胶二两炙，酒二升，顿和温服。\n\n《肘后方》妊娠卒下血：以酒煮胶二两，消尽顿服。\n\n【简误】\n         鹿乃仙兽，纯阳之物也。其治劳伤羸瘦，益肾添精，暖腰膝，养血脉，强筋骨，助阳道之圣药也。然而肾虚有火者，不宜用，以其偏于补阳也。上焦有痰热，及胃家有火者，不宜用。以其性热复腻滞难化也。凡吐血下血，系阴虚火炽者，概不得服。","videoMemo":"","fangList":[],"bieMing":"白胶,鹿角胶"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '7、白胶,鹿角胶', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NgjOjgmcx8V', 4, '{"title":"第400106606条・卷之十六_兽部上品","description":"<p>6、象胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106606,"note":"       主明目，及治疳，治疮肿。以水化涂之。治口臭，以绵裹少许贴牙根，平旦漱去，数度即瘥。\n\n        疏：象胆，苦寒之物也。入肝脾二经，肝热则目不明。脾家郁热则成疳积，或口臭。苦寒除二经之热，故能主诸证。苦寒凉血解毒，故又能主疮肿也。今世治疳证、痨瘵、传尸多用之，总取其苦寒能杀疳虫痨虫，兼除脏腑一切热结也。\n\n【主治参与】\n同獭肝、芦会、干漆、胡黄连、青黛、鬼臼、丹砂，入滋肾药内，治传尸痨瘵。\n\n《圣济总录》内障目翳：用象胆半两，鲤鱼胆七枚，熊胆一分，牛胆半两，麝香一分，石决明一两，为末，糊丸绿豆大。每茶下十丸，日二。\n\n象皮：其性最易收敛，人以钩刺插入皮中，拔出半日，其疮即合，故入膏散，为长肉合金疮之要药。\n\n【简误】\n       象胆苦寒之极，不利脾胃。凡疳证脾弱者，目","videoMemo":"","fangList":[],"bieMing":"象胆"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '6、象胆', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vHuN2I5F9M9', 4, '{"title":"第400106605条・卷之十六_兽部上品","description":"<p>5、象牙</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106605,"note":"      无毒。主诸铁及杂物入肉，刮取屑，细研，和水傅疮上，立出。\n\n      疏：象牙，本经无气味。日华子云平，《海药》云寒。应是甘寒无毒之物。象性勇猛，而牙善蜕，故能出一切皮肉间有形滞物，如经所言也。又能治邪魅惊悸风痫，及恶疮拔毒，长肉生肌，去漏管等用。\n\n【主治参与】\n同明矾、黄蜡、牛角䚡、铅花、金头蜈蚣、猬皮、猪悬蹄，治通肠漏，能去漏管。\n\n防杨梅结毒，载牛黄条内。\n\n王氏《痘疹方》痘疹不收：象牙屑，铜铫炒黄红色，为末。每服七八分，白汤下。\n\n又方，针箭入肉。象牙末，水和傅之，即出也。\n\n日华子：治小便不通，象牙生煎服之。小便过多，烧灰饮下。","videoMemo":"","fangList":[],"bieMing":"象牙"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '5、象牙', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7Ski5ym8aML', 4, '{"title":"第400106604条・卷之十六_兽部上品","description":"<p>4、熊脂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106604,"note":"       味甘，微寒、微温，无毒。主风痹不仁筋急，五藏腹中积聚，寒热羸瘦，头疡白秃，面皯皰，食饮吐呕。久服强志，不饥，轻身长年。\n\n       疏：《诗》云：惟熊惟罴，男子之祥。取其为阳兽而强力壮毅也。\n\n     《本经》味甘，气微寒。《别录》微温无毒。其主风痹不仁筋急者，盖风为阳邪，熊为阳兽，其气温，能通行经络，其性润，能滋养肝脾，故主之也。滑泽而通行，故主五脏腹中积聚，及食饮吐呕。甘寒而强力，故能主寒热羸瘦，轻身。性润而疏风，故能主头疡白秃，面皯皰也。久服强志，不饥长年，甚言其补虚壮筋骨之功耳。\n\n熊掌，乃八珍之一，食之可御风寒，益气力。肉与脂同功。河间云：熊肉振羸。是因其气有余，以补不足者也。\n\n熊胆   味苦，寒，无毒。疗时气热盛变为黄疸，暑月久痢，疳䘌，心痛疰忤。（《药性论》：小儿五疳，杀虫治恶疮。）\n\n疏：熊胆气味与象胆同。其所主亦相似。时气热盛变为黄疸，热邪在足太阴也。久痢，疳䘌，湿热在手阳明也。心痛疰忤，热邪在手少阴也。入三经而除热邪，故能疗诸证也。极苦而寒，故又能杀虫，治恶疮，点痔。\n\n【主治参与】\n《齐东野语》赤目障翳：熊胆丸以胆少许化开，入片脑一二厘，研匀，点上绝妙。\n\n《圣惠方》小儿鼻蚀：熊胆半分，汤化抹之。\n\n《外台秘要》十年痔疮。熊胆涂之，神效。一切方不及也。或加入片脑少许，以猪胆汁和涂，亦妙。\n\n《保幼大全》诸疳羸瘦：熊胆、使君子末，等分研匀，瓷器蒸溶，蒸饼丸麻子大。每米饮下二十丸。\n\n【简误】\n        凡胆，皆极苦寒而能走肝胆二经，泻有余之热，盖以类相从也。小儿疳积，多致目内生翳障者，以肝脾二脏邪热壅滞，则二脏之气血日虚，闭塞日甚故也。用此泻肝胆脾家之热，则内邪清而外障去矣。如不因疳证而目生翳障，及痘后蒙闭者，多因肝肾两虚，宜滋阴养血清热为急，诸胆皆不得用。有痼疾者，不可食熊肉，令终身不愈。\n","videoMemo":"","fangList":[],"bieMing":"熊脂"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '4、熊脂', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rk75k5l32Cc', 4, '{"title":"第400106603条・卷之十六_兽部上品","description":"<p>3、牛黄</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106603,"note":"     味苦，平，有小毒。主惊痫寒热，热盛狂痉，除邪逐鬼。疗小儿百病，诸痫热口不开，大人狂癫，又堕胎。久服轻身增年，令人不忘。（人参为之使。恶常山。畏牛膝、干漆。）\n\n      疏：牛为土畜，其性甘平，惟食百草，其精华凝结为黄，犹人身之有内丹也。故能解百毒而消痰热，散心火而疗惊痫，为世神物，诸药莫及也。凡牛生黄，则夜视其身有光，皮毛润泽，眼如血色，盖得气之精而形质变化自有异也。或云牛病乃生黄者，非也。\n     \n     《本经》味苦气平。《别录》有小毒。吴普云无毒。然必无毒者为是。入足厥阴、少阳，手少阴经。其主小儿惊痫，寒热热盛口不能开，及大人癫狂痫痉者，皆肝心二经邪热胶痰为病。心热则火自生焰，肝热则木自生风，风火相搏，故发如上等证。此药味苦气凉，入二经而能除热消痰，则风火息，神魂清，诸证自瘳矣。鬼邪侵着，因心虚所致。小儿百病多属胎热，入心养神，除热解毒，故悉主之也。性善通窍，故能堕胎。善除热益心，故能令人不忘。非久服多服之药。其云轻身延年者，盖指病去则身自轻安，而得尽其天年也。\n\n【主治参与】\n同犀角、琥珀、天竺黄、钩藤钩、茯神、真珠、金箔、麝香、丹砂，治小儿惊痫百病。\n\n入外科内服药，能解疔肿痈疽毒。并可入傅药，止痛散毒如神。\n\n同犀角、生地黄、牡丹皮、竹叶、麦门冬，治小儿五色丹毒。\n\n同钟乳石、真珠、猪牙皂角、象牙末、白僵蚕、红铅、片脑、明矾、没药、蛀竹屑、天灵盖，为丸。土茯苓汤下，治结毒有神。\n\n姚和众方：小儿初生三日，去惊邪，辟恶气：以牛黄一豆许，以蜜少许，研匀，绵蘸令儿吮之，一日令尽。\n\n《外台秘要》小儿七日口噤：牛黄为末，以淡竹沥化一字，灌之。更以猪乳滴之。\n\n钱氏《小儿方》初生胎热，或身体黄者，以真牛黄一豆大，入蜜调膏，乳汁化开，时时滴儿口中。兼治腹痛夜啼。\n\n《总微录》小儿热惊，或惊痫嚼舌，迷闷仰目：牛黄一杏仁大，竹沥、姜汁各一合，和匀与服。\n\n又方，小儿积热毛焦，睡语、欲发惊者：牛黄六分，朱砂五钱，同研。以犀角磨汁，调服一钱。\n\n王氏《痘疹方》痘疮黑陷：牛黄二粒，朱砂一分，研末。蜜浸胭脂，取汁调搽，并可内服。\n\n【简误】\n         牛黄，治小儿百病之圣药。盖小儿禀纯阳之气，其病皆胎毒痰热所生，肝心二经所发。此药能化痰除热，清心养肝，有起死回生之力。惟伤乳作泻、脾胃虚寒者，不当用。","videoMemo":"","fangList":[],"bieMing":"牛黄"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '3、牛黄', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UGDVzitcONR', 4, '{"title":"第400106602条・卷之十六_兽部上品","description":"<p>2、麝香</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106602,"note":"       味辛，温，无毒。主辟恶气，杀鬼精物，温疟，蛊毒，痫痉，去三虫，疗诸凶邪鬼气，中恶心腹暴痛，胀急痞满，风毒，妇人难产，堕胎，去面䵴（音孕），目中肤翳。久服除邪，不梦寤魇寐，通神仙。（忌大蒜。）\n\n      疏：陶弘景云：麝常食柏叶，又啖蛇。予以为其香必非因啖蛇而结。\n\n      苏颂乃云：夏月食蛇多，至寒则香满，入春脐内急痛，自以爪剔出。\n    \n      陶云：五月得香，往往有蛇皮骨，岂有食蛇逾一年，而皮骨尚不化者乎？不知麝乃山兽，好食香木芳草，如柏叶之类，故其气聚于脐，而结成是香。或遇蛇亦啖，但不结香耳。如必啖蛇多而后有香，则此药必大毒难近之物，安得味辛气温无毒耶？\n\n      甄权言苦辛，其香芳烈，为通关利窍之上药。凡邪气着人，淹伏不起，则关窍闭塞，辛香走窜，自内达外，则毫毛骨节俱开，邪从此而出。故主辟恶气，杀鬼精物凶邪，蛊毒，温疟，中恶心腹暴痛，胀急痞满，风毒诸证，其主痫痉者，借其气以达于病所也。苦辛能杀虫，故主去三虫。辛温主散，故能去面䵴，及目中肤翳。性能开窍，故主难产堕胎也。走窜之性，而云久服除邪，不梦寤魇寐，通神仙者，凡香皆能辟除恶气而通神明，故有是功能也。\n\n         日华子云：纳子宫，暖水脏，止冷带疾。\n\n        《药性论》主小儿惊痫客杵，蚀一切痈疽脓水。今人又以治中风、中气、中恶、痰厥猝仆。兼入膏药、傅药，皆取其通窍开经络、透肌骨之功耳。\n\n【主治参与】\n同犀角、牛黄、琥珀、龙齿、远志、丹砂、铅丹、金箔、菖蒲、真珠、茯神、天竺黄，治心气虚怯，惊邪癫痫，或梦寐纷纭，鬼交鬼疰，及小儿急惊，大人中恶等证。\n\n同白及、白敛、红白药子、雄黄、乌鸡骨煅、乳香、没药、冰片，为末。傅一切痈疽疔肿，有神。\n\n《济生方》中风不省：麝香二钱，研末，入清油二两，和匀，灌之即苏。\n\n又方，食诸果成积伤脾，作胀气急，用麝香一钱，生桂末一两，饭和丸，绿豆大。大人十五丸，小儿七丸，白汤下。盖果得麝即落，木得桂即枯故也。\n\n夏子益《奇疾方》口内肉球，根如线，五寸余，如钗股，吐出乃能食物，捻之则痛彻心者：麝香一钱，研，水服之，日三，自消。\n\n《续千金方》催生易产：麝香一钱，水研服。\n\n《经验方》鼠咬成疮：麝香封之，妙。并治蚕咬成疮。\n\n【简误】\n      麝香走窜飞扬，内透骨窍脏腑，外彻皮肉及筋。其性能射，故善穿透开散。东垣云：凡风病在骨髓者，用之使风邪得出。若在肌肉，用之反引风入骨。丹溪云：五脏之风，不可用麝香以泻卫气。二公之言，诚得其旨矣。凡似中风，小儿慢脾风，与夫阴阳虚竭，发热，吐血，盗汗，自汗，气虚眩晕，气虚痰热，血虚痿弱，血虚目翳，心虚惊悸，肝虚痫痉，产后血晕，胎前气厥，诸证之属于虚者，法当补益，概勿施用。即如不得已欲借其开通关窍于一时，亦宜少少用之，勿令过剂，苏省开通之后，不可复用矣。孕妇不宜佩带。劳怯人亦忌之。李廷飞云：不可近鼻，有白虫入脑，患癞。久带其香透关，令人成异疾。","videoMemo":"","fangList":[],"bieMing":"麝香"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2、麝香', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7YJyFyExPYI', 4, '{"title":"第400106601条・卷之十六_兽部上品","description":"<p>1、龙骨</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106601,"note":"      味甘，平、微寒，无毒。主心腹鬼疰，精物老魅，咳逆，泄痢脓血，女子漏下，癥瘕坚结，小儿热气惊痫。疗心腹烦满，四肢枯痿，汗出，夜卧自惊，恚怒伏气在心下，不得喘息，肠痈内疽，阴蚀，止汗，缩小便，溺血，养精神，定魂魄，安五藏。\n\n      白龙骨：疗梦寐泄精，小便泄精。\n\n      齿：主小儿、大人惊痫，癫疾狂走，心下结气，不能喘息，诸痉，杀精物，小儿五惊十二痫，身热不可近，大人骨间寒热。又杀蛊毒。（得牛黄、人参良。畏石膏。忌鱼及铁。）\n\n      疏：龙禀阳气以生，而伏于阴，为东方之神，乃阴中之阳，鳞虫之长，神灵之物也。故其骨味甘平，气微寒，无毒。内应乎肝，入足厥阴、少阳、少阴，兼入手少阴、阳明经。神也者，两精相合，阴阳不测之谓也。神则灵，灵则能辟邪恶、蛊毒、魇魅之气，及心腹鬼疰、精物老魅，遇之则散也。咳逆者，阳虚而气不归元也。气得敛摄而归元，则咳逆自止。其性涩以止脱，故能止泄痢脓血，因于大肠虚而久不得止，及女子漏下也。小儿心肝二脏虚则发热，热则发惊痫，惊气入腹则心腹烦满，敛摄二经之神气而平之，以清其热则热气散，而惊痫及心腹烦满皆自除也。肝气贼脾，脾主四肢，故四肢痿枯。肝宁则热退，而脾亦获安，故主之也。汗者，心之液也。心气不收，则汗出。肝心肾三经虚，则神魂不安而自惊，收敛三经之神气，则神魂自安。气得归元，升降利而喘息自平，汗自止也。肝主怒，肝气独盛，则善恚怒。魂返乎肝，则恚怒自除。小肠为心之腑，膀胱为肾之腑，二经之气虚脱，则小便多而不禁。脏气敛则腑亦随之，故能缩小便，及止梦寐泄精，小便泄精，兼主溺血也。其主养精神，定魂魄，安五脏者，乃收摄神魂，闭涩精气之极功也。又主癥瘕坚结，肠痈，内疽，阴蚀者，以其能引所治之药，粘着于所患之处也。\n\n       按：龙骨入心、肾、肠、胃。龙齿单入肝、心。故骨兼有止泻涩精之用，齿惟镇惊安魂魄而已。凡用龙骨，先煎香草汤洗二度，捣粉，绢袋盛之。用燕子一只，去肠肚，安袋于内，悬井上面，一宿取出，研粉。入补肾药中，其效如神。又法：酒浸一宿，焙干，研粉，水飞三度用。如急用，以酒煮焙干。或云：凡入药须水飞过，晒干。每斤用黑豆一斗，煮一伏时，晒干用。否则着人肠胃，晚年作热也。\n\n【主治参与】\n仲景方：同牡蛎，入柴胡、桂枝各汤内，取其收敛浮越之正气，固脱而镇惊。\n\n同远志等分为末，炼蜜丸如梧子大，朱砂为衣。每服三十丸，莲心汤下，治劳心梦遗。\n\n《梅师方》睡即泄精：白龙骨四分，韭子五合，为散。空心酒服方寸匕。\n\n又方泄泻不止：白龙骨、白石脂等分，为末，水丸梧子大。紫苏、木瓜汤下，量大人小儿用。亦治久痢休息。\n\n姚和众方：久痢脱肛，白龙骨粉，扑之。\n\n龙齿同荆芥、泽兰、牡丹皮、苏木、人参、牛膝、红花、蒲黄、当归、童便，治产后恶血扑心，妄语癫狂，如伤害发狂者。切不可认作伤寒治，误则杀人。\n\n同牛黄、犀角、钩藤钩、丹砂、生地黄、茯神、琥珀、金箔、竹沥、天竺黄、苏合香，治大人小儿惊痫癫疾。\n\n【简误】\n         龙骨味涩而主收敛。凡泄痢肠澼，及女子漏下崩中、溺血等证，皆血热积滞为患，法当通利疏泄，不可便用止涩之剂，恐积滞瘀血在内，反能为害也，惟久病虚脱者，不在所忌。","videoMemo":"","fangList":[],"bieMing":"龙骨"}}', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '2024-12-28T03:10:16.000Z', '1、龙骨', '2024-12-28T03:10:16.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'F2cHC2QyXhV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9hffEHfwoYA', 4, '{"title":"第400106724条・卷之十七_兽部中品","description":"<p>24、兔头骨</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106724,"note":"    平，无毒，主头眩痛，癫疾。\n     脑：主涂冻疮。\n     肝：主目暗。\n     肉：味辛，平，无毒。主补中益气。\n\n     疏：兔，属金，得太阴之精，故其性喜望月。兔至秋深时可食者，金气全也。其肉味辛气平无毒。然详其用，味应有甘，气应作凉。《经》曰：里不足者，以甘补之。又曰：热伤气。味甘而气凉，所以能补中益气也。肝为风木之位，太过则摇动撼物。兔属金而头骨在上，尤得气之全，故能平木邪，疗头眩痛、癫疾也。肝开窍于目，兔目不瞬而了然，其肝气足也，故能主目暗。河间云：兔肝明目。因其气有余以补不足也。\n\n    脑：为髓之至精，性温而滑润，故主涂冻疮皲裂，及世人用为催生利胎之圣药也。\n     血：味咸，寒。能凉血活血，解胎中热毒。亦能催生易产。\n     屎：一名明月砂。明目，治目中翳膜，劳瘵，五疳，痔瘘，杀虫，解毒。\n\n【主治参与】\n《博济方》催生散：用腊月兔脑摊纸上，夹匀，阴干，剪作符子，于面上书 “生” 字一个，候产母痛极时，用钗股夹定，灯上烧灰，煎丁香酒调下。\n\n《和剂局方》催生丹：麝香、乳香、母丁香为末，腊月兔脑和丸如芡实大，阴干，密封。每一丸温水下，即时产下。随男女左右手中握药丸，是验。\n\n刘氏《保寿堂方》兔血丸：小儿服之，终身不出痘疮，即出亦稀少。腊月八日，取生兔一只，刺血和荞麦面，少加丹砂、雄黄四五分，候干，丸绿豆大。初生小儿以乳汁化下二三丸。遍身发出红点，是其微验也。但儿长成，常以兔肉啖之尤妙。蔺氏《经验方》痘后目翳：直往山中东西地上，不许回顾，录兔屎二七粒，以雌雄槟榔各一个，同磨，不落地，井水调服。百无一失，其效如神。\n\n【简误】\n       妊娠不宜食兔肉，令子缺唇，且能致产不顺。性寒属阴，阳虚无热者不宜服。多服则损元气，痿阳事。不宜合白鸡、獭肉、姜、橘、芥同食。八月至十月可食，余月伤人神气。","videoMemo":"","fangList":[],"bieMing":"兔头骨"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '24、兔头骨', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VyftYK0TOw9', 4, '{"title":"第400106723条・卷之十七_兽部中品","description":"<p>23、虎骨</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106723,"note":"      主除邪恶气，杀鬼疰毒，止惊悸，主恶疮鼠瘘。头骨尤良。\n\n        疏：虎，西方之兽，山兽之君。属金而性最有力。语云：风从虎者，风，木也；虎，金也。木受金制，焉得不从！故虎啸而风生，自然之道也。所以能治风病挛急，屈伸不便，走疰骨节风毒，惊痫癫疾等证。其性虽死而胫犹矻立不仆，故胫骨治脚膝无力，及手足诸风多效，取以类相从，借其气有余以补不足也。本经无气味。《药性论》云味辛，微热无毒。禀勇猛之气，其味更辛散而通行，故主辟邪恶气，杀鬼疰毒，止惊悸也。恶疮鼠瘘，亦风邪浸淫所致，消散风邪，则恶疮鼠瘘自除矣。\n\n【主治参与】\n同牛膝、木瓜、地黄、山药、山茱萸、黄檗、枸杞子、麦门冬、五味子，治腰脚无力，筋骨疼痛，或痿弱不能步履。同萆薢、独活、防己、苍术、牛膝、何首乌、薏苡仁、木瓜、刺蒺藜，治风寒湿邪着于经络，以致偏痹不仁。同当归、白芍药、炙甘草、续断、牛膝、白胶、麦门冬、地黄，治遍身骨节痛。\n\n《永类钤方》健忘惊悸，预知散：用虎骨酥炙、白龙骨、远志等分为末。每服三钱，生姜汤下，日三。久则令人聪慧。\n\n李绛《兵部手集》虎骨治臂胫疼痛，不计深浅皆效。用虎胫骨二两，酥炙碎，羚羊角屑一两，芍药二两切，以无灰酒浸之，养至七日，秋冬倍之。每日空腹饮一杯。若要速服，即入磁银器中，以火暖养二三日，即可服也。\n\n《圣济总录》历节痛风：虎胫骨炙三两，没药七钱，为末，每服二钱，温酒下，日三。\n\n《小品方》恶犬咬伤，虎骨刮末，水服，并傅之。\n\n【简误】\n        凡血不足以养，以致筋骨疼痛者，宜少用。","videoMemo":"","fangList":[],"bieMing":"虎骨"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '23、虎骨', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QaoC30tXj8o', 4, '{"title":"第400106722条・卷之十七_兽部中品","description":"<p>22、犀角</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106722,"note":"    味苦、酸、咸，寒、微寒，无毒。主百毒蛊疰，邪鬼瘴气，杀钩吻、鸩羽、蛇毒，除邪，不迷惑魇寐，疗伤寒温疫，头痛寒热，诸毒气。久服轻身骏健。（升麻、松脂为之使。恶乌头。忌盐。凡欲作末，先锯屑置入怀中一宿，捣之应手成粉。）\n\n     疏：犀，亦神兽也。故其角之精者名通天，夜视有光，能开水辟邪，禽兽见之皆惊骇辟易。\n\n    《本经》味苦，气寒无毒。《别录》酸咸微寒。李珣大寒。味厚于气，可升可降，阳中之阴也。入足阳明，兼入手少阴经。阳明为水谷之海，无物不受，又口鼻为上下阳明之窍，邪气多从口鼻而入。凡蛊毒鬼瘴，与夫风火邪热气之侵人也，必先入于是经。犀角为阳明经正药，其性神灵而寒，故能除邪鬼，省魇寐。其味苦寒，能散邪热，解诸毒，故主百毒蛊疰，瘴气，杀钩吻、鸩羽、蛇毒，及伤寒温疫头痛寒热等证也。邪热去则心经清明，人自不迷惑，胃亦遂安，而五脏皆得所养，故能令人骏健，及久服轻身也。\n\n      《药性论》主镇心神，解大热，散风毒，治发背痈疽疮肿，疗时疾热如火，烦毒入心，狂言妄语。日华子治心烦，止惊，镇肝，明目。《海药》主风毒攻心，冒燥热闷，小儿麸豆，风热惊痫。孟诜主中恶心痛，中饮食药毒，心风烦闷，中风失音。及今人用治吐血，衄血，下血，伤寒蓄血发狂谵语，发黄，发斑，痘疮稠密，热极黑陷等证，神效。皆取其入胃、入心，散邪清热，凉血解毒之功耳。\n\n【主治参与】\n同鬼臼、麝香、龙齿、茯神、苏合香、沉水香、天灵盖、丹砂、雄黄，能辟鬼疰邪气。\n\n同丹砂、琥珀、金箔、天竺黄、牛黄、钩藤钩、羚羊角、真珠、麝香，治大人小儿风热惊痫。\n\n磨汁，同生地黄、红花子、麦门冬、紫草、白芍药、鼠粘子，治痘疮血热，初见点红艳，壮热口渴，烦躁狂语，多服可保无虞。\n\n磨汁，同郁金、童便、生地黄、麦门冬、炙甘草、白芍药、紫苏子、剪草、丹参、白药子，治吐血，衄血。\n\n犀角地黄汤：治伤寒蓄血发黄，或热盛吐血。\n\n入紫雪丸，治大人小儿颠狂，温疫，盅毒，邪魅，一切烦热为病。\n\n入抱龙丸，治小儿恍惚惊悸，痰涎壅塞。\n\n入至宝丹，治中风不语，中恶气绝，一切神魂恍惚，癫狂扰乱等证。\n\n《圣济总录》吐血不止似鹅鸭肝：用生犀角、桔梗各一两，为末。每酒服二钱。\n\n《广利方》治小儿惊痫不知人，嚼舌仰目者，犀角磨浓汁，服之立效。\n\n钱氏《小儿方》痘疮稠密：生犀角，于涩器中新汲水磨浓汁，冷饮之。\n\n《千金方》瘭疽毒疮，喜着十指，状如代指，根深至肌，能坏筋骨，毒气入脏杀人。宜烧铁烙之，或炙百壮，日饮犀角汁瘥。\n\n《圣惠方》下痢鲜血：犀角、地榆、金银花各一两，升麻五钱，为末，炼蜜丸弹子大。每服一丸，水一升，煎五合，去滓温服。此热毒伏于心经故也。宜加丹砂、滑石末，以金银藤花熬汁煎药，更效。\n\n【简误】\n痘疮，气虚无大热者不宜用。伤寒阴证发躁，因阴寒在内，逼其浮阳失守之火，聚于胸中，上冲咽嗌，故面赤、手温、烦呕、喜饮凉物、食下良久复吐出。惟脉沉细，足冷，虽渴而饮水不多，且复吐出，为异于阳证耳，不宜误用犀角凉剂。妊妇勿多服，能消胎气。","videoMemo":"","fangList":[],"bieMing":"犀角"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '22、犀角', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7dtjK8dfUeq', 4, '{"title":"第400106721条・卷之十七_兽部中品","description":"<p>21、羚羊角</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106721,"note":"     味咸、苦，寒、微寒，无毒。主明目，益气，起阴，去恶血注下，辟蛊毒恶鬼不祥，安心气，常不魇寐。疗伤寒时气寒热，热在肌肤，温风注毒伏在骨间，除邪气惊梦，狂越僻谬，及食噎不通。久服强筋骨，轻身，起阴益气，利丈夫。\n\n      疏：羊，火畜也。而羚羊则属木。《本经》味咸气寒，《别录》苦微寒，无毒。气薄味厚，阳中之阴，降也。入手太阴、少阴，足厥阴经。少阴为君主之官，虚则神明不守，外邪易侵，或蛊毒恶鬼不祥，或邪气魇寐，惊梦狂越僻谬。羚羊性灵能通神灵，逐邪气，心得所养而诸证除矣。其主伤寒时气寒热，热在肌肤，温风注毒伏在骨间者，皆厥阴为病。厥阴为风木之位，风热外邪伤于是经，故见诸证。入肝散邪，则诸证自除。\n\n     《经》曰：壮火食气。又曰：热则骨消筋缓。火热太甚，则阴反不能起，而筋骨软，咸寒入下焦，除邪热则阴自起，气自益，筋骨强，身自轻也。肝热则目不明。肝藏血，热伤血则恶血注下。肝在志为怒，病则烦满气逆，噎塞不通。苦寒能凉血热，下降能平逆气，肝气和而诸证无不瘳矣。\n\n【主治参与】\n同犀角、丹砂、牛黄、琥珀、天竺黄、金箔、茯神、远志、钩藤钩、竹沥，治惊邪靥寐，及癫痫狂乱等疾。\n\n同枸杞子、甘菊花、决明子、谷精草、生地黄、五味子、黄檗、蜜蒙花、木贼草、女贞实，治肝肾虚而有热，以致目昏生翳。\n\n《外台秘要》噎塞不通：羚羊角为细末，饮服方寸匕。\n\n《千金方》产后烦闷汗出，不识人：羚羊角烧末，东流水服方寸匕，未愈再服。\n\n【简误】\n       凡肝心二经，虚而有热者宜之，虚而无热者不宜用。凡用有神羊角，甚长，有二十四节挂痕甚明，内有天生木胎。此角有神，力抵千牛。入药不可单用，须要不拆元对，绳缚，铁剉剉细末，尽处须重重密裹，恐力散也。避风捣筛极细，更研万匝如飞尘后入药，免刮人肠。","videoMemo":"","fangList":[],"bieMing":"羚羊角"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '21、羚羊角', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SmQvEtLAJMq', 4, '{"title":"第400106720条・卷之十七_兽部中品","description":"<p>20、犬肉,狗肉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106720,"note":"      味咸、酸，温。主安五藏，补绝伤，轻身，益气。\n\n       疏：犬，火畜也。其味咸酸，气温无毒。乃脾胃家肉也。五脏皆赖脾胃以养，脾胃得补，故主安五脏，五脏安而身自轻，气血益，绝伤自补矣。\n   \n       日华子主补胃气，壮阳道，暖腰膝，益气力。孟诜主补五劳七伤，益阳事，补血脉，厚肠胃，实下焦，填骨髓者，皆取其温暖脾胃之功，则气血生长，腰肾受庇，阳道壮健而下焦暖也。\n\n【主治参与】\n《乾坤秘韫》戊戌丸：治男子妇人一应诸虚不足，大补元气。用黄童子狗一只，去皮毛肚肠同外肾，于砂锅内，以酒、酢八分，水二升，入地骨皮一斤，前胡、黄耆、肉苁蓉各半斤，同煮一日。去药，再煮一夜，去骨，再煮肉如泥，擂细。入当归末四两，莲肉、苍术末各一斤，山药、菟丝子末各十两，甘草末八两，和杵千下，丸梧子大。每空心酒下六七十丸。\n\n危氏方：痔漏有虫，用熟犬肉蘸蓝汁，空心食，七日效。\n\n【简误】\n        气壮多火，阴虚之人不宜食。凡犬肉不可炙食，令人消渴。妊妇食之，令子无声。热病后食之杀人。道家以犬为地厌，忌食。","videoMemo":"","fangList":[],"bieMing":"犬肉,狗肉"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '20、犬肉,狗肉', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1pvy2f2Pr2K', 4, '{"title":"第400106719条・卷之十七_兽部中品","description":"<p>19、白狗血</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106719,"note":"     味咸，无毒。主癫疾发作。\n\n     疏：癫疾属手少阴，少阴主血，藏神，血虚而神自不宁，故发是证。此物入心补血，以类相从，故主癫疾发作也。\n\n【简误】\n         犬性热，以其禀火土之气，故助阳，阳胜则发热、动火、生痰、发渴。凡病人阴虚内热，多痰多火者，慎勿食之。天行病后，尤为大忌。治痢亦非所宜。","videoMemo":"","fangList":[],"bieMing":"白狗血"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '19、白狗血', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fIGDOM2gnNq', 4, '{"title":"第400106718条・卷之十七_兽部中品","description":"<p>18、黄头骨</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106718,"note":"       主金疮止血。（烧灰，用黄狗者良。余骨烧灰，生肌，敷马疮，及疗诸疮瘘，妒乳，痈肿。）\n\n        疏：狗头骨，本经无气味。察其功用，应是甘咸温之物。咸能入血，甘能补血，温能和血，故主金疮止血也。\n\n【主治参与】\n同血竭、乳香、没药、蚺蛇胆、䗪虫、天灵盖、自然铜，治跌扑损伤有神。临杖时服之护心止痛，杖后服之生肌长肉。\n\n《千金方》治小儿久痢：狗头骨烧灰，白汤服。非久痢虚寒者勿用。\n\n《和剂局方》狗头骨丸：治久痢脐腹㽲痛，所下杂色，昼夜不止；或其人久虚，所下肠垢，谓之恶痢，并能治之。赤石脂、干姜各半两，肉豆蔻煨、附子炮去皮各一两，狗头骨灰一两，为末，醋和丸如桐子大。每服六七十丸，空心米饮下。非阴脏人，及阳虚极者不宜用。\n\n《圣惠方》赤白带下不止者，狗头骨烧存性，为末。每酒服一钱，日三。\n\n《经验方》产后血不定，奔四肢，以狗头骨灰，酒服二钱，甚效。\n\n《卫生易简方》打损接骨，狗头骨灰，热醋调涂伤处，暖卧。\n\n《寿域方》恶疮不愈：狗头骨灰、黄丹等分，敷之。\n\n同白敛等分，为末，生白酒调服五钱，治少腹痈，有神。","videoMemo":"","fangList":[],"bieMing":"黄头骨"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '18、黄头骨', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6YDcyS0bUF6', 4, '{"title":"第400106717条・卷之十七_兽部中品","description":"<p>17、狗阴茎,狗精</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106717,"note":"     味咸，平，无毒。主伤中，阴痿不起，令强热大，生子。除女子带下十二疾。一名狗精，六月上伏取，阴干百日。\n\n      疏：狗阴茎，气味与马阴茎同，其所主亦相似。性专补右肾命门真火，故能令阳道丰隆，精暖盈溢，使人生子也。女子带下十二疾，皆冲任虚寒所致。咸温入下焦，补暖二脉，故亦主之也。\n\n【主治参与】\n         同菟丝子、覆盆子、鱼胶、车前子、巴戟天、肉苁蓉、鹿茸、沙苑蒺藜、山茱萸，能益阳暖精，使人有子。\n\n【简误】\n       阳事易举者忌之。内热多火者勿服。","videoMemo":"","fangList":[],"bieMing":"狗阴茎,狗精"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '17、狗阴茎,狗精', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RpPlJ4AzoXo', 4, '{"title":"第400106716条・卷之十七_兽部中品","description":"<p>16、羊血</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106716,"note":"     主女人中风血虚闷，产后血晕，闷欲绝者。生饮一升即活。\n     \n      疏：血为水化，故其味应咸，气平无毒。女人以血为主，血热则生风，血虚则闷绝，咸平能补血凉血，故主女人血虚中风，及产后血闷欲绝也。性能解丹石毒，如丹砂、水银、汞粉、生银、硇砂、砒霜、硫黄、钟乳、礜石、阳起石等类。凡觉毒发，刺饮一升，即解。凡服地黄、何首乌诸补药者，须忌之。","videoMemo":"","fangList":[],"bieMing":"羊血"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '16、羊血', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OLxSAWDC2PI', 4, '{"title":"第400106715条・卷之十七_兽部中品","description":"<p>15、羊肝</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106715,"note":"     性冷。疗肝风虚热，目赤暗无所见。生食子肝七枚，神效。或切薄片，水浸傅之。\n\n     疏：羊肝补肝，以类相从。肝开窍于目，肝热则目赤痛，失明。补肝除热，所以能明目，及治诸目疾也。\n\n【主治参与】\n      《医镜》翳膜羞明有泪，肝经有热也，用青羊子肝一具，竹刀切，和黄连四两，为丸梧子大。食远茶清下七十丸，日三服。忌铁器、猪肉、冷水。","videoMemo":"","fangList":[],"bieMing":"羊肝"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '15、羊肝', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p7jb4TAOlfv', 4, '{"title":"第400106714条・卷之十七_兽部中品","description":"<p>14、羊肉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106714,"note":"      味甘，大热，无毒。主缓中，字乳余疾，及头脑大风汗出，虚劳寒冷，补中益气，安心止惊。（反半夏、菖蒲。）\n\n       疏：羊得火土之气以生，故其味甘气大热无毒。\n \n    《素问》言苦，亦以其性热属火耳。李杲云：补可去弱，人参、羊肉之属是已。羊肉有形，凡形气痿弱，虚羸不足者宜之。其主字乳余疾者，盖产后大虚，血气暴损，得甘热之物补助阳气，则阴血自长，余疾自除矣。中气虚则心不安，或惊惕；阳气弱则头脑大风汗出。补中则中自缓，故能安心止惊；益气则阳自足，故能疗头脑大风汗出，及虚劳寒冷也。\n\n【主治参与】\n《金匮要略》羊肉汤：治寒劳虚羸，及产后心腹疝痛，用肥羊肉一斤，水一斗，煮汁八升，入当归五两，黄耆八两，生姜六两，煮取二升，分四服。\n\n又方，产后虚羸腹痛，冷气不调，及脑中风汗自出：白羊肉一斤，治如常，调和食之。\n\n《饮膳正要》壮胃健脾：羊肉三斤切，粱米二升同煮，下五味作粥食。\n\n《千金方》损伤青肿，用新羊肉贴之。\n\n【简误】\n         羊肉，味甘，大热。脾胃虚寒，羸瘦气乏者宜之。然天行热病后，温疟、热痢后食之，必致发热难疗。妊妇食之，令子多热。与夫痈肿疮疡，消渴，吐血，嘈杂易饥等证，咸不宜服。又铜器煮食之，男子损阳，女子暴下。物性之异如此，不可不知也。","videoMemo":"","fangList":[],"bieMing":"羊肉"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '14、羊肉', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AkE0eawnbUL', 4, '{"title":"第400106713条・卷之十七_兽部中品","description":"<p>13、羊肾</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106713,"note":"     补肾气，益精髓。\n\n     疏：羊肾，补肾气者，以其类相从，借其气以补其不足也。肾得补则精髓自益矣。\n\n【主治参与】\n        羊肾一对，去脂切，肉苁蓉一两，酒浸一夕，去皮膜，和作羹，加五味食，治劳伤阳虚无力。","videoMemo":"","fangList":[],"bieMing":"羊肾"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '13、羊肾', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N3QMK4WmNe0', 4, '{"title":"第400106712条・卷之十七_兽部中品","description":"<p>12、羖羊角</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106712,"note":"     味咸、苦，温、微寒，无毒。主青盲，明目，杀疥虫，止寒泄，辟恶鬼虎狼，止惊悸，疗百节中结气，风头痛，及蛊毒吐血，妇人产后余痛。久服安心，益气，轻身。取之时勿中湿，湿即有毒。\n\n      疏：羊角，乃肺肝心三经药也。而入肝为正。《本经》咸温。《别录》苦微寒。甄权：大寒。察其功用，应是苦寒居多。非苦寒则不能主青盲，惊悸，杀疥虫，及风头痛，蛊毒吐血也。盖青盲，肝热也；惊悸，心热也；疥虫，湿热也；风头痛，火热上升也；蛊毒吐血，热毒伤血也。苦寒总除诸热，故能疗如上等证也。惊悸平则心自安。热伤气，热除则气自益。其主百节中结气，与妇人产后余痛，亦指血热气壅者而言。《本经》又主止寒泄，及辟恶鬼虎狼，未解其义，俟博物者详之。\n\n【主治参与】\n《子母秘录》产后寒热，心闷胀极，百病：羖羊角烧末，酒服方寸匕。\n\n《普济方》治小儿痫疾，方同上。","videoMemo":"","fangList":[],"bieMing":"羖羊角"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '12、羖羊角', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F3UWahDHUC6', 4, '{"title":"第400106711条・卷之十七_兽部中品","description":"<p>11、牛肉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106711,"note":"      味甘，平，无毒。主安中，益气，养脾胃。\n\n      疏：牛，土畜也。黄，中央正色也。经云：中央色黄，入通于脾。故为益脾胃之药。脾胃得所养则中自安，气自益矣。丹溪朱氏有倒仓法，非为其有吐下之力也。特饮之既满，或上涌下泄尔。此盖借其补以为泻，故积聚去而肠胃得所养，亦奇法也。但病非关肠胃者，不宜服。凡牛病死，及黑身、白头、独肝者，皆不宜服。合猪肉及黍米酒食，并生寸白虫。合韭、薤食，令人热病。合生姜食，损齿。又云：牛乃稼穑之资，不可多杀及食。若以之疗病，则药物甚多。以之供馔核，则肥甘不少。似可无此一物也。好生君子，其念及而力戒之，当有冥福耳。","videoMemo":"","fangList":[],"bieMing":"牛肉"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '11、牛肉', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dudje18s5Ub', 4, '{"title":"第400106710条・卷之十七_兽部中品","description":"<p>10、牛胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106710,"note":"    味苦，大寒无毒。除心腹热，渴利、口焦燥，益目精。可丸药。\n\n     疏：胆，牛食百草，其精华萃于胆，其味苦，其气大寒无毒。《经》云：寒以胜热，苦以泄结。故主心腹热，及渴利、口焦燥也。肝开窍于目，肝热则目睛不明，入肝泄热故益目精也。近世以南星末酿入阴干，治惊风有奇功者，取其苦寒制南星之燥，俾善于豁痰除热耳。\n\n【简误】\n       脾胃虚寒者忌之。目病非风热者，不宜用。","videoMemo":"","fangList":[],"bieMing":"牛胆"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '10、牛胆', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x6NpXi3tm1F', 4, '{"title":"第400106709条・卷之十七_兽部中品","description":"<p>9、牛角䚡</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106709,"note":"     下闭血，瘀血疼痛，女人带下，燔之。味苦，无毒。\n\n      疏：牛角䚡，乃角中嫩骨也。为筋之粹，骨之余。入足厥阴、少阴血分之药。兼入手阳明经。苦能泄，温能通行，故主妇人带下，及闭血瘀血疼痛也。\n\n【主治参与】\n同猪悬蹄、猬皮、金头蜈蚣、蛀竹屑、明矾、白蜡，去漏管。\n\n《近效方》大便下血：黄牛角䚡一具煅末，煮豉汤服二钱，日三。\n\n《塞上方》鼠瘘痔疾：牛角䚡烧灰，酒服方寸匕。","videoMemo":"","fangList":[],"bieMing":"牛角䚡"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '9、牛角䚡', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ewv9klRZBnS', 4, '{"title":"第400106708条・卷之十七_兽部中品","description":"<p>8、鹿肉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106708,"note":"     甘，温。补中，强五藏，益气力。生者疗口僻，割薄之。\n\n     疏：鹿，所食多芳草，其性质芳洁，气味醇和，故其肉味甘，气温无毒，与他肉不同也。性能益脾胃，通血脉，故主补中，强五脏，益气力也。生者疗中风口僻，亦取其有通血脉之功，血脉通则口僻自正也。","videoMemo":"","fangList":[],"bieMing":"鹿肉"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '8、鹿肉', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vlv3aVKFXBH', 4, '{"title":"第400106707条・卷之十七_兽部中品","description":"<p>7、鹿肾</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106707,"note":"     平。主补肾气。\n\n      疏：鹿性淫，一牡常御百牝，肾气有余故也。故服之能壮阳道，补肾家不足。","videoMemo":"","fangList":[],"bieMing":"鹿肾"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '7、鹿肾', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VXvi1KTgBC6', 4, '{"title":"第400106706条・卷之十七_兽部中品","description":"<p>6、鹿髓</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106706,"note":"     味甘，温。主丈夫女子伤中绝脉，筋急痛，咳逆。以酒和服之良。\n\n     疏：髓者，精血之纯懿，内充以实骨者也。鹿禀纯阳，故其髓味甘，气温，性能补血而润燥，所以主一切血脉不和，如伤中脉绝，筋急痛及咳逆也。日华子：同蜜煮服壮阳道，令人有子。同地黄汁煎膏服，填骨髓，壮筋骨。治呕吐者亦此意也。","videoMemo":"","fangList":[],"bieMing":"鹿髓"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '6、鹿髓', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('550yR8sQw1n', 4, '{"title":"第400106705条・卷之十七_兽部中品","description":"<p>5、鹿角</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106705,"note":"      味咸，无毒。主恶疮痈肿，逐邪恶气，留血在阴中，除小腹血急痛，腰脊痛，折伤恶血，益气。（杜仲为之使。）\n\n       疏：鹿，山兽，属阳。夏至解角者，阴生阳退之象也。麋，泽兽，属阴。冬至解角者，阳生阴退之象也。是以麋茸补阴，鹿茸补阳。角亦如之。凡角初生软嫩者为茸，禀壮健之性，故能峻补肾家真阳之气。熬成白胶，则气味甘缓，能通周身之血脉。生角则味咸，气温，惟散热、行血、消肿、辟恶气而已。咸能入血软坚，温能通行散邪，故主恶疮痈肿，逐邪恶气，及留血在阴中，少腹血急痛，折伤恶血等证也。肝肾虚则为腰脊痛，咸温入肾补肝，故主腰脊痛。气属阳，补阳故又能益气也。日华子云：水磨服，治脱精，尿血，夜梦鬼交。醋磨汁，涂疮疡痈肿热毒。火炙热，熨小儿重舌，鹅口疮。孟诜云：蜜炙研末酒服，轻身，强骨髓，补阳道绝伤。又治妇人梦与鬼交者，酒服一撮，即出鬼精。烧灰治女子胞中余血不尽欲死者，悉取其入血行血，散热消肿，补阳辟邪之意也。\n\n【主治参与】\n《济生方》骨虚劳极，面肿垢黑，脊痛不能久立，血气衰惫，发落齿槁，甚则喜唾：用鹿角屑二两，牛膝一两半，为末，炼蜜丸梧子大。每服五十丸，空心盐汤下。\n\n《肘后方》肾虚腰痛如锥刺，不能动摇：鹿角屑三两，炒黄研末。空心温酒服方寸匕，日三。\n\n《子母秘录》产后腹痛，瘀血不尽者，鹿角烧研，豉汁服方寸匕，日三。并治产后血晕。\n\n《千金方》蹉跌损伤，血瘀骨痛：鹿角末，酒服方寸匕。\n\n濒湖方：痈疖肿痛毒：鹿角尖，磨浓汁涂之。\n\n【简误】\n      无瘀血停留者不得服。阳盛阴虚者忌之。胃火齿痛亦不宜服。","videoMemo":"","fangList":[],"bieMing":"鹿角"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '5、鹿角', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HIr967Nc0hB', 4, '{"title":"第400106704条・卷之十七_兽部中品","description":"<p>4、鹿茸</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106704,"note":"      味甘、酸，温、微温，无毒。主漏下恶血，寒热惊痫，益气，强志，生齿，不老。疗虚劳洒洒如疟，羸瘦，四肢酸疼，腰脊痛，小便利，泄精，溺血，破留血在腹，散石淋，痈肿，骨中热，疽痒。（痒应作疡。凡用取形如分岐马鞍，茸端如玛瑙红玉，破之肌如朽木者最良。先以酥薄涂匀，于烈炎中燎去毛，再炙。）\n\n       疏：鹿茸禀纯阳之质，含生发之气，故其味甘气温。《别录》言酸微温。气薄味厚，阴中之阳也。入手厥阴、少阴，足少阴、厥阴经。妇人冲任脉虚则为漏下恶血，或瘀血在腹，或为石淋；男子肝肾不足则为寒热惊痫，或虚劳洒洒如疟，或羸瘦，四肢酸疼，腰脊痛，或小便数利，泄精溺血。此药走命门、心包络，及肾肝之阴分，补下元真阳，故能主如上诸证，及益气、强志、生齿、不老也。痈肿疽疡，皆荣气不从所致。甘温能通血脉，和腠理，故亦主之。日华子主补男子腰肾虚冷，脚膝无力，夜梦鬼交，精溢自出；女人崩中漏血，赤白带下。炙末，空心酒服方寸匕。\n\n【主治参与】\n同牛膝、杜仲、地黄、山茱萸、补骨脂、巴戟天、山药、肉苁蓉、菟丝子，治肾虚腰痛，及阴痿不起。\n\n《澹寮方》斑龙丸：治诸虚，用鹿茸酥炙，鹿角胶炒成珠，鹿角霜、阳起石煅红醋淬，肉苁蓉酒浸，酸枣仁、柏子仁、黄耆各一两，地黄九蒸八钱，朱砂半钱，各为末，酒糊丸梧子大。每空心酒下五十丸。昔西蜀市中有一道人货之，一名茸珠丹。每醉高歌曰：“尾闾不禁沧海竭，九转灵丹都漫说。唯有斑龙顶上珠，能补玉堂关下穴”。朝野遍传之，即此方也。\n\n《普济方》鹿茸酒：治阳事虚痿，小便频数，面色无光，用嫩鹿茸一两，去毛切片，山药末一两，绢袋裹，置酒瓮中，七日后开瓮，日饮三杯。将茸焙干作丸服。\n\n《本事方》阴虚腰痛，不能反侧：鹿茸、菟丝子各一两，茴香半两，为末，以羊肾二对，和酒煮烂，捣和泥，和丸梧子大，阴干。每服三五十丸。酒下，日三服。\n\n《济生方》室女白带，因冲任虚寒者：鹿茸酒蒸焙二两，金毛狗脊、白敛各一两，为末，用艾煎醋，打米糊丸梧子大。每酒下五十丸，日二服。\n\n“简误” 同白胶。","videoMemo":"","fangList":[],"bieMing":"鹿茸"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '4、鹿茸', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tw4jUHYDTEI', 4, '{"title":"第400106703条・卷之十七_兽部中品","description":"<p>3、白马溺</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106703,"note":"     味辛，微寒。主消渴，破癥坚积聚，男子伏梁积疝，妇人瘕疾。铜器盛饮之。\n\n      疏：白马溺，昔有人与其奴皆患心腹痛病。奴死剖之，得一白鳖，赤眼，仍活。以诸药纳口中，终不死。有人乘白马观之，马尿堕鳖而鳖缩。遂以灌之，即化成水。其人乃服之，疾亦愈。观其气味，不应有如是之功。乃知物性畏忌，各有所制，如刀柄之刈三棱而化为水，正以遇其所制之物故也。本经云气微寒。然详其用，必是微温，味应带咸，辛咸温俱足，所以能疗经所言诸证。\n\n【主治参与】\n《千金方》食髪成瘕，咽中如有虫上下者，白马尿饮之，佳。\n\n《鲍氏方》利骨取牙：白马尿浸茄秆三日，炒，为末，点牙即落。\n\n【简误】\n       无积聚癥瘕者，不得服。胸中虚痞误作伏梁，服之有损。","videoMemo":"","fangList":[],"bieMing":"白马溺"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '3、白马溺', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jCov0R8fkz0', 4, '{"title":"第400106702条・卷之十七_兽部中品","description":"<p>2、马通</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106702,"note":"   微温。主妇人崩中，止渴，及吐、下血，鼻衄，金疮止血。\n\n    疏：白马通，本经虽云微温，然必是苦而凉者。惟其苦凉所以能疗诸血热证，止渴。及孟诜主阴阳易、垂死者，绞汁服也。","videoMemo":"","fangList":[],"bieMing":"马通"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2、马通', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ugFiCVNEdtN', 4, '{"title":"第400106701条・卷之十七_兽部中品","description":"<p>1、白马茎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106701,"note":"     味咸、甘，平，无毒。主伤中，脉绝，阴不起，强志益气，长肌肉肥健，生子，小儿惊痫。阴干百日用。\n\n       疏：马，火畜也。其阴茎又纯阳之物也。故能主男子阴痿，坚强，房中药多用之。《本经》味咸气平，《别录》甘无毒。察其功用，气平应作温。非甘温则不主伤中脉绝，以甘能补血脉，温能通经络故耳。阳衰则阴不起而生长之道绝，咸温走下焦，补助真阳则阴自起，精自暖，故能令人有子也。气属阳，阳得补故能益气。肾藏志，肾气足故能强志。甘温补血脉而助真气，故又能长肌肉肥健也。《别录》又主小儿惊痫者，似非其所长，应是误入耳。凡收当取银色无病白马，春月游牝时，力势正强者。生取阴干百日，用时以铜刀切片，将生羊血拌蒸半日，去血，晒干，剉用。\n\n【主治参与】\n       得肉苁蓉、巴戟天、山茱萸、菟丝子、真阳起石、人参、鹿茸、狗阴茎，作丸。治真阴虚脱，阴痿不起，下元冷惫等证。\n\n【简误】\n       马阴茎，乃纯阳之物也。凡阴虚火盛者，不得服。人但喜其温暖，滋助阳道，少年多欲者，房中术用之，仗其力势，恣欲无节，以致损竭真阴，多成劳瘵，不可不戒也。","videoMemo":"","fangList":[],"bieMing":"白马茎"}}', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '2024-12-28T03:55:50.000Z', '1、白马茎', '2024-12-28T03:55:50.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Fn6MA7mPoDd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yyTcNpdnUcJ', 4, '{"title":"第400106811条・卷之十八_兽部下品","description":"<p>11、腽肭脐,海狗肾</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106811,"note":"      味咸，无毒。主鬼气尸疰，梦与鬼交，鬼魅狐魅，心腹痛，中恶邪气，宿血结块，痃癖羸瘦。（一名海狗肾。雷云：此物多伪者，真者有一对，则两重薄皮裹丸核，其皮上有肉黄毛，三茎共一穴，湿润常如新。或置睡犬旁，其犬忽惊跳若狂者，真也。与水乌龙似，以此别之。凡用酒浸一宿，纸裹炙香，剉或酒煎熟合药。）\n\n      疏：腽肭，海兽也。得水中之阳气，故其味咸无毒。《药性论》大热，李珣甘香美、大温。其味与獭肝相似，第其气倍热耳。所主鬼气尸疰，梦与鬼交，鬼魅狐魅，心腹痛，中恶邪气者，盖因真阳虚则神明不振，幽暗易侵，故诸邪恶缠疰为病。此药专补阳气则阴邪自辟，所以能疗如上等证也。咸能入血软坚，温热能通行消散，故又主宿血结块，及痃癖羸瘦也。近世房术中多用之，以其咸温入肾补虚，暖腰膝，固精气，壮阳道也。\n\n【主治参与】\n同阳起石、肉苁蓉、巴戟天、菟丝子、山茱萸、鹿茸，能壮阳道，益精。\n\n《和剂局方》有腽肭脐丸，治诸虚劳损，鬼疰邪恶，梦与鬼交，精气乏绝等证。\n\n【简误】\n    腽肭脐，性热助阳，为肾气衰竭，精寒痿弱之要药。然而阴虚火炽，强阳不倒，或阳事易举，及骨蒸劳嗽等候，咸在所忌。","videoMemo":"","fangList":[],"bieMing":"腽肭脐,海狗肾"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '11、腽肭脐,海狗肾', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kazhIpq53bT', 4, '{"title":"第400106810条・卷之十八_兽部下品","description":"<p>10、獭肝</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106810,"note":"       味甘，有毒。主鬼疰蛊毒，却鱼鲠，止久嗽，烧服之。\n\n        疏：獭，水中之兽也。本经味甘有毒。《药性论》咸，微热无毒。详其功用，应是咸胜甘劣，微温小毒之物。入肝、入肾之药也。《经》曰：邪之所凑，其气必虚。虚损劳极，则五脏之神俱不安，鬼邪相挟而为病。久嗽者，亦劳极所致，水不胜火，火气上炎，肺为贼邪所干也。咸味润下，俾火气下降，则肺自清。总之，此药能益阴气，补虚损，保劳极，故主如上诸证也。甘咸善于解毒，故又主蛊毒。獭性嗜鱼，故能却鱼鲠也。大抵其功长于治传尸劳，及鬼疰邪恶有效。故张仲景治冷劳有獭肝丸；崔氏治九十种蛊疰传尸，骨蒸伏连殗殜，诸鬼毒疠疾，有獭肝丸，皆妙。\n\n【主治参与】\n同芦荟、牛漆、象胆、青黛、胡黄连、啄木鸟头、狐脾、虎胃、丹砂、天灵盖，治传尸劳，能杀劳虫。\n\n孟诜：尸疰，一门悉患者。獭肝一具，烧，水服方寸匕，日再。\n\n葛洪：尸疰鬼疰，乃是五尸之一，又挟诸鬼邪为害，其病变动，乃有三十六种至九十种。大略使人寒热，沉沉默默，不知病之所苦，而无处不恶。积月累年，淹滞至死。死后传人，乃至灭门。觉有此候，惟以獭肝散服之有效。法如上。\n\n除传尸劳证外无他用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"獭肝"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '10、獭肝', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3Iih3h8iYkQ', 4, '{"title":"第400106809条・卷之十八_兽部下品","description":"<p>9、麋角</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106809,"note":"        甘，无毒。主痹，止血，益气力。\n\n        疏：麋属阴，好游泽畔。其角冬至解者，阳长则阴消之义也。为补左肾真阴不足，虚损劳乏，筋骨腰膝酸痛，一切血液衰少为病。故主止血，益气力，及除痹也。痹虽风寒湿合而成疾，然外邪易入者，由气血先虚，经络因之壅滞，血脉不通故也。麋角入血益阴，荣养经络，故主之也。\n\n茸：功用相同，而补阴之力更胜。\n\n【主治参与】\n《千金方》麋角丸：补心神，安五脏，填骨髓，理腰脚，能久立，聪明耳目，发白更黑，返老还少。麋角取当年新角连脑顶者，不论具数，去尖一大寸截断，于净盆中水浸，每夜换易。软即将出，削去皱皮，以镑镑取白处，至心即止。以清米泔浸两宿，取出曝干。以无灰酒于大瓷器中浸两宿，其药及酒俱入净釜中，初用武火煎一食顷，后以文火微煎如蟹眼，柳木不住手搅，时时添酒，以成膏为度。煎时皆须平旦下手，不得经宿。仍看屑如稀胶，即以牛乳五升，酥一升，以次渐下后项药。另以麋角炙令黄，为末：槟榔、通草、秦艽、肉苁蓉、人参、菟丝子、甘草各一两，为末。将胶再煎一食顷，似稀粥即止火。投诸药末，和匀，约稠粘堪作丸，倾出，众手一时丸梧子大。空腹酒下三十丸，日加一丸，至五十丸为度。日二服，至一百日。忌房事。经一月，腹内诸疾自相驱逐，有微利勿怪。服至二百日，面皱光泽。一年，齿落更生，强记身轻。二年，令人肥饱少食，不老神仙。合时须在净室，勿令阴人、鸡、犬、教子等见。\n\n杨氏《家藏方》二至丸：补虚损，生精血，去风湿，壮筋骨。用鹿角镑细，以真酥一两，无灰酒一升，慢火炒干，取四两；麋角镑细，以真酥二两，米醋一升，慢火炒干，取四两；苍耳子酒浸一宿，焙，半斤；山药、白茯苓、黄耆蜜炙，各四两，当归五两，肉苁蓉酒浸焙，远志、人参、沉香，各二两，五味子一两，通为末，酒煮糯米糊丸梧子大。每服五十丸，温酒、盐汤任下，日二服。\n\n【简误】\n        阳气衰少，虚羸畏寒者勿用。肉多食，令人弱房。","videoMemo":"","fangList":[],"bieMing":"麋角"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '9、麋角', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EmScs1YvIHY', 4, '{"title":"第400106808条・卷之十八_兽部下品","description":"<p>8、猪胰子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106808,"note":"      一名肾脂，生两肾中间，似脂非脂，似肉非肉，乃人物之命门、三焦发原处也。陈藏器主肺痿咳嗽，和枣肉浸酒服。亦能主痃癖羸瘦。苏颂主肺气干胀喘急，润五脏，去皴皰䵟（黑曾）等证。盖是甘寒滑泽之物，甘寒则津液生，滑泽则垢腻去，故主如上诸证也。男子多食损阳，薄大肠。其能专在去垢腻，可用以浣垢衣，俗名猪胰子。\n\n【简误】\n       按猪为食味中常用之物，脏腑肠胃咸无弃焉。然其一身除肚、膏外，余皆有毒发病，人习之而不察也。壮实者，或暂食无害；有疾者，不可不知其忌，故列其害于后。\n\n肉：多食令人虚肥，生痰热。热病后食之复发。不宜与姜同食，食则发大风病。\n\n头肉：有病者食之，生风发疾。\n\n脑：食之损男子阳道，临房不能行事，酒后尤不可食。\n\n血：能败血损阳，服地黄、何首乌诸补药者，尤忌之。多食耗心气，不可合吴茱萸食。\n\n肝：饵药人不可食。合鱼鲙食生痈疽。合鲤鱼肠、子食，伤人神。《延寿书》云：猪临宰，惊气入心，绝气归肝，俱不可多食，必伤人。\n\n脾：孙思邈云：凡六畜脾，人一生莫食之。\n\n肺：不可与白花菜合食，令人气滞发霍乱。八月和饴食，至冬发疽。\n\n肾：久食令人伤肾少子。冬月不可食，损人真气，兼发虚壅。\n\n胰：男子多食损阳。\n\n肠：多食动冷气。\n\n鼻、唇：多食动风。\n\n舌：多食损心。","videoMemo":"","fangList":[],"bieMing":"猪胰子"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '8、猪胰子', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WCQT4Bda6Bq', 4, '{"title":"第400106807条・卷之十八_兽部下品","description":"<p>7、猪脂油,肪膏</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106807,"note":"    主煎诸膏药，解斑猫、芫青毒。\n\n    疏：肪膏即脂油也。味甘寒，性滑泽。能凉血解毒润燥，故主煎诸膏药，及解斑猫、芫青毒也。又能利肠胃，通大小便，能散风热，疗恶疮。\n\n【主治参与】\n《肘后方》膏发煎：治女劳黄疸，见发髲条，兼能治五疸。\n\n万氏方：肺热暴瘖。猪脂油一斤炼过，入白蜜一斤再炼少顷，滤净冷定。不时挑服一匙，即愈。","videoMemo":"","fangList":[],"bieMing":"猪脂油,肪膏"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '7、猪脂油,肪膏', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XQghXbNiWtN', 4, '{"title":"第400106806条・卷之十八_兽部下品","description":"<p>6、猪肚</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106806,"note":"   主补中益气，止渴利。\n\n    疏：猪肚属土，故其味必甘，气微温，无毒。乃猪一身无害之物，为补脾胃之要品。脾胃得补则中气益、利自止矣。日华子主补虚损，苏颂主骨蒸劳热，血脉不行，皆取其补益脾胃则精血自生，虚劳自愈，根本固而五脏皆安也。\n\n【主治参与】\n《普济方》水泻不止，用猪肚一枚煮烂，入平胃散捣丸服效。\n\n仲景方：猪肚黄连丸，治消渴：用雄猪肚一枚，入黄连末五两，栝楼根、白粱米各四两，知母三两，麦门冬二两，缝定蒸熟，捣丸梧子大。每服三十丸，米饮下。\n\n《千金方》温养胎气，胎至九月消息，用猪肚一枚，如常着五味煮食至尽。\n\n又，猪肚丸：黄连一味为细末，量肚大小实之，煮令极烂，捣匀为丸梧子大。治脏毒下血。\n\n又方，治腹胀大，用乌芋去皮，入雄肚，线缝，砂器煮糜，食之，勿入盐。","videoMemo":"","fangList":[],"bieMing":"猪肚"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '6、猪肚', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3SPCBw5lBPD', 4, '{"title":"第400106805条・卷之十八_兽部下品","description":"<p>5、猪肤</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106805,"note":"      仲景治足少阴下利，咽痛，胸满心烦者，有猪肤汤。用猪肤一斤，水一斗，煮五升，取汁，入白蜜一升，白粉五合，熬香，分服。成无己注云：猪，水畜也。其气先入肾，解少阴客热。加白蜜以润燥除烦，白粉以益气断利也。","videoMemo":"","fangList":[],"bieMing":"猪肤"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '5、猪肤', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r688U1FdbCB', 4, '{"title":"第400106804条・卷之十八_兽部下品","description":"<p>4、猪胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106804,"note":"    主伤寒热渴。\n\n     疏：胆，味苦气寒，《经》曰：热淫于内，寒以胜之，苦以泄之。故主伤寒热渴也。\n\n【主治参与】\n仲景胆导法：以猪胆汁和醋少许，灌谷道中，通大便神效。入猪牙皂角细末二分，搅匀更速。盖酸苦益阴，润燥而泻便也。\n\n又治少阴下利不止，厥逆无脉，干呕烦者，以白通汤加猪胆汁主之。使其气相从，无拒格之患。此寒因热用，热因寒用之义也。葱白四茎，干姜一两，生附子一枚，水三升，煮一升，入人尿五合，猪胆汁一合，分服。\n\n入雄黄末三四分，蜈蚣末二发，套指缚紧，治天蛇毒，有效。\n\n《梅师方》热病䘌蚀上下：用猪胆汁一枚，醋一合，煎沸服，虫立死。\n\n《外台秘要》汤火伤疮，猪胆调黄檗末，涂之。","videoMemo":"","fangList":[],"bieMing":"猪胆"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '4、猪胆', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aqVRdM75KHk', 4, '{"title":"第400106803条・卷之十八_兽部下品","description":"<p>3、猪肾</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106803,"note":"    冷。和理肾气，通利膀胱。\n\n     疏：猪肾味咸，气冷，能泻肾气，肾虚寒者不宜食。本经主理肾气，乃借其同气以引导之耳。不言补而言理，其意有在矣。肾与膀胱为表里，故复能利膀胱也。今人误认以为补肾，恣意食之，大为差谬。不睹日华子云 “久食令人无子”，孟诜云 “久食令人伤肾”，其非补肾之物明矣。","videoMemo":"","fangList":[],"bieMing":"猪肾"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '3、猪肾', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uiaAcogEjkg', 4, '{"title":"第400106802条・卷之十八_兽部下品","description":"<p>2、猪四足</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106802,"note":"     小寒。主伤挞诸败疮，下乳汁。\n     \n       疏：乳属阳明，阳明脉弱则乳汁不通，能益阳明经气血，故能下乳。伤挞败疮，必血热作痛，气寒而味甘咸，故凉血止痛也。又，煮汤为洗溃疡之要药。\n\n【主治参与】\n《广济方》妇人乳无汁者，以猪蹄四枚，水二斗，煮一斗，去蹄，入土瓜根、通草、漏芦各三两，再煮六升，去滓，内葱白、豉，作粥或羹食之，身体微热有少汗出佳，未通再作。\n\n《梅师方》痈疽发背，乳发初起：母猪蹄一只，通草六分，绵裹煮羹食之。《外科精要》洗痈疽，有猪蹄汤。","videoMemo":"","fangList":[],"bieMing":"猪四足"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2、猪四足', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dALn18Mp2Hw', 4, '{"title":"第400106801条・卷之十八_兽部下品","description":"<p>1、猪悬蹄</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106801,"note":"     主五痔，伏热在肠，肠痈内蚀。\n\n      疏：猪，水畜也。在辰属亥，在卦属坎。其肉气味虽寒，然而多食令人暴肥，性能作湿生痰，易惹风热，殊无利益耳。其悬蹄，乃蹄甲之悬起不着地者。《本经》无气味，然为咸寒无毒之物，入手足阳明经药也。湿热下注则为五痔内蚀，热壅血滞则为肠痈，咸寒能除肠胃之热，故主之也。\n\n【主治参与】\n得牛角䚡、槐角子、蝟皮、象牙末、金头蜈蚣、蛀竹屑、明矾、地榆、青黛、白蜡，治通肠漏，令漏管自出。\n\n钱氏《小儿方》痘后目翳，半年已上者，一月取效。用猪悬蹄三两，瓦瓶固济煅，蝉蜕一两，羚羊角三钱，为末。每岁一字，三岁已上三钱，温水服，日三。","videoMemo":"","fangList":[],"bieMing":"猪悬蹄"}}', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '2024-12-28T06:25:51.000Z', '1、猪悬蹄', '2024-12-28T06:25:51.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'eizu94IGkg9');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B95CyucYYN0', 4, '{"title":"第400106911条・卷之十九_禽部三品","description":"<p>11、白鸽</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106911,"note":"     味咸，平，无毒。肉主辟诸药毒，及人马久患疥。又云：暖，无毒。调精益气，治恶疮疥，并风瘙，白癜，疬疡风。\n\n      疏：白鸽禀水金之气，故其味咸，气平，无毒，肾藏精，肾纳气，肺主皮毛，咸入肾，故能调精益气，平则兼辛入肺，故能主恶疮疥，及白癜疬疡风。凡毒药之性多热，鸽得金水之气，故又能辟诸药毒也。\n\n其屎名左盘龙，亦能主人马疥疮。\n\n【主治参与】\n《食医心镜》治消渴，饮水不知足，用白花鸽，切作小片，以土苏煎，含之咽汁。\n\n《潜江方》预辟痘毒，用白鸽卵一对，入竹筒封，置厕中，半月取出，以卵白和辰砂三钱，丸绿豆大。每服三十丸，豆子饮送下，毒从大小便出也。\n\n《保命集》破伤中风病传入里，用左盘龙、白僵蚕各炒半钱，雄黄一钱，为末，蒸饼丸梧子大。每服十五丸，温酒下，取效。\n\n《圣惠方》头痒生疮：白鸽屎五合，醋煮三沸，杵，傅之，日三上。\n\n又方，头疮白秃：鸽粪研末，先以醋米泔洗净，傅之。\n\n【简误】\n      鸽，本经虽云调精益气，其用只长于去风解毒，然而未必益人。故孟诜云：食多减药力。今世劳怯人多畜养，及煮食之，殊未当也。","videoMemo":"","fangList":[],"bieMing":"白鸽"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '11、白鸽', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vzMmnJqBfQf', 4, '{"title":"第400106910条・卷之十九_禽部三品","description":"<p>10、天鼠屎,夜明沙</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106910,"note":"    味辛，寒，无毒。主面痈肿，皮肤洗洗时痛，腹中血气，破寒热积聚，除惊悸，去面䵟。（一名夜明沙。）\n\n     疏：天鼠夜出，喜食蚊蚋，故其屎中淘出细沙，皆未化蚊蚋眼也。所以今人主明目，治目盲障翳，取其气类相从也。其味辛寒，乃入足厥阴经药。《本经》所主诸证，总属是经所发，取其辛能散内外结滞，寒能除血热气壅故也。然主疗虽多，性有专属。明目之外，余皆可略。\n\n【主治参与】\n《圣惠方》青盲障翳：夜明沙一两，柏叶炙一两，为末，牛胆汁和丸梧子大。每夜卧时，竹叶汤下二十丸。\n\n又方，五疟不止：夜明沙末，每冷茶服一钱，立效。并治胎前疟。\n\n除目疾外，他用甚稀，故不立 “简误”。","videoMemo":"","fangList":[],"bieMing":"天鼠屎,夜明沙"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '10、天鼠屎,夜明沙', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1wBGwZMU5BH', 4, '{"title":"第400106909条・卷之十九_禽部三品","description":"<p>9、雄雀屎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106909,"note":"       疗目痛，决痈疖，女子带下，溺不利，除疝瘕。（一名白丁香，一头尖是雄，两头圆者雌。凡用研细，甘草水浸一宿，焙干用。）\n\n      疏：雀屎，本经无气味。察其所主，应是辛苦温之物，性善消散，故外用疗目痛，决痈疖，内服治带下，溺不利，疝瘕也。苏恭以首生男子乳，研雀屎成泥，点目中弩肉，赤脉贯瞳子者，即消，神效。盖取其辛散拔出火毒之义也。\n\n【主治参与】\n《子母秘录》小儿中风，口噤乳不下：雀屎丸如麻子大，服二丸即愈。\n\n《梅师方》诸痈疖已成脓，不肯决，惧针者，涂雀屎疮头，即易决。\n\n《普济方》喉痹乳蛾：白丁香二十个，以沙糖和作三丸。每以一丸，绵裹含咽，即时遂愈。甚者不过二丸，极有奇效。\n\n【简误】\n        雀肉及卵，阴虚火盛者忌之。不可合李食。妊娠食雀肉饮酒，令子多淫。凡服术人忌之。雀屎疗目痛，非风热外邪者不宜用。女子带下溺不利，属肾虚有火者，并忌之。古方同天雄服，此药性极热，有大毒，非阴脏及真阳虚惫者，慎勿轻饵。","videoMemo":"","fangList":[],"bieMing":"雄雀屎"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '9、雄雀屎', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zaQ6ZOsEnV1', 4, '{"title":"第400106908条・卷之十九_禽部三品","description":"<p>8、雀卵</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106908,"note":"     味酸，温，无毒。主下气。男子阴痿不起，强之令热，多精有子。\n\n       疏：雀属阳，其气温，味酸，其性淫，故能入下焦阴分，能补暖两肾。夫人身两肾，左为肾，右为命门；左属水，为阴；右属火，为阳。天非此火不能生物，人非此火不能有生。又云：阳生则阴长。可见命门真阳之气，乃人身生化之本也。故命门衰败则阴痿，精寒，绝化育之道。\n\n       雀卵性温补，暖命门之阳气，则阴自热而强，精自足而有子也。温主通行，性又走下，故主下气也。弘景云：术家和天雄服之，令茎大不衰。孟诜云：和天雄、菟丝子末为丸，空心酒下五丸，治男子阴痿，女子带下，便溺不利，除疝瘕。以其有温暖命门之功也。肉味甘温，功用不及卵。","videoMemo":"","fangList":[],"bieMing":"雀卵"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '8、雀卵', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zIALzSb7yr7', 4, '{"title":"第400106907条・卷之十九_禽部三品","description":"<p>7、鸡内金,肶胵里黄皮</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106907,"note":"       微寒。主泄利，小便利，遗溺，除热止烦。\n\n        疏：此即肫内黄皮，一名鸡内金是也。肫是鸡之脾，乃消化水谷之所。其气通达大肠、膀胱。二经有热则泄痢遗溺，得微寒之气则热除而泄痢遗溺自愈矣。烦因热而生，热去故烦自止也。今世又以之治诸疳疮多效。\n\n【主治参与】\n《医林集要》小便淋沥，痛不可忍：鸡肫内黄皮五钱，阴干烧存性，作一服，白汤下，立愈。\n\n《子母秘录》鹅口白疮：鸡肫内黄皮，为末，乳服半钱，并可傅之。\n\n《经验方》走马牙疳：鸡肫内黄皮，不落水者五枚，焙存性，枯矾一钱，研细，搽。并治阴头疳蚀。","videoMemo":"","fangList":[],"bieMing":"鸡内金,肶胵里黄皮"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '7、鸡内金,肶胵里黄皮', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7ETypTbHi0Y', 4, '{"title":"第400106906条・卷之十九_禽部三品","description":"<p>6、鸡子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106906,"note":"   主除热火疮，痫痉。\n\n    卵白：微寒，疗目热赤痛，除心下复热，止烦满咳逆，小儿下泄，妇人产难，胞衣不出。醯渍之一宿，疗黄疸，破大烦热。\n\n   疏：鸡子禀生化最初之气，如混沌未分之形。故卵白象天，其气清，其性微寒。卵黄象地，其气浊，其性微温。卵则兼清浊而为体。其味甘，气平无毒。凡痫痉皆火热为病，鸡子之甘，能缓火之标，平即兼凉，能除热，故主痫痉及火疮，并治伤寒少阴咽痛，神效。\n\n【主治参与】\n《医方集成》年深哮喘：鸡子略敲损，浸尿缸中三四日，煮食，能去风痰。\n\n又方，用头生鸡卵七枚，童便浸七日，取出煮熟，每日食一枚，永不出痘。\n\n仲景苦酒汤：治少阴病，咽中伤生疮，痛不能语言，声不出者，用半夏十四枚碎，鸡子一枚去黄，内入半夏、苦酒令满，置刀环中，安火上，令三沸，去滓，少少含咽之。不瘥更作。此方有神效。\n\n《普济方》咽塞生疮，干呕头痛，食不下。法同上，无半夏。\n\n《经验秘方》汤火烧灼：鸡子清和酒调洗，勤洗止痛生肌。\n\n《普济方》涂面驻颜：鸡子一枚，开孔，去黄留白，入金华胭脂，及桑硇少许，纸封，与鸡抱之，俟别卵抱出，以涂面。洗之不落，半年尚红也。\n\n仲景方：治少阴病，得之二三日以上，心中烦，不得卧者，用黄连、黄芩、芍药、阿胶、鸡子黄，先煎三物成，去滓，胶烊尽小冷，鸡子黄搅匀，温服。\n\n刘禹锡《传信方》乱发鸡子膏：治孩子热疮效，见发髲条下。\n\n抱出卵壳：研末，磨障翳。取其蜕脱之义也。苏颂又主伤寒劳复。熬令黄黑，为末，热汤和一合服，取汗出即愈，炒，研细，傅下疳亦妙。卵中白皮，主久咳气结，得麻黄、紫菀和服之立止。","videoMemo":"","fangList":[],"bieMing":"鸡子"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '6、鸡子', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t0Q2UF6rNKT', 4, '{"title":"第400106905条・卷之十九_禽部三品","description":"<p>5、屎白,鸡屎白,鸡矢白</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106905,"note":"    微寒。主消渴，伤寒寒热，破石淋，及转筋，利小便，止遗溺，灭瘢痕。（雄鸡屎乃有白，腊月收之。白鸡乌骨者更良。《素问》作鸡矢。）\n\n      疏：鸡屎白微寒，乃肠胃所出之物，故复能走肠胃治病。《素问》云：心腹满，旦食不能暮食，名为鼓胀。治之以鸡矢醴，一剂知，二剂已。\n \n      王太仆注云：《本草》鸡矢，并不治蛊胀，但能利小便。盖蛊胀皆生于湿热，湿热胀满则小便不利，鸡屎能通利下泄，则湿热从小便而出，蛊胀自愈。故曰治湿不利小便，非其治也。本经主石淋，利小便，止遗溺者，正此意耳。转筋者，血热也。伤寒寒热及消渴者，热在阳明也。瘢痕者，血热壅滞肌肉也。寒能总除诸热，故主之也。日华子炒服，治中风失音痰迷。陈藏器和黑豆炒酒浸服，治贼风风痹。盖风为阳邪，因热而生，鸡屎寒能除热，鸡本与风木之气相通，取其治本从类之义也。\n\n【主治参与】\n《普济方》鸡矢醴：治臌胀，旦食不能暮食，用腊月干鸡矢白半斤，袋盛，以酒醅一斗，渍七日，温服三杯，日三。或为末服二钱亦得。\n\n《积善堂经验方》治一切肚腹四肢肿胀，不拘鼓胀、气胀、湿胀、水胀等，用干鸡矢一升，炒黄，以酒醅三碗，煮一碗，滤汁饮之。少顷腹中气大转动利下，即自脚下皮皱消也。未尽，隔日再作。","videoMemo":"","fangList":[],"bieMing":"鸡矢白,屎白,鸡屎白"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '5、屎白,鸡屎白,鸡矢白', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OEDuZtd7G6W', 4, '{"title":"第400106904条・卷之十九_禽部三品","description":"<p>4、鸡肝</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106904,"note":"     主起阴气。\n     疏：肝，本经主起阴气，性温可知。味甘微苦，入足厥阴、少阴经。今人用以治少儿疳积，眼目不明者，取其导引入肝，气类相感之用也。\n【主治参与】\n同芜荑、使君子、胡黄连、青黛、五谷虫、谷精草、芦荟，治小儿疳热，目生障翳。\n\n《千金方》阴痿不起，用雄鸡肝三具，菟丝子一升，为末，雀卵和丸小豆大。每五六十丸，酒下，日二服。\n","videoMemo":"","fangList":[],"bieMing":"鸡肝"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '4、鸡肝', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e3Afp5n0qH4', 4, '{"title":"第400106903条・卷之十九_禽部三品","description":"<p>3、鸡冠血</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106903,"note":"     主乳难。用三年老雄者，取其阳气充溢也。凡风中血脉则口角僻㖞，冠血咸而走血，透肌肉，故以之治中风口㖞不正，涂颊上效。丹雄鸡为阳禽，冠血乃诸阳之所聚，故能治中恶客忤邪气。高武《痘疹正宗》云：鸡冠血和酒服，发痘最佳，鸡属巽，属风，顶血至清至高故也。\n\n【主治参与】\n《皆效方》对口毒疮：热鸡冠血，频涂之，取散。\n\n《青囊杂纂》中蜈蚣毒，舌胀出口是也。雄鸡冠血，浸舌，并咽之。\n\n《胜金方》诸虫入耳，鸡冠血滴入即出。\n\n【简误】\n       痘疮须分寒热。鸡血性温，天行疮子虚寒者得之，固可资其起发；倘因血热而干枯焦黑者，误用之能更转剧。世人类用鸡血、桑蠹虫发痘，而不分寒热，误也。","videoMemo":"","fangList":[],"bieMing":"鸡冠血"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '3、鸡冠血', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V2NFXzsZMEL', 4, '{"title":"第400106902条・卷之十九_禽部三品","description":"<p>2、乌骨鸡</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106902,"note":"    味甘，平，无毒，主补虚劳羸弱，消渴，中恶鬼击心腹痛，益产妇，治女人崩中带下，一切虚损诸疾。\n\n     疏：乌骨鸡，得水木之精气，其性属阴，能走肝肾血分，补血益阴，则虚劳羸弱可除。阴回热去，则津液自生，渴自止矣。阴平阳秘，表里固密，邪恶之气不得入，心腹和而痛自止，鬼亦不能犯矣。益阴则冲、任、带三脉俱旺，故能除崩中带下，一切虚损诸疾也。古方乌骨鸡丸，治妇人百病者，以其有补虚、益阴、入血分之功也。\n\n【主治参与】\n古方乌骨鸡丸：治妇人产后蓐劳，及阴虚等证。方中半夏、人参，乃立方者之误，宜去之。\n\n用骨一具煅存性，同红药子、白及、白敛、冰片、雄黄、朱砂、乳香、没药，醋、蜜调傅一切痈疽肿毒，神效。\n\n治中恶心腹痛欲死，但杀白乌骨鸡，乘热薄心即瘥。如鬼击卒死，用其热血涂心下亦妙。","videoMemo":"","fangList":[],"bieMing":"乌骨鸡"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2、乌骨鸡', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X16rzTrQdS0', 4, '{"title":"第400106901条・卷之十九_禽部三品","description":"<p>1、诸鸡</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400106901,"note":"     疏：按鸡为阳禽，属木而外应乎风，故在卦为巽，其色虽有丹、白、黄、乌，其种复有乌骨之异，总之性热，补阳起阴，兼有风火之义。惟乌骨者，别是一种，独得水木之精，故主阴虚发热、蓐劳、崩中等证也。\n【简误】\n        鸡，性热动风。凡热病初愈，痈疽未溃，素有风病人，咸忌之。弘景云：小儿五岁以下，食鸡生蛔虫。鸡肉不可合葫、芥、李食，不可合犬肝、犬肾，并令人泄痢。同兔食成痢。同鱼汁食成心瘕。同鲤鱼食成痈疖。同獭肉食成遁尸。同生葱食成虫痔。同糯米食生蛔虫。年久老鸡，脑有大毒，食之能发疔，中其毒发疔者，以玉枢丹丸可解。","videoMemo":"","fangList":[],"bieMing":"诸鸡"}}', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '2024-12-28T07:00:09.000Z', '1、诸鸡', '2024-12-28T07:00:09.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'utO8rBquL06');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3sQLEHNOCr6', 4, '{"title":"第400107015条・卷之二十_虫鱼部上品","description":"<p>15、鲤鱼鳞</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107015,"note":"     主产妇腹痛，烧灰酒服，亦治血气。杂诸药用之。\n\n      疏：鱼鳞得水中之阳气，而鲤鱼鳞则又禀阴极生阳之数，性能入血散滞。入血者，阴之用也；散滞者，阳之用也。故主妇人产后腹痛，及血气不和等证。\n\n【主治参与】\n《和剂局方》乌金散：治产后血迷血晕，败血不止，淋沥不断，脐腹疼痛，及崩中下血过多不止。鲤鱼鳞烧、血竭、百草霜、乱发灰、松墨煅酢淬、延胡索、当归、赤芍药，等分为末。每二钱，温酒下。\n\n《外台秘要》：《古今录》疗鱼鲠骨横喉中，六七日不出，取鲤鱼鳞皮烧作屑，以水服之即出。未出再服。\n\n【简误】\n        六阴已极，阳气初生，故能发热动风，风热病者不宜食。天行病后下痢，及有宿癥者，俱不可食。不宜合犬肉、葵菜食。服天门冬、朱砂人不可食。凡炙鲤鱼，不可使烟入目，损目光，三日内必验也。前《和剂局方》乌金散方内有肉桂、当归、延胡索、赤芍药，皆行血之药，而其所主病内，开载崩中下血过多不止，用之则大误矣。慎之！慎之！","videoMemo":"","fangList":[],"bieMing":"鲤鱼鳞"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '15、鲤鱼鳞', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NXawSgEZoYy', 4, '{"title":"第400107014条・卷之二十_虫鱼部上品","description":"<p>14、鲤鱼肉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107014,"note":"      味甘，主咳逆上气，黄疸，止渴。生者主水肿脚满，下气。\n\n      疏：鲤鱼禀阴极之气，故其鳞三十六。阴极则阳复，故《素问》言鱼热中。其气味虽甘平，然多食能令人发风热也。甘可以缓，故主咳逆上气止渴。阴中有阳，能从其类以导之，故能利小便，使黄疸、水肿、脚气俱消也。河间云：鲤之治水，因其气以相感者是矣。\n\n【主治参与】\n《外台秘要》治水肿，用大鲤一尾，赤小豆一升，水二斗，煮可二升余，滤去滓，顿服尽，当下利，利尽即瘥。并治妊娠水肿有神效。","videoMemo":"","fangList":[],"bieMing":"鲤鱼肉"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '14、鲤鱼肉', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eicgERgm8xX', 4, '{"title":"第400107013条・卷之二十_虫鱼部上品","description":"<p>13、鲤鱼胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107013,"note":"    味苦，寒，无毒。主目热赤痛，青盲，明目。久服强悍益志气。\n\n     疏：凡胆皆苦寒走厥阴，故鲤鱼胆亦主明目，及目热赤痛、青盲也。肝为将军之官，肾为作强之官，二经有热，则虚怯志气衰。苦寒除二经之热，故久服强悍益志气也。","videoMemo":"","fangList":[],"bieMing":"鲤鱼胆"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '13、鲤鱼胆', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S5fcOPThCXj', 4, '{"title":"第400107012条・卷之二十_虫鱼部上品","description":"<p>12、鱓鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107012,"note":"    味甘，大温，无毒。主补中益血，疗沈唇。\n\n     疏：鱓鱼得土中之阳气以生，故其味甘、气大温。甘温俱足，所以能补中益血；甘温能通经脉，疗风邪，故又主沈唇，及今人用之以治口眼㖞斜也。\n\n【主治参与】\n与黄耆同食，能益气力。治火丹赤肿，生鱓血涂之效。\n\n【简误】\n性热而补，凡病属虚热者不宜食。时行病后食之多复。过食动风气，兼令人霍乱。","videoMemo":"","fangList":[],"bieMing":"鱓鱼"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '12、鱓鱼', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3gToCSXkG3n', 4, '{"title":"第400107011条・卷之二十_虫鱼部上品","description":"<p>11、鲫鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107011,"note":"     合莼作羹，主胃弱不下食。作鲙，主久赤白痢。烧灰，涂诸疮，或取猪脂煎用。又主肠痈。\n\n       疏：鲫鱼禀土气以生，故其味甘，其气温，无毒。是以能入胃，治胃弱不下食；入大肠治赤白久痢，肠痈。脾胃主肌肉，甘温能益脾生肌，故主诸疮久不瘥也。藏器主虚羸，大明主温中下气，孟诜云调中益五脏，表其益脾和胃之功也。\n\n【主治参与】\n《百一选方》肠风下血，用活鲫鱼一大尾，去肠留鳞，入五倍子末填满，泥固，煅存性，为末。酒服一钱。一方入白矾末二钱，外以棕包，更以纸裹煨存性，研末。每二钱，米饮下。\n\n《经验方》膈气吐食，用大鲫鱼去肠留鳞，切大蒜片填满腹，纸包十重，泥固，晒半干，炭火煨熟，单取肉用，和平胃散一两，杵丸梧子大，密藏。每服三十丸，米饮下。\n\n【简误】\n       鲫鱼调胃实肠，与病无碍。诸鱼之中，惟此可常食。但不宜与沙糖同食，生疳虫。同芥菜食，成肿疾。同猪肝、鸡肉、雉肉、鹿肉食，生痈疽。同麦门冬食，害人。","videoMemo":"","fangList":[],"bieMing":"鲫鱼"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '11、鲫鱼', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RfdrvfbFQc1', 4, '{"title":"第400107010条・卷之二十_虫鱼部上品","description":"<p>10、蠡鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107010,"note":"      味甘，寒，无毒。主湿痹，面目浮肿，下大水，疗五痔。有疮者不可食，令人瘢白。\n\n        疏：蠡鱼禀北方玄水之精，得中央阴土之气，故其色黑、味甘，气寒无毒。乃益脾除水之要药也。土虚则水泛滥，土坚则水自清。凡治浮肿之药，或专于利水，或专于补脾，其性各自为用，惟蠡鱼色黑象水，能从其类以导横流之势；味甘土化，能补其不足以遂敦阜之性。补泻兼施，故主下大水及湿痹，面目浮肿，有神效也。五痔因湿热所生，水去则湿气自除。今世俗小儿痘后咸食之。然而早食多食，能令皮肤瘢痕皆黑。本草独云：有疮者食之，令人瘢白，非也。孟诜主下大小便，壅塞气，作鲙与脚气、风气人食，良。苏颂主妊娠有水气，并取其除湿下水益脾之功也。\n\n【主治参与】\n同白术、茯苓、橘皮、姜皮，煮食，下水肿大效。\n\n与蒜作鲙食，能去湿下水。\n\n《食医心镜》治十种水气垂死：蠡鱼一斤重者，煮汁和冬瓜、葱白作羹食。\n\n《灵苑方》喉痹将死者，以蠡鱼胆点入少许即瘥。病深者水调灌之。诸鱼胆皆苦。惟此胆甘可食为异耳。\n\n【简误】\n蠡鱼其功专于去湿下水，他用无所长，且多食能发痼疾，不可不知也。","videoMemo":"","fangList":[],"bieMing":"蠡鱼"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '10、蠡鱼', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xpJqappeYd2', 4, '{"title":"第400107009条・卷之二十_虫鱼部上品","description":"<p>9、文蛤</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107009,"note":"     味咸，平，无毒。主恶疮蚀，五痔，咳逆胸痹，腰痛胁急，鼠瘘，大孔出血，崩中漏下。\n\n      疏：文蛤即花蛤，大小背上有斑纹。得阴水之气，故其味咸气平无毒。经曰：硬则气坚，咸以软之。文蛤之咸，能消散上下结气，故主咳逆胸痹，腰痛胁急也。恶疮蚀，五痔，鼠瘘，大孔出血，崩中漏下，皆血热为病，咸平入血除热，故主之也。更能止烦渴，化痰，利小便。\n\n【主治参与】\n仲景方：伤寒在阳，当以汗解，反以冷水噀之或灌之，其热被劫不得去，更益烦热，皮上粟起，欲饮水，反不渴者，文蛤散主之。文蛤五两，为末。每服方寸匕，沸汤下，甚效。\n\n《千金翼》疳蚀口鼻，数日欲尽：文蛤烧灰，以蜡、猪脂和涂之。\n\n【简误】\n       病属邪热痰结者宜之。气虚有寒者，不得用。","videoMemo":"","fangList":[],"bieMing":"文蛤"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '9、文蛤', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KaA62sMv9EJ', 4, '{"title":"第400107008条・卷之二十_虫鱼部上品","description":"<p>8、石决明</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107008,"note":"    味咸，平，无毒。主目障翳痛，青盲。久服益精轻身。（凡用以面裹煨熟，磨去粗皮，捣细如飞面，方堪入药。一名千里光。得龙骨疗泄精。畏旋覆花。）\n\n    疏：石决明得水中之阴气以生，故其味咸，气应寒无毒。乃足厥阴经药也。足厥阴开窍于目，目得血而能视，血虚有热，则青盲赤痛障翳生焉。咸寒入血除热，所以能主诸目疾也。咸寒又能入肾补阴，故久服益精轻身也。研细水飞，主点外障翳。\n\n【主治参与】\n得甘菊花、生地黄、木贼草、谷精草、羚羊角、人爪、蝉蜕、空青、蜜蒙花、决明子、夜明砂，治青盲障翳。\n\n《明目集验方》羞明怕日：用千里光、甘菊花、甘草各二钱，水煎冷服。\n\n《鸿飞集》痘后目翳：用石决明火煅研，谷精草各等分，为细末，以猪肝蘸食。\n\n目疾外，他用甚稀，故无 “简误”。","videoMemo":"","fangList":["石决明"],"bieMing":"石决明"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '8、石决明', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VAzb8JmW52s', 4, '{"title":"第400107007条・卷之二十_虫鱼部上品","description":"<p>7、桑螵蛸</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107007,"note":"    味咸、甘，平，无毒。主伤中，疝瘕，阴痿，益精生子。女子血闭腰痛，通五淋，利小便水道，又疗男子虚损，五藏气微，梦寐失精遗溺。久服益气养神。二月三月采蒸之，当火炙，不尔令人泄。\n\n     疏：桑螵蛸，桑树上螳螂子也。禀秋金之阴气，兼得桑木之津液。《本经》味咸气平，《别录》甘无毒。气薄味厚，阴也。入足少阴、太阳经。人以肾为根本，男子肾经虚损，则五脏气微，或阴痿，梦寐失精遗溺。咸味属水，内合于肾，肾得之而阴气生长，故能愈诸疾及益精生子也。肾与膀胱为表里，肾得所养则膀胱自固，气化则能出，故利水道通五淋也。女子属阴，肝肾用事，疝瘕血闭腰痛，皆二经为病。咸能益阴入血软坚，是以主之。甘能补中，故主伤中益气。肾足则水自上升，克与心交，故能养神也。\n\n【主治参与】\n《外台秘要》虚劳盗汗，遗精白浊：桑螵蛸炙，白龙骨等分，为细末。每服二钱，空心盐汤下。\n\n寇宗奭方：桑螵蛸散：治男子房劳，小便日数十次，如稠米泔，心神恍惚，瘦瘁食减。其药安神魂，定心志，治健忘，补心气，止小便数。用桑螵蛸、远志、龙骨、菖蒲、人参、茯神、当归、龟甲各如法制，\n\n各一两，为末。卧时人参汤调下二钱。\n\n《千金翼》妇人遗尿：桑螵蛸酒炒为末，白汤服二钱。兼治胎前产后遗尿不禁。\n\n【简误】\n       桑螵蛸气味虽咸平，走肾利水道，然得秋时收敛之气，凡失精遗溺，火气太盛者，宜少少用之。","videoMemo":"","fangList":[],"bieMing":"桑螵蛸,桑蜱蛸"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '7、桑螵蛸', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5cb7muO0R1O', 4, '{"title":"第400107006条・卷之二十_虫鱼部上品","description":"<p>6、瑇瑁,玳瑁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107006,"note":"      寒，无毒。主解岭南百药毒。（一名玳瑁。）\n\n      疏：瑇瑁，龟类也。得水中至阴之气，故气寒无毒，而解一切热毒。其性最灵，凡遇饮食有毒，则必自摇动，然须用生者乃灵，死者则不能矣。岭南人善以诸毒药造成蛊，人中之则昏愦闷乱，九窍流血则死。惟用活瑇瑁，刺其血饮，或生者磨浓汁服之可解。日华子主破癥结，消痈肿，止惊痫。陈士良主心风，解烦热，行气血，利大小肠。以其性禀纯阴，气味至寒，故治如是等病也。又能解痘毒，神效。\n\n【主治参与】\n杨氏《产乳方》：解一切蛊毒：生玳瑁磨浓汁，服一盏即消。\n\n《灵苑方》预解痘毒，遇时行痘疹，服此未发内消，已发稀少：用生玳瑁、生犀角，各磨浓汁一合，和匀温服半合，日三，最良。\n\n闻人规《痘疮论》：痘疹黑陷，乃心热血凝也。法同上，加入猪心血少许，紫草汁五匙，和匀温服。\n\n《鸿飞集》：迎风目泪，乃肝肾虚热也，用生玳瑁、羚羊角各一两，石燕一双，为末，每一钱，薄荷汤下，日二服。\n\n【简误】\n痘疮虚寒不起发者，不宜服。","videoMemo":"","fangList":[],"bieMing":"瑇瑁,玳瑁"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '6、瑇瑁,玳瑁', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('80tbYwi0QjG', 4, '{"title":"第400107005条・卷之二十_虫鱼部上品","description":"<p>5、真珠</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107005,"note":"    寒，无毒。主手足皮肤逆胪，镇心，绵裹塞耳主聋，傅面令人润泽好颜色。粉点目中主肤翳障膜。\n\n     疏：珠禀太阴之精气而结，故中秋无月则蚌无胎。其体光明，其性坚硬，大小无定，要以新完未经锁缀者为上。味甘，微咸，气寒，无毒。入手少阴，足厥阴经。心虚有热，则神气浮越；肝虚有热，则目生浮翳障膜。除二经之热，故能镇心去目中障翳也。耳聋本属肾虚有热，所以主之。逆胪者，胪胀也。胸腹胀满气逆，以及于手足皮肤皆肿也。《经》云：诸湿肿满，属脾土。又云：诸腹胀大，皆属于热。此因脾虚有热，兼有积滞所致。真珠味甘，亦能益脾气，寒能除热，体坚能磨积消滞，故主手足皮肤逆胪也。古人未发斯义，所以方书叙论不详，亦为阙略也。珠藏于泽，则川自媚，况涂面，宁不令人润泽好颜色乎？凡小儿惊热风痫，为必须之药。\n\n【主治参与】\n同丹砂、牛黄、犀角、天竺黄、茯神、远志、钩藤钩、琥珀、金箔，治小儿惊痫风热，大人失志癫狂等证。\n\n同炉甘石、龙脑香、白硼砂、空青、人爪，点目能去翳障。\n\n同钟乳石、象牙末、牛黄、冰片、白僵蚕、红铅、天灵盖、蛀竹屑、桦皮灰、没药、明矾，治广疮结毒，及阴蚀疮有奇效。\n\n同人中白、黄檗、青黛、硼砂，和冰片少许，治口疳。加入鸡内金、腻粉治下疳。\n\n《格古论》灰尘迷目，用大珠挹之则消。\n\n《千金方》妇人难产，或胞衣不下：真珠末一两，酒服，立出。\n\n《圣惠方》肝虚目暗：真珠末一两，白蜜二合，鲤鱼胆二枚，和合，铜器煎至减半，新绵滤过，瓶盛，频点取瘥。\n\n痘疮发疔毒方，见谷部豌豆下。\n\n【简误】\n真珠，体最坚硬，研如飞面，方堪服食，不细能伤人脏腑。病不由火热者勿用。","videoMemo":"","fangList":[],"bieMing":"真珠"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '5、真珠', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B2hXY5ECI2b', 4, '{"title":"第400107004条・卷之二十_虫鱼部上品","description":"<p>4、龟甲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107004,"note":"     味咸、甘，平，有毒。主漏下赤白，破癥瘕，痎疟，五痔，阴蚀，湿痹四肢重弱，小儿囟不合，头疮难燥，女子阴疮，惊恚气，心腹痛，不可久立，骨中寒热，伤寒劳复，或肌体寒热欲死，以作汤良。久服轻身不饥，益气资智，亦使人能食。勿令中湿，中湿即有毒。\n\n      疏：介虫三百六十，而龟为之长。禀金水之气。故味咸而甘，气平。其性神灵能变化，凡入药，勿令中湿，中湿则遂其变化之性而成癥瘕于腹中，故言有毒也。气味俱阴，入足少阴经。方家多入补心药用，以心藏神，而龟性有神，借其气以相通，且得水火既济之义，实非补心之正药也。其主骨中寒热，及伤寒劳复，肌体寒热欲死，痎疟者，皆阴虚而邪热为病。\n\n    《经》曰：伤于湿者，下先受之。湿痹四肢重弱，亦肾阴虚而邪气易犯。肾主骨，肾虚则小儿囟门不合。肾为五脏阴中之阴，阴虚则火热偏至，而为惊恚气、心腹痛。此药补肾家之真阴，则火气自降而寒热邪气俱除矣。益阴除热软坚，故主漏下赤白，癥瘕，五痔，阴蚀阴疮，及小儿头疮也。经曰：邪热不杀谷。热去故令人能食，能食则脾胃得所养而能思，思作睿，故资智。久服益气轻身不饥者，除热益阴之功也。\n\n【主治参与】\n丹溪方：补阴丸：用龟下甲酒炙，熟地黄蒸晒，各六两，黄檗、知母各四两，为末，以猪脊髓和丸梧子大。每百丸，空心温酒下。\n\n《摘玄方》治产三五日不下，垂死，及短小女子交骨不开者，用干龟壳一个酥炙，头发一握烧灰，川芎、当归各一两，为末和匀，每服七钱，水煎服。如人行五里许，再一服。生胎、死胎俱下。\n\n【简误】\n      按：龟、鳖二甲，《本经》所主大略相似。今人有喜用鳖甲，恶用龟甲者；有喜用龟甲，恶用鳖甲者，皆一偏之见也。二者咸至阴之物，鳖甲走肝益肾以除热，龟甲通心入肾以滋阴。第鳖甲无毒可多用，龟甲非千年自死者，则有毒。故方书所用曰败龟板者，取其长年则得阴气多，故有益阴之功用耳。若今新剖之甲，断乎有毒，不宜频使用者，不可不详辨也。妊妇不宜用。病人虚而无热者不宜用。凡入药，须研极细，不尔，留滞肠胃能变癥瘕也。","videoMemo":"","fangList":[],"bieMing":"龟甲"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '4、龟甲', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D4F76Ai8C4N', 4, '{"title":"第400107003条・卷之二十_虫鱼部上品","description":"<p>3、牡蛎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107003,"note":"     味咸，平、微寒，无毒。主伤寒寒热，温疟洒洒，惊恚怒气，除拘缓鼠瘘，女子带下赤白，除留热在关节，荣卫虚热去来不定，烦满，止汗，心痛气结，止渴，除老血，涩大小肠，止大小便，疗泄精，喉痹，咳嗽，心胁下痞热。久服强骨节，杀邪鬼，延年。（贝母为之使。得甘草、牛膝、远志、蛇床子良。恶麻黄、细辛、吴茱萸。）\n\n         疏：牡蛎得海气结成，故其味咸平，气微寒无毒。气薄味厚，阴也，降也。入足少阴、厥阴、少阳经。其主伤寒寒热，温疟洒洒，惊恚怒气，留热在关节，去来不定，烦满气结心痛，心胁下痞热等证，皆肝胆二经为病。二经冬受寒邪，则为伤寒寒热。夏伤于暑，则为温疟洒洒。邪伏不出，则热在关节，去来不定。二经邪郁不散，则心胁下痞热。邪热甚，则惊恚怒气，烦满气结心痛。此药味咸气寒，入二经而除寒热邪气，则荣卫通，拘缓和，而诸证无不瘳矣。少阴有热，则女子为带下赤白，男子为泄精，解少阴之热而能敛涩精气，故主之也。咸属水，属阴而润下，善除一切火热为病，故又能止汗止渴，及鼠瘘、喉痹、咳嗽也。老血者，宿血也，咸走血而软坚，所以主之。其性收敛，故能涩大小肠，止大小便利也。肾主骨，入肾益精，则骨节自强。邪本因虚而入，肝肾足则鬼邪自去。人以肾为根本，根本固，则年自延矣。更能止心脾气痛，消疝瘕积块，瘿瘤结核，胁下坚满等证，皆寒能除热，咸能软坚之功也。\n\n【主治参与】\n同生地黄、黄耆、龙眼、五味子、酸枣仁、麦门冬、白芍药、茯神、黄檗、当归，治心肾虚，盗汗。\n\n同黄檗、五味子、地黄、山茱萸、枸杞子、车前子、沙苑蒺藜、连须、杜仲，治梦遗泄精。加牛膝则兼治赤白浊。\n\n同地黄、黄檗、阿胶、木耳、炒黑香附、白芍药、地榆、麦门冬、续断、青蒿、鳖甲、蒲黄，止妇人崩中下血，及赤白带下。\n\n仲景方：同龙骨入柴胡、桂枝各汤内，取其收敛浮越之阳气，固脱而镇惊，更能除胸胁中痞硬。\n\n藏器方：同麻黄根、蛇床子为粉，去阴汗。\n\n《本事方》虚劳盗汗：牡蛎粉、麻黄根、黄耆，等分为末。每服二钱，水煎服。\n\n仲景《金匮玉函方》伤寒传成百合病，如寒无寒，如热无热，欲卧不卧，欲行不行，欲食不食，口苦，小便赤色，得药则吐，变成渴疾，久不瘥者用牡蛎煅二两，栝楼根二两，为细末。每服方寸匕，用米饮调下，日三服。\n\n《古今灵验方》水病囊肿：牡蛎粉二两，干姜炮一两，研细，冷水调稠扫上。须臾囊热如火，干则再上。小便利即愈。一方用葱汁、白面同调。小儿不用干姜。\n\n《经验方》男女瘰疬，用牡蛎粉四两，玄参末三两，甘草一两，面糊丸梧子大。每三十丸，酒下，日三服。服尽除根，不拘已破未破，皆效。\n\n《普济方》月水不止：牡蛎煅，研细，米醋搜成团，再煅，研末，以米醋调艾叶末熬膏，丸梧子大。每用醋汤下四五十丸。\n\n【简误】\n       凡病虚而多热者宜用。虚而有寒者忌之。肾虚无火，精寒自出者非宜。","videoMemo":"","fangList":[],"bieMing":"牡蛎"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '3、牡蛎', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w30ft7prHTJ', 4, '{"title":"第400107002条・卷之二十_虫鱼部上品","description":"<p>2、蜜蜡</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107002,"note":"    味甘，微温，无毒。主下痢脓血，补中，续绝伤、金疮，益气，不饥耐老。\n\n     白蜡：疗久泄澼、后重、见白脓，补绝伤，利小儿。久服轻身不饥。\n\n     疏：蜡，石蜜之凝结于底者也。蜜性缓，质柔，故主润脏腑经络；蜡性涩，质坚，故能疗久痢，泄澼后重，下脓血也。甘能益血补中，温能通行经脉，故主续绝伤及金疮也。中得补则气自益，故久服能不饥轻身耐老也。男子女人，大小内外皆可施。而《别录》独云利小儿者，非也。\n\n【主治参与】\n得象牙末等，能去漏管长肉，见象牙条下。\n\n得腻粉、真珠末、黄檗末、龙脑香、铅丹、蛀竹屑、葱白、猪脊髓，治阴蚀恶疮。\n\n同孩儿茶、铅丹、胡粉、水龙骨粉、霜龙骨、黄檗、猪胆汁、炙猪脂作膏，治内外臁疮久不愈。\n\n《金匮》方：调气饮：治赤白痢，少腹痛不可忍，后重，或面青手足俱变者，用黄蜡三钱，阿胶三钱同溶化，入黄连末五钱，搅匀，分三次热服，神效。\n\n《千金方》胶蜡汤：治热痢，及妇人产后下痢。用蜡二棋子大，阿胶二钱，当归二钱半，黄连三钱，黄檗一钱，陈廪米半升，水三升，煮至一升，去米入药，煎至一钟，温服神效。\n\n【简误】\n       火热暴痢不宜用。","videoMemo":"","fangList":[],"bieMing":"蜜蜡"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2、蜜蜡', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0kHwUGAVa72', 4, '{"title":"第400107001条・卷之二十_虫鱼部上品","description":"<p>1、石蜜</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107001,"note":"      味甘，平，无毒，微温。主心腹邪气，诸惊痫痓（痓作痉）。安五藏诸不足，益气补中，止痛解毒，除众病，和百药，养脾气，除心烦，食饮不下，止肠澼，肌中疼痛，口疮，明耳目。久服强志轻身，不饥不老，延年神仙。\n\n       疏：石蜜，蜂采百花酿成。故《本经》味甘，气平。《别录》微温无毒。得草木群英之精华，合露气以酿成。故其气清和，其味纯甘。施之精神、气血、虚实、寒热、阴阳、内外诸病，罔不相宜。《经》曰：里不足者，以甘补之。甘为土化，土为万物之母。石蜜具天地间至甘之味，故能安五藏诸不足，及益气补中除众病也。心经有热，则为诸惊痫痉，得甘缓之气则心火降，烦热除，诸惊痫痉平矣。诸痛痒疮疡，皆属心火，故又能止肌中疼痛及口疮也。甘主解毒，故能和百药。甘主入脾，故能养脾气。脾气得所养，而饮食自下，肠澼止矣。五脏足，气血充，则耳目聪明，不饥不老，轻身强志，延年神仙所自来矣。\n\n【主治参与】\n同芦根汁、梨汁、人乳、牛羊乳、童便，治噎膈，大便燥结，用此润之。有痰加竹沥。\n\n炼熟和诸丸药及膏子，主润五脏，益血脉，调脾胃，通三焦，涂火灼疮能缓痛。\n\n仲景方：蜜导煎：治阳明病自汗，小便反利，大便鞕者，用蜜二合，铜器中微火熬之，候凝如饴状至可丸，乘热捻作挺，令头锐大如指，长寸半许，候冷，纳谷道中，少顷即通也。一法：加皂角细末二分，搅匀，尤速。\n\n《产书》：产后口渴，用熟蜜不计多少，熟水调服即止。\n\n《全幼心鉴》：痘疹作痒难忌，抓成疮及痂，欲落不落，百花膏主之。用上等石蜜，不拘多少，汤和，时时以翎刷之，效。\n\n《肘后方》：天行虏疮，头面及身须臾周匝，状如火疮，皆戴白浆，随决随生。不即疗，数日必死，瘥后疮瘢黯色，一岁方灭。此恶毒之气深入也。用蜜入升麻煎过，数数拭之。\n\n【简误】\n   石蜜虽称补五脏，益脾胃，然而生者性寒滑，能作泄。大肠气虚完谷不化者，不宜用。呕家、酒家，不宜用。中满蛊胀不宜用。湿热脚气不宜用。生者有小毒，尤不宜食。青赤酸者，食之令人心烦。不可与生葱同食，害人。若与莴苣同食，令人利下。食蜜饱后，不可食鲊，令人暴亡。","videoMemo":"","fangList":[],"bieMing":"石蜜"}}', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '2024-12-28T07:53:25.000Z', '1、石蜜', '2024-12-28T07:53:25.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r99o2vb639e');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dIcisys1USh', 4, '{"title":"第400107117条・卷之二十一_虫鱼部中品","description":"<p>17、鲈鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107117,"note":"      平。补五脏，益筋骨，和肠胃，治水气，多食宜人。\n\n       疏：鲈鱼，秋月方美，其得水中之清气者乎？味甘淡，气平，虽有小毒，不至发病，乃与脾胃相宜之物也。肾主骨，肝主筋，滋味属阴，总归于脏。益二脏之阴气，故能益筋骨。脾胃有病，则五脏无所滋养而积渐流于虚弱。脾弱则水气泛滥，益脾胃则诸证自除矣。\n","videoMemo":"","fangList":[],"bieMing":"鲈鱼"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '17、鲈鱼', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QoRGCXSzCjA', 4, '{"title":"第400107116条・卷之二十一_虫鱼部中品","description":"<p>16、石首鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107116,"note":"     味甘，无毒。头中有石如棋子。主下石淋，磨石服之，亦为灰末服。和莼菜作羹，开胃益气。候干食之名为鲞。炙食之，主消瓜成水，亦主卒腹胀，食不消，暴下痢。\n\n      疏：石首鱼得海中水土之气，故其味甘气平无毒。胃属土，甘为土化，故能开胃。胃气开则饮食增，五脏皆得所养而气自益矣。干鲞其性疏利，故能入肠胃宽中、消食止痢。头中石坚重下走，故主下石淋也。凡泄痢腹痛，与夫肠胃诸疾，最忌油腻鱼腥，惟白鲞不忌。盖鲞饮咸水而性平不热，且无脂腻，不惟少热中之患，更有消食理脾实肠胃之功也。","videoMemo":"","fangList":[],"bieMing":"石首鱼"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '16、石首鱼', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ssNA2Ma4g5W', 4, '{"title":"第400107115条・卷之二十一_虫鱼部中品","description":"<p>15、青鱼胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107115,"note":"     主目暗，滴汁目中，并涂恶疮。\n\n       疏：青鱼胆，色青象木，木气通于肝，肝开窍于目，故能治目暗。味苦气寒，能凉血热，故又主涂恶疮也。\n\n【主治参与】\n龚氏《易简方》治赤目障翳，用黄连熬膏，入大青鱼胆汁和就，再入片脑少许，瓶收密封。每日点之，甚妙。\n\n《龙木论》：一切障翳，鱼胆丸：用青鱼胆、鲤鱼胆、羊胆、牛胆，各半两，熊胆二钱，龙脑香少许，石决明一两，为末，蜜丸梧子大。每空心茶下十丸。\n\n《万氏家抄》乳蛾喉痹：用胆矾盛青鱼胆中，阴干。每用少许，吹喉取吐。\n\n【简误】\n目病非风热盛，而由于血虚昏暗者，不宜用。服术人，不可食青鱼肉。","videoMemo":"","fangList":[],"bieMing":"青鱼胆"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '15、青鱼胆', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yDag1Olx0yY', 4, '{"title":"第400107114条・卷之二十一_虫鱼部中品","description":"<p>14、䗪虫,地鳖</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107114,"note":"     味咸，寒，有毒。主心腹寒热洗洗，血积癥瘕，破坚，下血闭，生子，大良。一名地鳖。\n\n     疏：䗪虫生于下湿土壤之中，故其味咸，气寒。得幽暗之气，故其性有小毒。以刀断之，中有白汁如浆，凑接即连，复能行走，故今人以之治跌扑损伤，续筋骨有奇效。乃足厥阴经药也。夫血者，身中之真阴也。灌溉百骸，周流经络者也。血若凝滞则经络不通，阴阳之用互乖，而寒热洗洗生焉。咸寒能入血软坚，故主心腹血积，癥瘕血闭诸证。血和而荣卫通畅，寒热自除，经脉调匀，月事时至，而令妇人生子也。又治疟母为必用之药。\n\n【主治参与】\n同自然铜、血竭、乳香、没药、五铢钱、黄荆子、麻皮灰、狗头骨，治跌扑损伤神效。\n\n仲景方：大黄䗪虫丸：治产妇腹痛有干血，用䗪虫二十枚去足，桃仁二十枚，大黄二两，为末，炼蜜杵和，分为四丸，每以一丸，酒一升，煮取二合，温服，当下血也。\n\n仲景鳖甲煎丸：治久疟成癖。\n\n董炳《集验方》治跌扑闪挫：用土鳖阴干一个，临时旋研，入乳香、没药、自然铜、龙骨各等分，麝香少许，为末。每服三分，入土鳖末，以酒调下。须先整定骨乃服，否则接挫也。又可代杖。\n\n【简误】\n    无瘀血停留者，不宜用。","videoMemo":"","fangList":[],"bieMing":"䗪虫,地鳖"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '14、䗪虫,地鳖', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RkkNgRKGFdW', 4, '{"title":"第400107113条・卷之二十一_虫鱼部中品","description":"<p>13、蜚虻,虻虫</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107113,"note":"     味苦，微寒，有毒。主逐瘀血，破下血积，坚痞癥瘕，寒热，通利血脉及九窍，女子月水不通，积聚，除贼血在胸腹五脏者，及喉痹结塞。（一名虻虫。）\n\n      疏：蜚虻，其用大略与䗪虫相似，而此则苦胜，苦能泄结；性善啮牛马诸畜血，味应有咸，咸能走血。完素云：虻饮血而用以治血。故主积聚癥瘕，一切血结为病，如经所言也。苦寒又能泄三焦火邪，迫血上壅，闭塞咽喉，故主喉痹结塞也。今人以其有毒，多不用。然仲景抵当汤、丸，大黄䗪虫丸中咸入之，以其散脏腑宿血结积有神效也。凡毒药之治病，如刑罚之治盗贼，不如是则不足以祛邪反正。《书》曰：若药不瞑眩，厥疾不瘳。正此谓也。其与病相乖不宜用者，详著简误中。\n\n【主治参与】\n入大黄䗪虫丸，治虚劳羸瘦，内有干血，肌肤甲错，两目黯黑。\n\n入抵当汤，治太阳病，身黄，脉沉结，小腹硬，小便自利，其人如狂者。\n\n《备急方》扑坠瘀血：虻虫二十枚，牡丹皮一两，为末。酒服方寸匕，血化为水也。\n\n【简误】\n        伤寒发黄，脉沉结，少腹硬，如小便不利者，为无血证，非蓄血也，不宜用。瘀血未审的者，不宜用。女子月水不通，由于脾胃薄弱，肝血枯竭，而非血结闭塞者，不宜用。孕妇腹中有癥瘕积聚不宜用。凡病气血虚甚，形质瘦损者忌之。","videoMemo":"","fangList":[],"bieMing":"蜚虻,虻虫"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '13、蜚虻,虻虫', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ngB4IkXwbMT', 4, '{"title":"第400107112条・卷之二十一_虫鱼部中品","description":"<p>12、蛞蝓,蜗牛</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107112,"note":"     味咸，寒，无毒。主贼风㖞僻，轶筋，及脱肛，惊痫挛缩。\n      蜗牛：味咸，寒。主贼风㖞僻，踠跌，大肠下脱肛，筋急及惊痫。（蛞蝓、蜗牛，《本经》分二条，今按其气味相同，主疗无别，惟形质稍异，故并为一。蜗牛负壳，蛞蝓无壳耳。）\n\n     疏：蛞蝓、蜗牛，禀阴湿之气而生，故味咸气寒无毒。经曰：清静则肉腠闭拒，虽大风苛毒，弗能害也。如阴血亏竭，阳气躁扰，则腠理不密，贼风乘虚而入。风主摇动，中于经络故㖞僻挛缩，轶筋、筋急所自来矣。又风为阳邪，筋脉得之皆燥急，咸寒能益阴润燥软坚，则筋脉舒缓，经络通达而诸证除矣。惊痫者，风热也。脱肛者，大肠热也。踠跌者，血脉伤必发热也。咸寒总除诸热，所以主之。蜈蚣性畏二物，不敢过其所行之路，触其身即死。故人取以治蜈蚣毒。\n\n【主治参与】\n《圣惠方》治大肠因热脱肛，用蜗牛一两烧灰，猪脂和傅，立缩。\n\n《济生方》痔疮肿痛：用蜗牛一杖，入麝香少许，以碗盛，次日取水涂之。丹溪方：用蜗牛浸油涂之，或烧灰傅亦可。\n\n《集验方》发背初起：活蜗牛二百个，以新汲水一盏，瓶内封一宿，取涎水，入真蛤粉，旋调扫傅疮上。日十余度。\n\n《大全良方》痔热肿痛，用大蛞蝓一个，研泥，入片脑一字，燕脂坯子半钱，同傅之。\n\n【简误】\n       其气大寒，非有风热者不宜用。小儿薄弱多泄者不宜用。","videoMemo":"","fangList":[],"bieMing":"蛞蝓,蜗牛"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '12、蛞蝓,蜗牛', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CWNISOa2ubg', 4, '{"title":"第400107111条・卷之二十一_虫鱼部中品","description":"<p>11、鳗鲡鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107111,"note":"     味甘，有毒，主五痔疮瘘，杀诸虫。\n\n      疏：鳗鲡鱼禀土中之阴气，故其味甘，其气寒。其形类蛇，常与水蛇同穴，故其性有小毒。甘寒而善能杀虫，故骨蒸劳瘵，及五痔疮瘘人，常食之有大益也。烧烟辟蚊，熏屋舍竹木断蛀虫，置骨于衣箱子断蠹。其杀诸虫之验可证矣。腹下有黑斑，背上有白点者，毒甚不可食。重三四斤，及水行昂头者，不可食。妊娠食之，令胎有疾。脾胃薄弱易泄者，勿食。","videoMemo":"","fangList":[],"bieMing":"鳗鲡鱼"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '11、鳗鲡鱼', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MwgsLdPX5eR', 4, '{"title":"第400107110条・卷之二十一_虫鱼部中品","description":"<p>10、白僵蚕</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107110,"note":"     味咸、辛，平，无毒。主小儿惊痫夜啼，去三虫，灭黑䵟，令人面色好，男子阴疡（作疮）病，女子崩中赤白，产后余痛，灭诸疮瘢痕。\n\n      疏：蚕属阳，而僵者又兼金木之化。《本经》味咸，《别录》辛平无毒。然详其用，应是辛胜咸劣，气微温之药也。气味俱薄，浮而升，阳也。入足厥阴，手太阴、少阳经。厥阴为风木之位，主藏血。小儿惊痫夜啼，女子崩中赤白，风热乘肝脏也。产后余痛，风寒入血分也。辛能祛散风寒，温能通行血脉，故主如上诸证也。肺主皮毛，而风邪客之，则面色不光润。辛温入肺，去皮肤诸风，故能灭黑䵟，及诸疮瘢痕，令人面色好也。男子阴疡，风湿浸淫也。辛平能散风热，兼能燥湿，是以主之。三虫亦湿热所化，故又能去三虫也。《药性论》治口噤发汗，日华子主中风失音，一切风疰，小儿客忤，男子阴痒痛，女子带下。苏颂治风喉痹欲绝。元素主皮肤诸风如虫行，皆取其性属阳，风热为阳邪，能入皮肤经络，发散诸邪热气也。\n\n【主治参与】\n同丹砂、牛黄、胆星、全蝎、麝香、钩藤钩、犀角、金箔、天竺黄、蝉蜕，治小儿急惊客忤。\n\n《仁存方》开关散：治急喉风痹，用白僵蚕炒，白矾半生半烧，等分为末。每以一钱，用竹沥加姜汁调灌，得吐顽痰，立效。小儿加薄荷。一方用白梅和丸，绵裹含之。\n\n《圣惠方》小儿撮口噤风，面黄赤，气喘，啼声不出，由胎气挟热，流毒心脾，故令舌强唇青，撮口发噤。用白僵蚕二杖，去嘴略炒，为末。蜜调傅唇中，甚效。\n\n《普济方》治大人头风，及小儿惊风，并用大蒜七个，先烧红地，以蒜逐个于地上磨成膏。却以僵蚕一两，去头足，安蒜上，碗覆一夜，勿令泄气，只取僵蚕研水。每用㗜鼻，口内含水，有效。\n\n又方，治腹内龟病，诗云：人间龟病不堪言，肚里生成硬似砖。自死僵蚕白马溺，不过时刻软如绵。\n\n《药性论》灭诸疮瘢痕：白僵蚕衣、鱼鹰屎白等分，傅之。\n\n《圣惠方》瘾疹风疮疼痛：白僵蚕焙研，酒服一钱，立瘥。\n\n《小儿宫气方》小儿口疮通白者，白僵蚕炒为末，蜜和傅之，效。兼治内疳蚀疮。\n\n【简误】\n      僵蚕性辛温，辛能散，其功长于祛风化痰，散有余之邪。凡中风口噤，小儿惊痫夜啼，由于心虚神魂不宁，血虚经络劲急所致，而无外邪为病者，忌之。女子崩中，产后余痛，非风寒客入者，亦不宜用。今世治小儿惊风，不问虚实，一概混施，误甚！误甚！","videoMemo":"","fangList":[],"bieMing":"白僵蚕"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '10、白僵蚕', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f4ryEMqkx49', 4, '{"title":"第400107109条・卷之二十一_虫鱼部中品","description":"<p>9、蚕退,马明退</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107109,"note":"   主血风病，益妇人。一名马明退。（近世医家多用初出蚕子壳在纸上者。东方诸医用老蚕眠起所蜕皮。功用虽相近，当以蜕皮为正，用之微炒。）\n\n    疏：蚕退如蝉蜕、蛇蜕之类，各因其本质以为用。蚕退得蚕气之余，故能治血风病。血热则生风，妇人以血为主，故尤益妇人也。近世以之疗痘疹，去目中翳障，其义犹蝉蜕也。\n\n【主治参与】\n《集验方》走马牙疳：用蚕退纸灰，入麝香少许，贴之。并治口疮。\n\n又方，治缠喉风：蚕蜕纸烧存性，蜜丸芡实大，含化咽津。蚕已出蛾，取退煅存性为末，服之能排脓、穿毒疮口。\n\n【简误】\n妇人血虚无风湿者，不宜用。","videoMemo":"","fangList":[],"bieMing":"蚕退,马明退"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '9、蚕退,马明退', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mzbkACzY56F', 4, '{"title":"第400107108条・卷之二十一_虫鱼部中品","description":"<p>8、蚕沙,蚕屎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107108,"note":"     瘫缓筋骨不随，由于血虚不能荣养经络，而无风湿外邪侵犯者，不宜服。","videoMemo":"","fangList":[],"bieMing":"蚕沙,蚕屎"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '8、蚕沙,蚕屎', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RE5UpNzpuBi', 4, '{"title":"第400107107条・卷之二十一_虫鱼部中品","description":"<p>7、原蚕蛾</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107107,"note":"   雄者有小毒。主益精气，强阴道，交接不倦，亦止精。\n\n    疏：原蚕蛾，乃是晚蚕第一番出者，其子再复出者为二蚕。此二蚕之种，其蛾性最淫，出茧便媾。味咸气温热，故能强阴益精，令交接不倦也。日华子主壮阳事，止泄精，尿血，暖水脏。盖取其性淫助阳，咸温入肾之功耳。\n\n【主治参与】\n《千金方》丈夫阴痿不起：未连蚕蛾二升，去头翅足，炒为末，蜜丸梧子大。每夜服一丸，可御十女，以菖蒲酒止之。\n\n《圣济总录》玉枕生疮，生枕骨上，如痈，破后如箸头，用原蚕蛾炒、石韦等分，为末，干贴，瘥。\n\n【简误】\n少年阴痿，由于失志者，不宜用。阴虚有火者，咸忌之。","videoMemo":"","fangList":[],"bieMing":"原蚕蛾"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '7、原蚕蛾', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G3zOpUnLV4X', 4, '{"title":"第400107106条・卷之二十一_虫鱼部中品","description":"<p>6、海螵蛸,乌贼鱼骨,乌鲗骨,墨鱼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107106,"note":"      味咸，微温，无毒。主女子漏下赤白，经汁血闭，阴蚀肿痛，寒热癥瘕，无子，惊气入腹，腹痛环脐，阴中寒肿。令人有子。又止疮多脓汁不燥。（一名海螵蛸，一名乌鲗骨，一名墨鱼。）\n\n       疏：乌贼鱼骨禀水中之阳气以生，故其味咸，气微温无毒。入足厥阴、少阴经。厥阴为藏血之脏，女人以血为主，虚则漏下赤白，或经汁血闭，寒热癥瘕；少阴为藏精之脏，主隐曲之地，虚而有湿，则阴蚀肿痛。虚而寒客之，则阴中寒肿。男子肾虚则精竭无子，女子肝伤则血枯无孕。咸温入肝肾，通血脉而祛寒湿，则诸证除，精血足，令人有子也。其主惊气入腹，腹痛环脐者，盖肝属木，主惊，惊入胆则荣气不和，故腹痛环脐也。入肝胆舒荣气，故亦主之。温能燥湿，故又主疮多脓汁也。按《素问》云：有病胸胁支满者，妨于食，病至则先闻腥臊臭，出清液，先唾血，四肢清，目眩，时时前后血，病名曰血枯。得之年少时，有所大脱血，或醉入房中，气竭肝伤，故月事衰少不来。治之以四乌鲗骨一藘茹，为末，丸以雀卵，大如小豆。每服五丸，饮以鲍鱼汁，所以利肠中及伤肝也。观此则其入厥阴血分，为女人崩漏下血的要药可知矣。\n\n【主治参与】\n《圣惠方》赤白目翳：用乌鲗骨一两，去皮为末，入片脑少许点之。\n\n《澹寮方》底耳出脓：海螵蛸半钱，麝香一字，为末。以绵杖绞净，吹入。\n\n《圣惠方》小儿脐疮出血及脓：海螵蛸、干胭脂，为末，油调搽之。\n\n《圣济总录》骨鲠在喉：乌贼鱼骨、橘红焙，等分为末，寒食面和饧丸芡子大。每一丸含化。\n\n《简便单方》舌肿出血不止：乌贼骨、蒲黄各等分，炒为末，涂之。\n\n【简误】\n其气味咸温，血病多热者勿用","videoMemo":"","fangList":[],"bieMing":"海螵蛸,乌贼鱼骨,乌鲗骨,墨鱼,乌贼骨"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '6、海螵蛸,乌贼鱼骨,乌鲗骨,墨鱼', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gbu0bMKK6X4', 4, '{"title":"第400107105条・卷之二十一_虫鱼部中品","description":"<p>5、蝉蜕,枯蝉,金牛儿</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107105,"note":"       味咸、甘，寒，无毒。主小儿痫，女人生子不出。灰服之，主久痢。（一名枯蝉，一名金牛儿。凡用洗去泥，并去翅足。浆水煮，晒干用。）\n\n       疏：蝉禀水土之余气，化而成形，其飞鸣又得风露之清气，故能入肝祛风散热，如《药性论》主小儿壮热惊痫是矣。其主妇人生子不下者，取其蜕脱之义。治久痢者，以其有甘寒之功也。其鸣清响，能发音声。其性善蜕，能脱翳障。其体轻浮，能发疮疹。其味甘寒，能除风热。故陈藏器主哑病。寇宗奭主目昏障翳，小儿疮疹出不快。及今人治头风眩晕，皮肤风热，痘疹作痒，疔肿毒疮，大人失音，小儿噤风天吊，惊哭夜啼等证，皆以其有如上诸功能也。\n\n【主治参与】\n同羚羊角、蜜蒙花、白蒺藜、草决明、木贼草、谷精草、甘菊花、夜明沙、生地黄、黄连、女贞实，治目盲障翳。\n\n同丹砂、茯神、真珠、牛黄、僵蚕、天竺黄、钩藤钩、犀角、琥珀、全蝎，治小儿风热急惊痫病。\n\n同犀角、生地黄、紫草、麦门冬、连翘、金银花，治痘疮血热，出不快。\n\n同石膏、鼠粘子、赤柽木、薄荷、玄参、甘草、葛根、栝楼根、麦门冬，治大人小儿痧疹。\n\n《普济方》治小儿夜啼不止，状若鬼祟，以蝉蜕下半截为末，每一字，钩藤汤调下，或入辰砂少许亦可。并治天吊惊啼。\n\n《全幼心鉴》痘疮作痒：蝉蜕三七枚，炙甘草各一钱，水煎服。\n\n钱氏方：痘后目翳，蝉蜕为末，每一钱，羊肝煎汤下，日二服。\n\n《和剂局方》蝉花散：治肝经蕴热，风毒之气内搏上攻，眼目赤肿，翳膜疼痛昏涩，内外障翳，咸治之。用蝉蜕、谷精草、刺蒺藜、甘菊花、防风、草决明、蜜蒙花、甘草、羌活、黄芩、蔓荆子、川芎、木贼草、荆芥，等分为末。每二钱，茶清调，食后临卧各一服。\n\n【简误】\n痘疹虚寒证不得服。","videoMemo":"","fangList":[],"bieMing":"蝉蜕,枯蝉,金牛儿"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '5、蝉蜕,枯蝉,金牛儿', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V1sPpgHzztS', 4, '{"title":"第400107104条・卷之二十一_虫鱼部中品","description":"<p>4、蟹</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107104,"note":"    味咸，寒，有毒。主胸中邪气热结痛，㖞僻面肿。败漆烧之，致鼠。解结散血，愈漆疮，养筋，益气。\n    爪：主破胞堕胎。\n\n    疏：蟹禀水气以生，故其味咸气寒。《本经》虽云有毒，然今人多食之卒无害。其有害者，大抵形质怪异，如后文所载诸种，始有大毒耳。外骨内肉，阴包阳也。入足阳明，足厥阴经。《经》曰：热淫于内，治以咸寒。故主胸中邪气热结痛也。㖞僻者，厥阴风热也。面肿者，阳明热壅也。解二经之热，则筋得养而气自益，㖞僻、面肿俱除矣。咸走血而软坚，故能解结散血。漆得蟹则化为水，烧之可集鼠于庭，此物性之相感相制，莫能究其义也。愈漆疮者，以其能解漆毒故也。\n\n爪性迅利，故能破胞堕胎也。\n\n【主治参与】\n日华子：产后肚痛，血不下者，以酒食之。筋骨折伤者，生捣炒罯之。\n\n陈藏器：续断绝筋骨，去壳同黄，捣烂微炒，纳入疮中，筋即连也。\n\n寇宗奭：小儿解颅不合，以蟹螯同白及末捣涂，以合为度。\n\n唐瑶《经验方》骨节离脱：生蟹捣烂，以热酒倾入，连饮数碗，其渣涂。半日内，骨肉谷谷有声即好。\n\n董炳《验方》：中鱓鱼毒，食蟹即解。\n\n胡洽方：治孕妇僵仆，胎上抢心，有蟹爪汤。\n\n《千金方》神造汤：治子死腹中，或双胎一死一生，服之令死者出，生者安，神验。用蟹爪一升，甘草二尺，东流水一斗，以苇薪煮至二升，滤去滓，入真阿胶三两，令烊，顿服，或分二服。若人困不能服者，灌入即活。\n\n【简误】\n      蟹性冷，能散血热为病，故跌扑损伤，血热瘀滞者宜之。若血因寒凝结，与夫脾胃寒滑腹痛，喜热恶寒之人，咸不宜食。有独螯、独目、两目相向、六足、四足、腹下有毛、腹中有骨头、背有星点、足斑目赤者，并有毒，不可食，能害人。被其毒者，冬瓜汁、紫苏、蒜、豉、芦根汁，皆可解之。不可与柿及荆芥食，发霍乱动风，木香汁可解。","videoMemo":"","fangList":[],"bieMing":"蟹"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '4、蟹', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P9VWh9GSntW', 4, '{"title":"第400107103条・卷之二十一_虫鱼部中品","description":"<p>3、鳖甲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107103,"note":"    味咸，平，无毒。主心腹癥瘕，坚积寒热，去痞，息肉，阴蚀，痔，恶肉，疗温疟，血瘕腰痛，小儿胁下坚。\n     肉：味甘。主伤中，益气补不足。（恶矾石。）\n\n    疏：鳖甲全禀天地至阴之气，故其味咸平无毒。润下作咸，象水明矣。本乎地者亲下，益阴何疑？甲主消散者，以其味兼乎平，平亦辛也。咸能软坚，辛能走散，故《本经》主癥瘕坚积寒热，去痞疾、息肉、阴蚀、痔核、恶肉。\n\n    《别录》疗温疟者，以疟必暑邪为病，类多阴虚水衰之人，乃为暑所深中，邪入阴分，故出并于阳而热甚，入并于阴而寒甚，元气虚羸则邪陷而中焦不治，甚则结为疟母。甲能益阴除热而消散，故为治疟之要药，亦是退劳热在骨，及阴虚往来寒热之上品。血瘕腰痛，小儿胁下坚，皆阴分血病，宜其悉主之矣。劳复、女劳复为必须之药。劳瘦骨蒸，非此不除。产后阴脱，资之尤急。\n\n【主治参与】\n仲景鳖甲煎丸，治疟母之要药。\n\n得牛膝、当归，佐以橘皮、何首乌、知母、麦门冬治久疟。\n\n同知母、石膏、麦门冬、贝母、竹叶，治温疟热甚、渴甚，无肺热病者加人参。若疟发热甚、渴甚，又寒甚汗多，发时指甲黯，状若欲死，并加桂枝，有神。去桂枝，治瘅疟良。\n\n得青蒿、麦门冬、五味子、地黄、枸杞、牛膝，治骨蒸劳热。甚则加银柴胡、地骨皮、胡黄连。\n\n肉：主伤中，益气补不足，腹中结热，妇人漏下，阴虚羸瘦，性冷，补一切阴虚人，宜常食之。\n\n【简误】\n鳖甲，妊娠禁用。凡阴虚胃弱，阴虚泄泻，产后泄泻，产后饮食不消，不思食，及呕恶等证，咸忌之。","videoMemo":"","fangList":[],"bieMing":"鳖甲"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '3、鳖甲', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3h6p3exKElN', 4, '{"title":"第400107102条・卷之二十一_虫鱼部中品","description":"<p>2、露蜂房，蜂房</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107102,"note":"   味苦、咸，平，有毒。主惊痫瘈疭，寒热邪气，癫疾，鬼精盅毒，肠痔。火熬之良。又疗蜂毒、毒肿。\n\n   疏：蜂性有毒，螫人则痛极，以其得火气之甚也。故蜂房味苦，气平，性亦有毒。《别录》言咸，当作辛咸。辛散苦泄，咸可软坚，故主惊痫瘈疭，寒热邪气，癫疾，鬼精蛊毒，肠痔等证也。疗蜂毒、毒肿者，取其气类相从，以毒攻毒之义也。苏恭以乱发、蛇皮，三物合烧灰，酒服方寸匕，治恶疽附骨痈，根在脏腑，历节肿，出疔肿恶脉诸毒。大明煎水漱齿，止风虫疼痛，洗乳痈，蜂疔恶疮。皆取其攻毒散邪杀虫之功耳。\n\n【主治参与】\n《子母秘录》脐风湿疮久不瘥者，蜂房烧末，傅之效。\n\n《袖珍方》风虫牙痛：蜂房一枚，盐实孔内，烧过研末，擦之，盐汤漱去。一方同细辛煎，水漱之。\n\n又方，喉痹肿痛：露蜂房灰、白僵蚕等分，为末，吹入喉内，或用乳香汤服半钱。\n\n《济众方》女人妒乳、乳痈，汁不出，内结成肿，名妒乳：用蜂房烧灰研末，每服二钱，水一盏，煎六分，去滓温服。\n\n《经验方》治漏痔，蜂房烧存性，研细掺之。干则菜油调傅。\n\n【简误】\n蜂房主惊痫瘈疭，及诸痈疽恶毒，正取其攻散邪恶，以毒攻毒之意。若病属气血虚，无外邪者，与夫痈疽溃后元气乏竭者，皆不宜服。","videoMemo":"","fangList":[],"bieMing":"露蜂房，蜂房"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2、露蜂房，蜂房', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BzhsxvJk0HW', 4, '{"title":"第400107101条・卷之二十一_虫鱼部中品","description":"<p>1、猬皮</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107101,"note":"    味苦，平，无毒。主五痔，阴蚀，下血赤白、五色血汁不止，阴肿痛引腰背，酒煮杀之。又疗腹痛疝积，亦烧为灰酒服之。（得酒良。畏桔梗、麦门冬。）\n\n     疏：猬，鼠类，属水。其皮毛戟刺如针，属金。故味苦平，平即兼辛。大肠属金，以类相从，故能治大肠湿热、血热为病，及五痔，阴蚀，下血赤白，五色血汁不止也。阴肿痛引腰背，腹痛疝积，皆下焦湿热邪气留结所致，辛以散之，苦以泄之，故主之也。\n\n肉：味甘平。能开胃气，止反胃，亦主痔瘘肠风。\n\n【主治参与】\n同象牙末等，治通肠漏，见象牙条下。\n\n《衍义》五痔下血：用猬皮、穿山甲等分，烧存性，入肉豆蔻一半，空心米饮下一钱，妙。\n\n《杨氏家藏方》肠风下血：猬皮一枚，木贼草半两，炒黑为末。每二钱，热酒调下。\n\n【简误】\n    凡食其肉，当去骨，误食令人瘦劣，诸节渐小也。","videoMemo":"","fangList":[],"bieMing":"猬皮"}}', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '2024-12-28T09:16:53.000Z', '1、猬皮', '2024-12-28T09:16:53.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'r0wA7YRO5iV');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DasVBbAfdCi', 4, '{"title":"第400107218条・卷之二十二_虫鱼部下品","description":"<p>18、鲮鲤甲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107218,"note":"       微寒。主五邪惊啼悲伤。烧之作灰，以酒或水和方寸匕，疗蚁瘘。\n\n        疏：鲮鲤甲，穿山穴居，其性善走。味辛平，气微寒有毒。入足厥阴，兼入手足阳明经。邪魅着人，则惊啼悲伤不已，辛主散，则邪魅去，惊啼悲伤止矣。喜食蚁，又能入大肠，故疗蚁瘘。蚁瘘者，即世人所云漏也。性走能行瘀血，通经络，故又有消痈毒，排脓血，下乳，和伤，发痘等用。\n\n【主治参与】\n鲮鲤甲，俗名穿山甲。土炒，同乳香、没药、番降香、红曲、山查、川通草、童便，治上部内伤，胸膈间疼痛。\n\n同当归、白芷、金银花、连翘、紫花地丁、夏枯草、牛旁子、乳香、没药、甘草、贝母、皂角刺，治痈肿未溃，资为引导。\n\n佐地榆，治便毒。\n\n《直指方》：治鼠痔成疮肿痛，用穿山甲尾尖处一两，煅存性，鳖甲酥炙一两，麝香半钱，为末。每服一钱，空心茶下。\n\n又方，乳汁不通，涌泉散：用穿山甲炮研末，酒服方寸匕，日二服，外以油梳梳乳，即通。\n\n又方，便毒便痈：穿山甲半两，猪苓二钱，并以醋炙研末，酒服二钱。得紫草、生犀角、生地黄，治痘疮毒盛，不得起发，色带干红枯燥者有功。\n\n【简误】\n      痈疽已溃，不宜服。痘疮元气不足不能起发者，不宜服。","videoMemo":"","fangList":[],"bieMing":"鲮鲤甲"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '18、鲮鲤甲', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1OWjitdcS6J', 4, '{"title":"第400107217条・卷之二十二_虫鱼部下品","description":"<p>17、蝎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107217,"note":"     味甘、辛，有毒。疗诸风瘾疹，及中风半身不遂，口眼㖞斜语涩，手足抽掣。形紧小者良。\n\n      疏：蝎禀火金之气以生，本经味甘辛有毒。然察其用，应是辛多甘少，气温。入足厥阴经。诸风掉眩，属肝木，风客是经，非辛温走散之性，则不能祛风逐邪，兼引诸风药入达病所也。故大人真中风，小儿急惊风，皆须用之。\n\n【主治参与】\n《全幼心鉴》：小儿脐风，宣风散：治小儿初生断脐后伤风，唇青口撮，出白沫，不乳，用全蝎二十一个，无灰酒涂炙为末，入麝香少许。每用金、银煎汤，调半字服之。\n\n《经验方》大人风涎：用蝎一个，头尾全者，以薄荷四叶裹定，火上炙焦，同研为末。作一服，白汤下。小儿惊风分四服，如前服。得胡桃同煅，共研，黄耆、金银花汤下，治横痃不收口。\n\n【简误】\n       蝎，风药也。似中风，及小儿慢脾风病属于虚，法咸忌之。","videoMemo":"","fangList":[],"bieMing":"蝎"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '17、蝎', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EMUSyl42Y2d', 4, '{"title":"第400107216条・卷之二十二_虫鱼部下品","description":"<p>16、五灵脂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107216,"note":"      味甘，温，无毒。主疗心腹冷气，小儿五疳，辟疫，治肠风，通利气脉，女子月闭。出北地，此是寒号虫粪也。\n      \n       疏：寒号虫，畏寒喜暖，故其粪亦温，味甘而无毒。气味俱厚，阴中之阴，降也。入足厥阴、手少阴经。性专行血，故主女子血闭。味甘而温，故疗心腹冷气，及通利气脉也。其主小儿五疳者，以其亦能消化水谷。治肠风者，取其行肠胃之瘀滞也。凡心胸血气刺痛，妇人产后少腹儿枕块诸痛，及痰挟血成窠囊，血凝齿痛诸证，所必须之药。\n\n【主治参与】\n同泽兰、牛膝、益母草、延胡索、牡丹皮、红花、赤芍药、山查、生地黄，治产后恶露不净，腹中作疼。加桃仁其效更速，勿过剂。同番降香、红曲、川通草、红花、延胡索、韭菜、童便，治胃脘瘀血作痛。\n同木香、乌药，治周身血气刺痛。\n\n《和剂局方》失笑散：治男女老少心痛，腹痛，少腹痛，并少腹疝气，诸药不效者，能行能止；妇人妊娠心痛，及产后心痛，少腹痛，血气痛尤妙。用五灵脂、蒲黄等分，研末。先以醋二杯调末，熬成膏，入水一盏，煎至七分，连药热服。未止再服。一方以酒代醋，一方以醋糊丸，童便酒服。\n\n《杨氏产乳方》紫金丸：治产后恶露不快，腰痛，少腹如刺，时作寒热头痛，不思饮食；又治久有瘀血，月水不调，黄瘦不食；亦疗心痛，功与失笑同。以五灵脂，水淘净炒末一两，以好米醋调稀，慢火熬膏，入真蒲黄末，和丸龙眼大。每服一丸，以水与童便各半盏，煎至七八分，温服，少顷再服，恶露即下。血块经闭者，酒磨服之。\n\n《图经》：产后血晕不知人事，用五灵脂二两，半生半炒，为末。每服一钱，白水调下。如口噤者，斡开灌之，入喉即愈。\n\n丹溪方：产后腹痛，五灵脂、香附、桃仁，等分研末，醋糊丸。服一百丸，白术、牛膝、陈皮汤下。\n\n《事林广记》卒暴心痛：五灵脂炒一钱半，干姜炮三分，为末。热酒服，立愈。\n\n《产宝方》胎衣不下，恶血冲心：用五灵脂半生半炒，研末。每服二钱，温酒下。\n\n《百一选方》：痰血凝结，紫芝丸：用五灵脂水飞，半夏汤泡，等分为末，姜汁浸，蒸饼丸梧子大。每米饮下二十丸。\n\n夏子益《奇疾方》：血溃怪病，凡人眼中白珠浑黑，视物殊常，毛发坚直如铁条，能饮食而不语，如醉，名曰血溃。以五灵脂为末，汤服二钱即愈。\n\n【简误】\n      五灵脂，其功长于破血行血，故凡瘀血停滞作痛，产后血晕，恶血冲心，少腹儿枕痛，留血经闭，瘀血心胃间作痛，血滞经脉，气不得行，攻刺疼痛等证，在所必用。然而血虚腹痛，血虚经闭，产妇去血过多发晕，心虚有火作痛，病属血虚无瘀滞者，皆所当忌。","videoMemo":"","fangList":[],"bieMing":"五灵脂"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '16、五灵脂', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qYW6a5zs0Fe', 4, '{"title":"第400107215条・卷之二十二_虫鱼部下品","description":"<p>15、蜣螂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107215,"note":"      味咸，寒，有毒，主小儿惊痫瘈疭，腹胀寒热，大人癫疾狂昜（音羊），手足端寒，支满，贲豚。\n\n       疏：蜣螂禀阴湿之气以生，故其味咸气寒有毒。入足厥阴、手足阳明经。小儿惊痫瘈疭，腹胀寒热，大人癫疾狂昜，皆肝、胃、大肠三经风热壅盛所致。咸寒除三经之邪热，则诸证自瘳。《别录》主手足端寒、支满者，以脾胃主四肢而治中焦。脾气结滞，则血液不能通行灌溉于手足。胃家热壅及大肠结实，则中焦不治而气逆支满。行三经之壅滞，则所苦减除矣。咸能软坚入肾，故又主奔豚也。古今方书以之治一切痔瘘，及疔肿疽疮，出箭镞之用。\n\n【主治参与】\n《本事方》推车散：治大小便经月不通欲死者，用推车客七个，男用头，女用身；蝼蛄七个，男用身，女用头，新瓦焙，研末。用虎目树南向皮煎汁调服，只一服，立通。\n\n一方，大肠脱肛：蜣螂烧存性，为末，入冰片研匀，掺上托之即入。\n\n唐氏方：肠漏出水，用蜣螂一枚，阴干，入冰片少许，为细末。纸捻蘸末入孔内，渐渐生肉，药自退出，即愈。\n\n刘涓子方：附骨疽疮：蜣螂七枚，同大麦捣傅。\n\n《广利方》：无名恶疮，忽得不识者，用蜣螂杵汁涂之。\n\n刘禹锡纂 “柳州救三死方” 云：元和十一年得疔疮，凡十四日益笃，善药傅之莫救。长庆贾方伯教用蜣螂心，一夕百苦皆已。明年正月，食羊肉又大作，再用如神验。其用蜣螂心，在腹下度取之，其肉稍白是也。贴疮半日许，再易，血尽根出即愈。蜣螂畏羊肉，故食之即发。其法盖出葛洪《时后方》。\n\n杨氏《家藏方》：箭镞入骨不可移者，用巴豆微炒，同蜣螂捣涂，斯须痛定，必微痒，忍之。待极痒不可忍，乃撼动拔之立出。凡诸疮皆可疗也。\n\n捣为丸，塞下部，引痔虫出尽，永差。\n\n【简误】\n蜣螂有毒，外用易臻厥功。内服非虚人所宜。非不得已，勿轻试。","videoMemo":"","fangList":[],"bieMing":"蜣螂"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '15、蜣螂', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zkv68oE9v8G', 4, '{"title":"第400107214条・卷之二十二_虫鱼部下品","description":"<p>14、白花蛇,褰鼻蛇</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107214,"note":"      味甘、咸，温，有毒。主中风，湿痹不仁，筋脉拘急，口面㖞斜，半身不遂，骨节疼痛，大风疥癞，及暴风瘙痒，脚弱不能久立。一名褰鼻蛇。白花者良。（出蕲州，龙头虎口，黑质白花，目开如生，尾有爪甲，真蕲产也。）\n\n         疏：白花蛇，生于土穴阴霾之处，禀幽暗毒厉之气，故其味虽甘咸，性则有大毒也。《经》曰：风者，百病之长，善行而数变。蛇性走窜，亦善行而无处不到，故能引诸风药至病所，自腑脏而达皮毛也。凡疠风、疥癣、㖞僻、拘急、偏痹不仁、因风所生之证，无不借其力以获瘥。本经著其功能，信非虚矣。\n\n【主治参与】\n同苦参、何首乌、威灵仙、鳖虱胡麻、天门冬、百部、豨莶、漆叶、刺蒺藜，治疠风，并遍身顽痹、疥癣。\n\n《医垒元戎》驱风膏：治风瘫疠风，遍身疥癣，用白花蛇肉四两，酒润炙干，天麻七钱半，薄荷、荆芥各二钱半，为末，好酒二升，蜜四合，石器熬成膏。每服一盏，温汤服，日三服，急于暖处出汗，十日效。\n\n《瑞竹堂经验方》白花蛇酒：治诸风疠癣，用白花蛇一条，酒润，去皮骨取肉，绢袋盛之，蒸糯米一斗，安曲于缸底，置蛇于曲上，以饭安蛇上，用物密盖三七日，取酒，以蛇晒干为末，每服三五分，温酒下，仍以浊酒并糟作饼食之，尤佳。\n\n洁古白花蛇散治大风病：白花蛇、乌梢蛇，各取净肉二钱酒炙，雄黄二钱，大黄五钱，为末。每服二钱，白汤下，三日一服。\n\n乌蛇：即乌梢蛇，气味所主，经白花蛇同，第性善无毒耳。修事亦同，不复载。（色黑如漆，尾细有剑脊者良。）\n\n【简误】\n白花蛇，性走窜有毒，疠风、疥癣、顽痹等证，诚为要药。然而中风口面㖞斜，半身不遂，定缘阴虚血少、内热而发，与得之风湿者殊异，非所宜也，医师宜辨之。头尾并骨俱有大毒，须尽去之。\n","videoMemo":"","fangList":[],"bieMing":"白花蛇,褰鼻蛇"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '14、白花蛇,褰鼻蛇', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fsWszoeAya7', 4, '{"title":"第400107213条・卷之二十二_虫鱼部下品","description":"<p>13、田螺,田中螺汁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107213,"note":"      大寒。主目热赤痛，止渴。\n\n      疏：田螺，产于水田中，禀水土之阴气，故其汁大寒，味应甘，性无毒。陶隐居以真珠、黄连末纳入，良久取汁点目痛，神效。以其寒能除热也。解一切有余之热，故能止渴及醒酒。\n\n【主治参与】\n丹溪方：治噤口痢疾，用活大田螺二枚，捣烂，入麝香三分，作饼，烘热贴脐间。半日热气下行，即思食矣。甚效。\n\n又方治小便不通，腹胀如鼓：用田螺一枚，盐半匕，生捣，傅脐下一寸三分，即通。\n\n《经验方》大肠脱肛坠下三五寸者，用大田螺二三枚，将净水养去泥，用鸡爪黄连研细末，入厣内，待化成水，以浓茶洗净肛门，将鸡翎蘸水刷之，以软帛托上，自然不再发也。\n\n《乾坤生意》痔漏疼痛，用田螺一个，入龙脑一分在内，取水搽之效。\n\n【简误】\n目病非关风热者，不宜用。","videoMemo":"","fangList":[],"bieMing":"田螺,田中螺汁"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '13、田螺,田中螺汁', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yKm0XBdiHa7', 4, '{"title":"第400107212条・卷之二十二_虫鱼部下品","description":"<p>12、斑猫,斑蟊</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107212,"note":"       味辛，寒，有毒。主寒热，鬼疰蛊毒，鼠瘘，疥癣，恶疮疽，蚀死肌，破石癃血积，伤人肌，堕胎。（马刀为之使。畏巴豆、丹参、空青、甘草。）\n\n       疏：斑猫禀火金相合之气，故其味辛气寒。扁鹊云：有大毒。近人肌肉则溃烂，毒可知矣。入手阳明、手太阳经。性能伤肌肉，蚀死肌，故主鼠瘘、疽疮、疥癣。辛寒能走散下泄，故主破石癃血积，及堕胎也。至于鬼疰蛊毒，必非极辛大毒之药所能疗，此《本经》之误。甄权主瘰疬，通利水道。以其能追逐肠胃垢腻，复能破结走下窍也。\n\n【主治参与】\n治瘰疬，用肥皂二斤，去核，每服皂一荚，入斑猫四枚，线缚蒸，取出，去斑猫并肥皂皮筋，得净肉十两，入贝母二两，栝楼根、玄参、甘草、薄荷叶各一两五钱，共为末，以肥皂捣如泥，为丸梧子大。每服一钱，白汤吞。服后腹疼，勿虑，此药力追毒之故。\n\n治癫犬咬方：用斑猫七个，去头足并翅，酒洗，和湿糯米铜勺内炒，米熟为度，随将二物研成细末，加六一散三两，分作七服，每清晨一服，白汤调下。本人头顶心必有红发二三根，要不时寻觅拔去。\n《经验方》内消瘰疬，不拘大人小儿：用斑猫一两，去头足翅，以粟米一升同炒，米焦去米，入薄荷四两，为末，乌鸡子清丸如绿豆大。空心腊茶下三丸，加至五丸，却每日减一丸，减至一丸后，复日增一丸，以消为度。\n\n【简误】\n        斑猫，性有大毒，能溃烂人肌肉。惟瘰疬、癫犬咬，或可如法暂施。此物若煅之存性，犹能啮人肠胃，发泡溃烂致死。即前二证，亦不若用米同炒，取气而勿用质为稳。余证必不可饵。切戒！切戒！","videoMemo":"","fangList":[],"bieMing":"斑蟊,斑猫"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '12、斑猫,斑蟊', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ks1NDB4RfhA', 4, '{"title":"第400107211条・卷之二十二_虫鱼部下品","description":"<p>11、水蛭,马蟥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107211,"note":"      味咸、苦，平、微寒，有毒。主逐恶血，瘀血月闭，破血瘕积聚无子，利水道，又堕胎。（俗名马蟥。）\n\n       疏：水蛭生于溪涧阴湿之处，其味咸苦，气平有大毒。其用与虻虫相似。故仲景方中往往与之并施。咸入血走血，苦泄结，咸苦并行，故治妇人恶血，瘀血月闭，血瘕积聚因而无子者。血蓄膀胱则水道不通，血散而膀胱得气化之职，水道不求其利而自利矣。堕胎者，以其有毒善破血也。\n\n【主治参与】\n入抵当汤，治伤寒蓄血下焦，因而发狂。\n\n入大黄䗪虫丸，兼治虚劳骨蒸咳嗽，内有干血，皮肤甲错。\n\n入鳖甲煎丸，消疟母。以上皆仲景方。\n\n《古今录验方》坠跌打击内伤，神效。水蛭一两，烧令烟出，为末，入麝香一两，每酒服一钱，当下蓄血。未止再服，其效如神。\n\n【简误】\n       水蛭、虻虫，皆破逐瘀血，血瘀发病之恶药。而水蛭入腹，煅之若尚存性，尚能变为水蛭，啮人肠脏，非细故也。破瘀消血之药尽多，正足选用，奚必用此难制之物？戒之可也。如犯之，以黄泥作丸吞之，必入泥而出。","videoMemo":"","fangList":[],"bieMing":"水蛭,马蟥"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '11、水蛭,马蟥', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BORp8cppTz1', 4, '{"title":"第400107210条・卷之二十二_虫鱼部下品","description":"<p>10、蛤蚧</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107210,"note":"      味咸，平，有小毒，主久肺劳传尸，杀鬼物邪气，疗咳嗽，下淋沥，通水道。生岭南山谷，及城墙或大树间。身长四五寸，尾与身等，形如大守宫，一雌一雄，常自呼其名曰蛤蚧。最护惜其尾，或见人欲取之，多自啮断其尾，人即不取之。凡采之者，须存其尾，则用之力全故也。\n\n       疏：蛤蚧得金水之气，故其味咸气平，有小毒。入手太阴，足少阴经。其主久肺劳传尸、鬼物邪气、咳嗽、淋沥者，皆肺肾为病，劳极则肺肾虚则生热，故外邪易侵，内证兼发也。蛤蚧属阴，能补水之上源，则肺肾皆得所养而劳热咳嗽自除，邪物鬼气自去矣。肺朝百脉，通调水道，下输膀胱，肺气清，故淋沥水道自通也。又顾玠《海槎录》云：广西横州甚多蛤蚧，牝牡上下，相呼累日，情洽乃交，两相抱负，自堕于地。人往捕之亦不知觉，以手分劈，虽死不开。乃用熟槁草细缠，蒸过曝干，售之，炼为房中之药甚效。寻常捕者，不论雌雄，但可为杂药用。\n\n【主治参与】\n寇氏《衍义》：治久嗽不愈，肺积虚热成痈，咳出脓血，晓夕不止，喉中气塞，胸膈噎痛，用蛤蚧、阿胶、鹿角胶、犀角、羚羊角，各二钱半，用河水三升，银石器内文火熬至半升，滤汁。时时仰卧细呷，日一服。\n\n【简误】\n咳嗽由风寒外邪者，不宜用。雷公曰：其毒在眼，须去眼及甲上、尾上、腹上肉毛，以酒浸透，隔两重纸缓焙令干，以瓷器盛，悬屋东角上一夜，用之力可十倍。勿伤尾。","videoMemo":"","fangList":[],"bieMing":"蛤蚧"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '10、蛤蚧', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DhWie6wlYT9', 4, '{"title":"第400107209条・卷之二十二_虫鱼部下品","description":"<p>9、蜈蚣,蝍蛆,天龙</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107209,"note":"      味辛，温，有毒。主鬼疰蛊毒，噉诸蛇虫鱼毒，杀鬼物老精，温疟，去三虫，疗心腹寒热结聚，堕胎，去恶血。赤头足者良。（一名蝍蛆，一名天龙。）\n\n       疏：蜈蚣禀火金之气以生，故其味辛，气温有毒。乃属阳之毒虫，足厥阴经药也。善能制蛇，见大蛇便缘上啖其脑。《淮南子》云：腾蛇游雾，而殆于蝍蛆。正指此也。故《本经》主噉诸蛇虫鱼毒，及去三虫蛊毒也。性复走窜辟邪，所以能疗鬼疰温疟，杀鬼物老精。辛主散结，温主通行，故又治心腹寒热结聚，堕胎去恶血也。今世又以之治小儿惊痫风搐，脐风口噤，与夫瘰疬、便毒、痔漏等证皆用之。\n\n【主治参与】\n金头蜈蚣，得牛角䚡、象牙末、猪悬蹄、刺猬皮、蛀竹屑，能去通肠漏管。\n\n《直指方》：瘭疮，一名蛇瘴。蛮烟瘴雨之乡多毒蛇气，人有不伏水土风气而感触之者，数月以还，必发蛇瘴。惟赤足蜈蚣最能伏蛇，为上药，白芷次之。\n\n《圣济总录》云：岭南外蛇瘴，一名琐喉瘴，项大肿痛连喉。用赤足蜈蚣一二节，研细，水下即愈。\n\n《奇效良方》：天蛇头疮，生手指头上：用蜈蚣一条，烧烟熏，一二次即愈。或为末，猪胆汁调涂之。\n\n《济生秘览》便毒初起：蜈蚣一条，瓦上焙存性，为末，酒调服。\n\n《图经》治初失小儿口噤不开，不能乳者，用赤足蜈蚣去足炙，研末，以猪乳二合，调半钱，分三四服，温灌之，效。\n\n【简误】\n         蜈蚣性有毒，善走窜，小儿慢惊风，口噤不言；大人温疟，非烟岚瘴气所发；心腹积聚，非虫结蛇瘕；便毒成脓将溃，咸在所忌。性畏蛞蝓，不敢过其所行之路。能啮人痛甚，以蛞蝓捣涂之，痛立止。蜈蚣能制龙蛇而反畏蛞蝓、蜘蛛，即《庄子》所谓物畏其天，《阴符经》所谓禽之制在气也。凡使勿用千足虫，真相似，但蜈蚣腰中一段无脚，所以能掬而弹远为异。又云：头上有白肉面并嘴尖可别。若误用并把着，腥臭气入顶，能杀人也。","videoMemo":"","fangList":[],"bieMing":"蜈蚣,蝍蛆,天龙"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '9、蜈蚣,蝍蛆,天龙', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Njdjq242CGX', 4, '{"title":"第400107208条・卷之二十二_虫鱼部下品","description":"<p>8、白颈蚯蚓</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107208,"note":"     味咸，寒、大寒，无毒。主蛇瘕，去三虫，伏尸鬼疰，蛊毒，杀长虫。仍自化作水，疗伤寒伏热狂谬，大腹黄疸。一名土龙。（畏葱、盐。）\n\n      疏：蚯蚓得土中阴水之气，故其味咸寒，无毒大寒。能祛热邪，除大热，故主伏尸鬼疰，乃疗伤寒伏热狂谬。咸主下走，利小便，故治大腹黄疸。诸虫瘕，咸属湿热所成，得咸寒之气，则瘕自消，虫自去，而蛊毒之热亦解矣。昔一道人，治热病发狂，用白颈蚯蚓十数条，同荆芥穗捣汁，与饮之，得臭汗而解。其为治伤寒伏热狂谬之明验也。\n\n【主治参与】\n《肘后方》伤寒热结六七日，狂乱见鬼欲走：以大白颈蚯蚓半斤，去泥，用人溺煮汁饮。或生绞汁亦可。\n\n《斗门方》小便不通，因湿而得者：用蚯蚓捣烂，浸水，滤取浓汁半碗，服立通。\n\n《胜金方》耳卒聋闭：蚯蚓入盐，安葱管内，化水点之，立效。\n\n《保命集》瘰疬溃烂流串者，用荆芥根下段煎汤，温洗良久，看疮破紫黑处，以针刺去血，再洗三四次，用韭菜地上蚯蚓一把，五更时收取，炭火上烧红为末。每一匙入乳香、没药、轻粉各半钱，穿山甲九片，炙为末，麻油调傅之，神效。\n\n【简误】\n蚯蚓，气大寒，能除有余邪热，故伤寒非阳明实热狂躁者，不宜用。温病无壮热，及脾胃素弱者，不宜用。黄疸缘大劳腹胀，属脾肾虚。尸疰因阴虚成劳瘵者，咸在所忌。性复有小毒，被其毒者，以盐水解之。","videoMemo":"","fangList":[],"bieMing":"白颈蚯蚓"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '8、白颈蚯蚓', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BnFPhkTPdhD', 4, '{"title":"第400107207条・卷之二十二_虫鱼部下品","description":"<p>7、蛇蜕</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107207,"note":"      味咸、甘，平，无毒。主小儿百二十种惊痫、瘈疭、癫疾、寒热、肠痔、虫毒、蛇痫弄舌摇头。大人五邪，言语僻越，恶疮，呕咳，明目。火熬之良。\n\n       疏：蛇蜕，蛇之余性犹存，不以气味为用者。故蛇之性上窜而主风；蜕之用，入肝而辟恶，其性一也。小儿惊痫、瘈疭、癫疾、寒热，蛇痫弄舌摇头，大人五邪，言语僻越，皆肝经为病，邪恶侵犯也。蛇蜕走窜，能引诸药入肝散邪，故主如上等证。善能杀虫，故主肠痔、虫毒、恶疮。邪去木平，故止呕咳，明目。今人亦用以催生、去翳膜者，取其善脱之义也。\n\n【主治参与】\n《肘后方》治小儿头面疮：蛇蜕烧灰，腊猪脂和傅之，并治小儿月蚀。周密《齐东野语》云：小儿痘后障翳，蛇蜕一条，净洗，焙，天花粉五钱，为末。以羊肝破开，夹药缚定，米泔水煮食。屡试辄效，真奇方也。《济生秘览》治横生、逆生，须臾不救，用蛇蜕一具，蝉蜕十四个，发一握，并烧存性，分二服，酒下。仍以小针刺儿足心，擦盐少许，即顺。并能下胞衣。\n\n《产乳方》妇人吹乳：蛇皮一尺七寸，烧末酒服。\n\n《千金方》诸漏有脓：蛇蜕灰，傅之即虫出。\n\n《直指方》鱼脐疮出水，四畔浮浆：用蛇蜕烧存性，鸡子清和傅。\n\n《医方摘要》耳忽大痛，如有虫在内奔走，或血水流出，或干痛不可忍者，蛇蜕皮烧存性，研细，鹅翎吹入，立愈。\n\n【简误】\n小儿惊痫癫疾，非外邪客忤，而由于肝心虚者，不效。","videoMemo":"","fangList":[],"bieMing":"蛇蜕"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '7、蛇蜕', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6RTl2GkcsuA', 4, '{"title":"第400107206条・卷之二十二_虫鱼部下品","description":"<p>6、蚺蛇胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107206,"note":"     味甘、苦，寒，有小毒。主心腹䘌痛，下部䘌疮，目肿痛。\n\n      疏：蚺蛇禀火土之气，其胆为甲乙风木之化，故其味苦中有甘，气寒有小毒。气薄味厚，阴也。降也。入手少阴，足厥阴、阳明经。心腹䘌痛者，虫在内攻啮也。下部䘌疮者，虫在外侵蚀也。湿热则生虫，苦寒能燥湿杀虫，故内外施之皆得也。肝开窍于目，肝热则目肿痛，入肝泄热，则肿痛除矣。今人受杖时，用此噙化，可得不死。其功能护心止痛，使恶血不上薄心，有神力也。\n\n【主治参与】\n\n同血竭、乳香、没药、狗头骨灰、䗪虫、天灵盖、象牙末、麻皮灰、丹砂，作丸。临杖服一丸，护心止痛，多杖无害。\n\n《圣惠方》：小儿急疳疮，水调蚺蛇胆傅之。\n\n《医方摘要》痔疮肿痛：蚺蛇胆研，香油调涂，立效。\n\n真胆绝难得，狭长，通黑，皮膜极薄，舐之甜苦，剔取粟许，着净水中，浮游水上，回旋行走者为真。其径沉者，非也。勿多着，亦沉散也。今世惟为受杖人所需，余甚稀使，故不著“简误”。","videoMemo":"","fangList":[],"bieMing":"蚺蛇胆"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '6、蚺蛇胆', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QS28yIWhW57', 4, '{"title":"第400107205条・卷之二十二_虫鱼部下品","description":"<p>5、蚶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107205,"note":"     温。主心腹冷气，腰脊冷风，利五脏，健胃，令人能食。又云温中消食，起阳，益血色。\n\n       壳：烧过，以米醋三度淬后，埋令坏，醋膏丸。治一切血气，冷气，癥癖。\n\n       疏：蚶得水中之阳气，故其味甘，气湿，性亦无毒。《经》曰：里不足者，以甘补之。又曰：形不足者，温之以气。甘温能益气而补中，则五脏安，胃气健，心腹腰脊风冷俱瘳矣。胃健则食自消，脏暖则阳自起，气充则血自华也。\n\n      壳味咸，走血而软坚，故能治血气冷气癥癖。丹溪用以消血块，化痰积，以此也。今世糟其肉侑酒之物，罕有入药者。壳惟消癥癖之外，无他用。故并不著“主治”及“简误”。","videoMemo":"","fangList":[],"bieMing":"蚶"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '5、蚶', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zRWk1WCmHSX', 4, '{"title":"第400107201条・卷之二十二_虫鱼部下品","description":"<p>1、蟾蜍,虾蟆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107201,"note":"       味辛，寒，有毒，主邪气，破癥坚血，痈肿阴疮。服之不患热病。疗阴蚀，疽疠恶疮，猘犬伤疮，能合玉石。一名蟾蜍。\n\n       疏：虾蟆、蟾蜍，本是二物。经云：一名蟾蜍者，盖古人通称蟾为虾蟆耳。经文虽名虾蟆，其用实则蟾蜍也。今世所用者皆蟾蜍，而非虾蟆，其功益可见矣。禀土金之精气，上应月魄，性亦灵异，其味辛气寒，毒在眉棱皮汁中。其主痈肿阴疮，阴蚀，疽疠恶疮，猘犬伤疮者，皆热毒气伤肌肉也。辛寒能散热解毒，其性急速，以毒攻毒则毒易解，毒解则肌肉和，诸证去矣。凡瘟疫邪气，得汗则解。其味大辛，性善发汗，辛主散毒，寒主除热，故能使邪气散而不留，邪去则胃气安而热病退矣。破癥坚血者，亦以其辛寒能散血热壅滞也。陶隐居云：其肪涂玉，则刻之如蜡，故云能合玉石。近世治小儿疳疾多用，以其走阳明而能消积滞也。\n\n【主治参与】\n《全婴方》五疳保童丸：治五疳八痢，面黄肌瘦，好食泥土，不思乳食，用大干蟾蜍一枚，烧存性，皂角去皮弦一钱，烧存性，蛤粉水飞三钱，麝香一分，糊丸粟米大。空心米饮下三四十丸，日二服。\n\n郑氏小儿方：走马牙疳，侵蚀口鼻：干蚵蚾，黄泥裹固，煅过，黄连，各二钱半，青黛一钱，入麝香少许，和研傅之。\n\n《锦囊秘览》附骨坏疮久不瘥，脓汁不已，或骨从疮孔中出：用大虾蟆一个，乱发一鸡子大，猪油四两，入二物煎枯去滓，待凝如膏。先以桑根皮、乌头煎汤洗，拭干，煅龙骨末糁四边，以前膏贴之。\n\n《医林集要》发背肿毒初起势重者，以活蟾一个，破开，连肛乘热合疮上。不久必臭不可闻，再易，三四次即愈。\n\n《袖珍方》治疯犬伤，即用蟾蜍后足捣烂，水调服之。先于顶心拔去血发三两根，则小便内见沫也。","videoMemo":"","fangList":[],"bieMing":"蟾蜍,虾蟆"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '1、蟾蜍,虾蟆', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7ivVH1hLyeD', 4, '{"title":"第400107204条・卷之二十二_虫鱼部下品","description":"<p>3、蛤蜊</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107204,"note":"    冷，无毒。润五藏，止消渴，开胃，解酒毒，主老癖能为寒热者，及妇人血块。煮食之。\n    \n      疏：蛤蜊禀水中之阴气以生，其味咸，气冷无毒。入足阳明经。五脏皆属阴，得水气之阴者，其性滋润而助津液，故能润五脏，止消渴，开胃也。咸能入血软坚，故主妇人血块，及老癖为寒热也。煮食更能醒酒。\n\n蛤粉：丹溪云：味咸，寒，无毒。主热痰、湿痰、老痰、顽痰、疝气、白浊、带下。同香附末，姜汁调服，主心痛。\n\n疏：此即蛤壳煅成粉者，其味咸，气寒无毒，为诸痰证的要药。盖痰未有不由火气上炎，煎熬津液而成。咸能软坚润下，得之则火自降，痰结自消矣。疝气、白浊、带下，皆肾经为病也。肾属水，咸为水化，气类相从，故能入肾以除其所苦也。心痛者，心虚而热邪客之也。“五脏苦欲补泻”云：心欲软，急食咸以软之。此之谓也。更有消浮肿，利小便，散瘿核肿毒，妇人血块，汤火伤疮等服。\n\n【主治参与】\n《普济方》气虚水肿：用大蒜十个，捣如泥，入蛤粉丸梧子大。每食前白汤下二十丸，服尽，小便下数桶而愈。\n\n洁古方：治白浊遗精，真珠粉丸：用蛤粉煅一斤，黄檗蜜炙一斤，为末，水跌为丸梧子大。每服一百丸，空心温酒下，日二次。盖蛤粉味咸，而能补肾阴，黄檗苦而降心火、坚肾故也。\n\n【简误】\n       肉气味虽冷，乃与丹石人相反，食之令腹结痛。壳粉善消痰积血块，然脾胃虚寒者，宜少用，或加益脾胃药同用为宜。","videoMemo":"","fangList":[],"bieMing":"蛤蜊"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '3、蛤蜊', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mwzbAnykkZf', 4, '{"title":"第400107203条・卷之二十二_虫鱼部下品","description":"<p>3、牡鼠粪</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107203,"note":"      微寒，无毒。主小儿痫疾，大腹，时行劳复。（两头尖者是牡鼠屎。）\n\n        疏：牡鼠粪，本经诸家不言味，但云微寒无毒。然详其所自，应是苦咸之物。盖鼠属水，而凡粪必苦者也。入足阳明，足厥阴经。其主小儿痫疾，大腹，及时行劳复者，皆热邪在阳明也。苦寒能除是经之热，所以主之。古方治男子阴易腹痛，妇人吹乳乳痈，皆取其除热软坚泄结，走肝入胃之功耳。\n\n【主治参与】\n同白芷、山慈菇、山豆根、连翘、金银花、蒲公草、夏枯草、贝母、橘叶、栝楼根、紫花地丁、牛旁子，治乳痈、乳岩，有效。\n\n《外台秘要》伤寒劳复：用雄鼠屎二十枚，豉五合，水二升，煮一升，顿服。《活人书》加栀子、葱白。\n\n南阳《活人书》：男子阴易，及劳复。豭鼠屎汤：用豭鼠屎两头尖者，十四枚，韭白根一大把，水二盏，煎一盏，温服得粘汗为效。未汗再服。\n\n《集要方》妇人吹奶：鼠屎七粒，红枣七枚去核包屎，烧存性，入麝香少许，温酒调服。并治乳痈初起。\n\n《普济方》大小便秘：雄鼠屎末，傅脐中，立效。\n\n除伤寒劳复阴易及乳痈、乳岩外，他用甚稀，故不著“简误”。","videoMemo":"","fangList":[],"bieMing":"牡鼠粪"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '3、牡鼠粪', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QQG79qK7aS0', 4, '{"title":"第400107202条・卷之二十二_虫鱼部下品","description":"<p>2、蟾酥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107202,"note":"     甄权云：端午日，取眉脂，以朱砂、麝香为丸，如麻子大，治小儿疳瘦，每日一丸。如脑疳，以乳汁调，滴鼻中。日华子云：眉酥治蚛牙。和牛酥摩傅腰眼并阴囊，治腰肾冷，并助阳气。苏颂云：主蚛牙，及小儿疳瘦。观诸家所主，但言其有消积杀虫，温暖通行之功。然其味辛甘，气温，善能发散一切风火抑郁、大热痈肿之候，为拔疔散毒之神药。第性有毒，不宜多用。入发汗散毒药中服者，尤不可多。\n\n【主治参与】\n同铁锈、桑硇、麝香、牛黄、冰片，用金针针入疔根，抹入前药，其疔根即烂出。\n\n治疔丸：同朱砂、冰片、牛黄、明矾、白僵蚕、麝香、黄蜡，溶化作丸，麻子大。用葱头、白酒吞下取汗，不过二三小丸。\n\n《青囊杂纂》拨取疔黄：蟾酥，以面丸梧子大。每用一丸，安舌下，即黄出也。\n\n危氏方：拔取疔毒：蟾酥，以白面、黄丹搜作剂，每丸麦粒大。挑破纳入，仍以水澄膏贴之。\n\n《保命集》一切疮毒：蟾酥一钱，白面二钱，朱砂少许，井水调成小锭子如麦大。每用一锭，葱汤服，汗出即愈。如疮势紧急，用三四锭。\n\n《万氏家抄》：凡痈疽发背，无名肿毒初起者，急取蟾酥三五分，广胶一块，米醋一二碗，入铫内火化开，用笔蘸，乘热令人不住手周围润之。以散为度。\n\n【简误】\n        蟾虽有毒，与病无害。其眉酥有大毒，不宜多服。诸家咸云，治小儿疳瘦，恐非正治，不宜漫尝也。即用亦煅过者。予亲见一人，因齿痛，以蟾酥纳牙根，误吞入，头目俱胀大而毙。即陶注云：其皮汁甚有毒，犬啮之，口皆肿之验也。惟疔肿服之者，取其以毒攻毒之义。然其剂亦甚小，不能为害耳。外治殊有神效，若欲内服，勿过三厘。慎毋单使，必与牛黄、明矾、乳香、没药之类同用乃可。如疮已溃，欲其生肌长肉之际，得之作痛异常，不可不知也。","videoMemo":"","fangList":[],"bieMing":"蟾酥"}}', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2024-12-30T02:46:39.000Z', '2、蟾酥', '2024-12-30T02:46:39.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Ft5CihvqBxA');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ot5EZsVpZJR', 4, '{"title":"第400107328条・卷之二十三_果部三品","description":"<p>28、榧实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107328,"note":"     味甘，无毒。主五痔，去三虫，蛊毒，鬼疰。（木部移入。）\n\n      疏：榧实禀土气以生。本经味甘无毒。然尝其味多带微涩，详其用应是有苦，气应微寒。气薄味厚，阴也，降也。入手太阴、阳明经。五痔、三虫皆大肠湿热所致，苦寒能泻湿热，则肠清宁，而二证愈矣。其主蛊毒鬼疰者，以其甘能解毒，而苦寒能涤除肠胃邪恶气耳。\n\n【主治参与】\n孟诜《食疗》：治寸白虫，日食榧子七颗，满七日，虫皆化为水也。\n\n《简便方》：好食茶叶，面黄者，每日食榧子七枚，以愈为度。","videoMemo":"","fangList":[],"bieMing":"榧实"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '28、榧实', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9JVhieFc7La', 4, '{"title":"第400107327条・卷之二十三_果部三品","description":"<p>27、赤爪木实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107327,"note":"     味酸，冷，无毒。汁服主水痢，沐头及洗身上疮痒。（自木部移入。即今山查，一名棠梂。）\n\n     疏：山查禀木气而生。本经云：味酸气冷，然观其能消食积，行瘀血，则其气非冷矣。入足阳明、太阴经。二经有积滞，则成下痢。产后恶露不尽，蓄于太阴经部分，则为儿枕痛。山查能入脾胃，消积滞，散宿血，故主水痢及产妇腹中块痛也。大抵其功长于化饮食，健脾胃，行结气，消瘀血，故小儿，产妇宜多食之。本经误认为冷，故有洗疮痒之用。\n\n【主治参与】\n同矾红、黄连、红曲，消肉积。\n\n同红曲、麦芽、橘皮、白术、肉豆蔻、厚朴、砂仁，能消食健脾。\n\n同牛膝、生地黄、当归、续断、益母草、泽兰、牡丹皮、蒲黄、芍药，治产后儿枕作痛。\n\n《卫生易简方》偏坠疝气：山查肉、茴香炒各一两，为末，糊丸梧子大。每服一百丸，空心白汤下。\n\n【简误】\n       山查性能克化饮食，若胃家无食积，及脾虚不能运化，不思食者，多食之反致克伐脾胃生气。如脾虚兼有积滞者，当与补药同施，亦不宜过用也。《物类相感志》云：煮老鸡硬肉，入山查数颗即易烂。其消食克伐之力彰矣。","videoMemo":"","fangList":[],"bieMing":"赤爪木实"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '27、赤爪木实', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dbevBsLf0WN', 4, '{"title":"第400107326条・卷之二十三_果部三品","description":"<p>26、龙眼</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107326,"note":"       味甘，平，无毒。主五藏邪气，安志厌食，除虫去毒。久服强魂，聪明，轻身不老，通神明。（自木部移入。）\n\n       疏：龙眼禀稼穑之化，故其味甘，气平，无毒。入足太阴、手少阴经。少阴为君主之官，藏神而主血，甘能益血补心，则君主强，神明通，五脏邪气俱除矣。甘味补脾，脾得补则食自寡而饫。心得补则火下降而坎离交，故能安志。肝藏魄，主纳血，心家血满，则肝有所受而魂强。甘能解毒，故主去毒。久服聪明耳目，轻身不老，总之补益心脾之验也。至于除虫，非其所能，略之可也。\n\n【主治参与】\n同生地黄、天麦门冬、丹参、柏子仁、远志、莲实、五味子、茯神、人参，能补心保神，益气强志。\n\n严用和《济生方》归脾汤：治思虑过度，劳伤心脾，健忘怔忡，虚烦不眠，自汗惊悸，用龙眼肉、酸枣仁、炒黄耆、炙白术、焙茯神各一两，木香半两，炙甘草二钱半，㕮咀，每服五钱，姜三片，枣一枚，水二钟，煎一钟，温服。","videoMemo":"","fangList":[],"bieMing":"龙眼"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '26、龙眼', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NJUc7dCtmIt', 4, '{"title":"第400107325条・卷之二十三_果部三品","description":"<p>25、海松子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107325,"note":"      味甘，小温，无毒。主骨节风，头眩，去死肌，发白，散水气，润五藏，不饥。生新罗。\n\n      疏：海松子气味香美，甘温。甘温助阳气而通经，则骨节中风水气，及因风头眩、死肌自除矣。气温属阳，味甘补血，血气充足，则五脏自润，发白，不饥所由来矣。仙方服食，多饵此物，故能延年轻身不老也。","videoMemo":"","fangList":[],"bieMing":"海松子"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '25、海松子', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SRhCbQjiLWS', 4, '{"title":"第400107324条・卷之二十三_果部三品","description":"<p>24、胡桃</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107324,"note":"       味甘，平，无毒。食之令人肥健，润肌，黑发。取瓤烧令黑末，断烟，和松脂研傅瘰疬疮。又和胡粉为泥，拔白须发，以内孔中，其毛皆黑。多食利小便，能脱人眉，动风故也。去五痔。外青皮染髭。\n\n        疏：胡桃禀火土之气以生。本经虽云甘平，然其气多热而性润，益血脉，补命门之药也。血不充，则消瘦、肌肤不泽、及须发易白，益血故令人肥健，润肌，黑须发也。多食利小便者，以其能入肾固精，令水窍常通也。傅瘰疬者，甘热能解毒散结。去五痔，取其润肠除湿之功也。能脱人眉者，热极则生风，风甚则万物摇落之象也。青皮性涩，故能染髭。\n\n【主治参与】\n一味勿去黄皮，空腹食之，最能固精。\n\n同补骨脂、蒺藜、莲须、鹿茸、麦门冬、巴戟天、覆盆子、山茱萸、五味子、鱼胶，益命门，种子，最效。\n\n入青娥丸，能黑须发，补右肾，方见补骨脂条。\n\n《御药院方》胡桃丸：益血补髓，强筋壮骨，延年明目，悦心润肌，能除百病。用胡桃肉四两捣膏，入补骨脂、杜仲、萆薢末各四两，杵匀，丸梧子大。每空心温酒、盐汤任下五十丸。\n\n《普济方》产后气喘：胡桃肉、人参各二钱，水一盏，煎七分，顿服。\n\n李楼方：误吞铜钱，多食胡桃，自化出也。\n\n《圣惠方》揩齿乌须：胡桃仁烧过、贝母等分，为散，日日用之。\n\n《圣济总录》血崩不止：胡桃肉十五枚，烧存性，研作一服，空心温酒调下，神效。\n\n子和《儒门事亲》便毒初起。用胡桃七个，烧研，酒服，不过三服效。\n\n杨试《经验方》，鱼口便毒：端五日午时，取树上青胡桃，筐内阴干，临时全烧为末，酒服。少行一二次，有脓自大便出，无脓即消，二三服平。上二方，应加全蝎、穿山甲尤妙。\n\n《图经本草》压扑损伤：胡桃肉捣，和温酒顿服，便瘥。\n\n【简误】\n       胡桃，前人多言其有害不可食。孙思邈云：多食动痰饮，令人恶心吐水。苏颂云：性热不可多食。马志云：多食动风，脱人眉。同酒食，多令人咯血。汪颖曰：多食生痰动肾火。然而近世医方用治痰气喘嗽，和伤，补命门，润血脉、大肠，及疠风诸病，而酒家往往以之佐酒，则多食吐水、咯血、脱眉、动火之说，亦未尽然也。但性本热，惟虚寒者宜之。如肺家有痰热，命门火炽，阴虚吐衄等证，皆不得施。","videoMemo":"","fangList":[],"bieMing":"胡桃"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '24、胡桃', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QR0kIbIjC1E', 4, '{"title":"第400107323条・卷之二十三_果部三品","description":"<p>23、橄榄</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107323,"note":"       味酸、甘，温，无毒。主消酒，疗鯸鲐毒。\n\n        疏：橄榄，本经味酸、甘。今尝之先涩而后甘。得土中的阳气，气温无毒，肺胃家果也。能生津液，酒后嚼之不渴，故主消酒。甘能解毒，故疗鯸鲐毒也。马志云：鯸鲐即河豚也。人误食此鱼肝及子，必迷闷至死，惟橄榄汁煮服之，必解。其木作楫，拨着鱼皆浮出，故知物有相畏如此，不特味甘解毒之义也。\n\n【主治参与】\n食诸鱼被鲠，用橄榄嚼汁咽之。无橄榄时，即觅核研末，急流水调服，亦效。\n\n手抓碎成疮，用橄榄磨浓汁涂之，能灭瘢痕。\n\n《直指方》肠风下血：橄榄烧存性，研末。每服二钱，陈米饮调下。\n\n《乾坤生意》耳足冻疮：橄榄核烧研，油调涂之。","videoMemo":"","fangList":[],"bieMing":"橄榄"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '23、橄榄', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NFQkzH57Ky2', 4, '{"title":"第400107322条・卷之二十三_果部三品","description":"<p>22、梨</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107322,"note":"      味甘、微酸，寒。多食令人寒中。金疮、乳妇尤不可食。\n\n       疏：梨成于秋，花实皆白，其得西方之阴气者乎！味甘微酸，气寒无毒。入手太阴，兼入足阳明经。\n\n    《别录》著梨，止言其害，不叙其功。陶隐居言梨不入药。盖古人论病，多主于风寒外邪，以温热为补，药多桂、附。凡冷利之物，辍而不用也。不知时运迭降，禀受递殊。今时之人，火病、热病、痰病，往往皆是。梨能润肺消痰，降火除热，故苏恭主热嗽，止渴，贴汤火伤，治客热，中风不语，伤寒寒热，解丹石热气，惊邪，利大小便。大明主贼风，心烦，气喘，热狂。孟诜主胸中痞塞热结等，诚不可阙者也。本经言多食令人寒中者，以其过于冷利也。乳妇、金疮不可食者，以血得寒则凝而成瘀为病也。凡人有痛处，脉数无力，或发渴，此痈疽将成之候，惟昼夜食梨，可转重为轻。膏粱之家，厚味酽酒，纵恣无节，必多痰火卒中。痈疽之病，数食梨，可变危为安。功难尽述。\n\n【主治参与】\n梨汁，同霞天膏、竹沥、童便，治中风痰热。\n\n同人乳、蔗浆、芦根汁、童便、竹沥，治血液衰少，渐成噎膈。\n\n《普济方》消渴饮水：用香水梨，或鹅梨、雪梨皆可，取汁以蜜和熬成膏，瓶收。不时白汤调服一二匙。\n\n崔元亮《海上方》：卒得咳嗽，用上好梨去核，捣汁一碗，入椒四十粒，煎一沸，去滓，纳黑饧一大两，消讫，细细含咽，立定。\n\n《食疗本草》暗风失音：捣梨汁一盏饮之，日再服。\n\n《圣惠方》小儿风热，昏懵躁闷，不能食：用消梨三枚切破，以水二升，煮取汁一升，入粳米一合，煮粥食之。\n\n治小儿内热，痰壅喉间吐不出，或因惊热生痰，或因风热生痰：取梨汁时时与之，加牛黄分许，神效。\n\n《图经》：赤目胬肉，日夜痛者，取好梨一颗捣绞汁，以黄连切片一钱浸汁内，取汁，仰卧点之。\n\n《圣济总录》反胃转食，药物不下：用大雪梨一个，以丁香十五粒，刺入梨内，湿纸包四五重，煨熟，去丁香，食之。\n\n【简误】\n         肺寒咳嗽，脾家泄泻，腹痛冷积，寒痰痰饮，妇人产后，小儿痘后，胃冷呕吐，及西北真中风证，法咸忌之。","videoMemo":"","fangList":[],"bieMing":"梨"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '22、梨', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('A13mMr7cx42', 4, '{"title":"第400107321条・卷之二十三_果部三品","description":"<p>21、杏仁,杏核仁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107321,"note":"       味甘、苦，温，冷利，有毒。主咳逆上气雷鸣，喉痹，下气，产乳金疮，寒心，贲豚，惊痫，心下烦热，风气去来，时行头痛，解肌，消心下急，杀狗毒。\n\n       疏：杏核仁禀春温之气，而兼火土之化以生。故《本经》味甘，气温。《别录》加苦，有毒。其言冷利者，以其性润利下行之故，非真冷也。气薄味厚，阴中微阳，降也。入手太阴经。太阴为清肃之脏，邪客之则咳逆上气。火炎乘金，则为喉痹。杏仁润利而下行，苦温而散滞，则咳逆上气、喉痹俱除矣。其主心下烦热者，邪热客于心肺之分也。风气去来，时行头痛者，肺主皮毛，风邪自外而入也。温能解肌，苦能泄热，故仲景麻黄汤中用之，亦取其有发散之功也。主产乳、金疮者，亦指为风寒所乘者言之。消心下急者，以其润利而下气也。心寒贲豚者，心虚而肾邪凌之也。惊痫者，痰热盛也。雷鸣者，大肠不和也。总之取其下气消痰，温散甘和，苦泄润利之功也。\n\n【主治参与】\n同桑根白皮、前胡、薄荷、桔梗、苏子、贝母、甘草、五味子、橘红、紫菀，治风寒入肺，咳嗽生痰。\n\n入麻黄汤，治太阳病无汗，恶寒，喘急。\n\n《千金方》咳逆上气：以杏仁三升去皮尖，炒黄研膏，入蜜一合，杵熟。每食前含之，咽汁。\n\n《梅师方》食狗肉不消，心下坚胀，口干，发热妄语：杏仁一升去皮尖，水三升，煎减半，取汁分三服，效。\n\n【简误】\n       杏仁性温，散肺经风寒滞气殊效。第阴虚咳嗽，肺家有虚热，热痰者忌之。风寒外邪，非壅逆肺分，喘急息促者，不得用。产乳、金疮无风寒击袭者，不得用。惊痫，喉痹，亦非必须之药。用者详之。双仁者能杀人。《本经》言有毒，盖指此耳。","videoMemo":"","fangList":[],"bieMing":"杏仁,杏核仁"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '21、杏仁,杏核仁', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l635IQ2fq0e', 4, '{"title":"第400107320条・卷之二十三_果部三品","description":"<p>20、桃枭,桃奴</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107320,"note":"      味苦微温。主杀百鬼精物，疗中恶腹痛，杀精魅五毒不祥。一名桃奴。\n\n       疏：桃枭是桃实着树经冬不落者，正月采之。桃为五木之精，仙木也，最能辟邪。今道家禁咒镇魇之术，犹有用桃木者。《本经》以桃枭主杀诸精鬼不祥，亦此意耳。况着于树上最久，得气尤全，苦温之性，又能通滞散邪者乎？治血之功，与桃仁同。\n\n【主治参与】\n桃枭煅存性，同棕皮灰、蒲黄、朱砂、京墨，为末，临卧以童便调服三钱，小便解，色渐淡为度。治内伤吐血神效。\n\n同番降香、辰砂，治鬼击吐血。\n\n《圣惠方》伏梁结气在心下不散：桃奴三两为末，空心温酒下，每服二钱。","videoMemo":"","fangList":[],"bieMing":"桃枭,桃奴"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '20、桃枭,桃奴', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T3Ba4KZIhaw', 4, '{"title":"第400107319条・卷之二十三_果部三品","description":"<p>19、桃仁,桃核仁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107319,"note":"       味苦、甘，平，无毒。主瘀血血闭瘕，邪气，杀小虫，止咳逆上气，消心下坚，除卒暴击血，破癥瘕，通月水，止痛。\n\n        疏：桃核仁禀地二之气，兼得天五之气以生，故其味苦重、甘微，气平无毒。思邈言辛，孟诜言温，皆有之矣。气薄味厚，阳中之阴，降也。入手、足厥阴经。夫血者，阴也，有形者也。周流乎一身者也。一有凝滞，则为癥瘕，瘀血血闭，或妇人月水不通，或击扑伤损积血，及心下宿血坚痛，皆从足厥阴受病，以其为藏血之脏也。苦能泄滞，辛能散结，甘温通行而缓肝，故主如上等证也。心下宿血去则气自下，咳逆自止。桃为五木之精，能镇辟不祥，故主邪气。味苦而辛，故又能杀小虫也。\n\n【主治参与】\n仲景桃仁承气汤：治伤寒湿热在内，小便利而大便黑，为蓄血，用桃仁五十粒，桂枝二两，大黄四两，芒硝二两，甘草一两，以水七升，煮取二升半，去滓，内芒硝，更上火微沸，空心温服五合，日三，当微利。\n\n入抵当汤，治太阳病六七日，表证仍在，脉微而沉，反不结胸，其人如狂者，以热结在下焦，少腹当硬满，小便自利，下血乃愈。用桃仁二十粒，水蛭三十个熬，虻虫三十个去翅足熬，大黄三两酒浸，以水五升，煮取三升，温服一升，不下再服。\n\n同当归、芍药、泽兰、延胡索、苏木、五灵脂、红花、牛膝、生地黄、益母草，治产后瘀血，结块作痛，并治壮盛妇人经闭不通。\n\n同当归、麻仁、地黄、麦门冬、芍药、黄芩、肉苁蓉、甘草，治大肠血燥，便结不通。\n\n同番降香、川通草、山查、穿山甲、乳香、没药、红花、续断、当归，治上部内伤，瘀血作痛。\n\n《圣济总录》大便不快，里急后重：用桃仁三两去皮，以吴茱萸二两，食盐一两，同炒熟，去二物，每嚼桃仁五七粒，效。兼可预辟瘴疠。\n\n《删繁方》：妇人难产，数日不出。桃仁一个劈开，用朱砂书一片 “可” 字，一片 “出” 字，吞之即生。\n\n《肘后方》妇人阴痒：桃仁杵烂，绵裹塞之。杏仁亦可用。\n\n【简误】\n      桃仁性善破血，凡血结、血秘、血燥、瘀血、留血、蓄血、血痛、血瘕等证，用之立通。第散而不收，泻而无补，过用之及用之不得其当，能使血下不止。损伤真阴，为害非细。故凡经闭不通由于血枯，而不由于瘀滞；产后腹痛由于血虚，而不由于留血结块；大便不通由于津液不足，而不由于血燥闭结，法并忌之。","videoMemo":"","fangList":[],"bieMing":"桃仁,桃核仁"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '19、桃仁,桃核仁', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oPWi1CrX9OZ', 4, '{"title":"第400107318条・卷之二十三_果部三品","description":"<p>18、沙糖</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107318,"note":"      味甘，寒，无毒。功用与石蜜同，而冷利过之。\n       \n       疏：沙糖，蔗汁之清而煎炼至紫黑色者。本经虽云与石蜜同功，然而不逮石蜜多矣。既经煎炼之久，则未免有湿热之气，故多食损齿生虫，发疳胀满，令人心痛等害。与鲫鱼同食成疳虫，与葵同食生流澼，与笋同食不消成癥，身重不能行。今医家用作汤，下小儿丸散，殊为未当。","videoMemo":"","fangList":[],"bieMing":"沙糖"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '18、沙糖', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TKN2mfpdAVv', 4, '{"title":"第400107317条・卷之二十三_果部三品","description":"<p>17、甘蔗</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107317,"note":"      味甘，平，无毒。主下气，和中，助脾气，利大肠。\n\n       疏：甘蔗禀地中之冲气，故味甘气平无毒。日华子云：冷。气薄味厚，阳中之阴，降也。入手足太阴、足阳明经。甘为稼穑之化，其味先入脾，故能助脾气。脾主中州，故主和中。甘寒除热润燥，故主下气，利大肠也。大明为其消痰止渴，除心胸烦热，解酒毒。今人用以治噎膈反胃呕吐，大便燥结。皆取其除热生津润燥之功耳。\n\n【主治参与】\n蔗浆一味单服，能润大便，下燥结。\n\n同芦根汁、梨汁、藕汁、人乳、童便、竹沥，和匀。时时饮之，治胃脘干枯，噎食呕吐。\n\n《梅师方》反胃吐食：蔗浆七升，姜汁半升，和匀，日日细呷。\n\n【简误】\n甘蔗，世人皆以其性热，不敢多食，不知乃是甘寒之物，能泻火热，润枯燥。唐王摩诘 “樱桃诗” 云：饱食不须愁内热，大官还有蔗浆寒。可为证矣。惟胃寒呕吐，中满滑泄者，忌之。","videoMemo":"","fangList":[],"bieMing":"甘蔗"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '17、甘蔗', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XI3oI1NudLb', 4, '{"title":"第400107316条・卷之二十三_果部三品","description":"<p>16、石蜜</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107316,"note":"     味甘，寒，无毒。主心腹热胀，口干渴，性冷利。\n\n      疏：石蜜乃煎甘蔗汁曝之，凝如石，而体甚轻，今之白沙糖也。其味甘，其气寒，其用在脾，故主心腹热胀。甘寒能除热生津液，故止口干渴，及咳嗽生痰也。多食亦能害脾，以其味太甘耳。","videoMemo":"","fangList":[],"bieMing":"石蜜"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '16、石蜜', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5QKJoXXylQ6', 4, '{"title":"第400107315条・卷之二十三_果部三品","description":"<p>15、荔枝子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107315,"note":"      味甘，平，无毒。止渴，益人颜色。\n\n       疏：荔枝子，南方果也。感天之阳气，得地之甘味。本经虽云平，而其气实温也。鲜时味极甘美，多津液，故能止渴。甘温益血，助荣卫，故能益人颜色也。多食令人发热，或衄血、齿痛者，以其生于炎方，熟于夏月，故善助火发热耳。\n\n入药甚稀，无 “主治”、“简误”。\n\n 核：味甘，温。主心痛，小肠气痛，㿗疝，妇人血气刺痛。以一枚煨存性，研末，酒调服。盖其气温而通行，入肝者，散滞气，辟寒邪，所以能疗如上诸证也。\n\n【主治参与】\n荔枝核同牛膝、补骨脂、延胡索、合欢子、茴香、木瓜、杜仲、橘核、萆薢，治疝气。虚热者加黄檗，虚寒加桂。\n\n孙氏方：治疝气㿗肿，荔枝核炒黑色，大茴香炒，等分为末。每服一钱，温酒下。\n\n又方，肾肿如斗：荔枝核、青橘皮、茴香等分，各炒研。酒服二钱，日三。\n\n除疝气外无他用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"荔枝子"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '15、荔枝子', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0RUP7v174YZ', 4, '{"title":"第400107314条・卷之二十三_果部三品","description":"<p>14、枇杷叶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107314,"note":"    味苦，平，无毒。主卒啘不止，下气。\n\n     疏：枇杷叶禀天地清寒之气，四时不凋，其味苦，气平，平即凉也，无毒。入手太阴、足阳明经。气薄味厚，阳中之阴，降也。《经》曰：诸逆冲上，皆属于火。火气上炎，则为卒啘不止。啘者，哕也，其声浊恶而长。经曰：树枯者叶落，病深者声哕。病者见此，是为危证。枇杷叶性凉，善下气，气下则火不上升，而胃自安，故卒啘止也。其治呕吐不止，妇人产后口干，男子消渴，肺热咳嗽，喘息气急，脚气上冲，皆取其下气之功。气下则火降痰顺，而呕者不呕，渴者不渴，咳者不咳，冲逆者不冲逆矣。又治妇人发热咳嗽，经事先期，佐补阴清热之药，服之可使经期正而受孕。\n\n【主治参与】\n同生地黄、麦门冬、白芍药、炙甘草、枸杞子、桑根白皮、童便、茅根、天门冬、苏子、五味子、栝楼根，治阴虚咳嗽吐血。\n\n入噙化丸，治肺热咳嗽：同竹茹、木瓜、芦根汁、石斛、麦门冬、人参、白茯苓，治胃热呕吐。加童便、人乳、竹沥、苏子、白芍药、蔗浆，治噎膈反胃。\n\n同白芍药、生地黄、青蒿子、五味子、黄檗、阿胶、枸杞子、杜仲、牡丹皮、鳖甲作丸，治妇人经行先期，发热无孕。\n\n同人参、白芍药、茯苓、竹茹、橘红、苏子、麦门冬、木瓜，治妊娠恶阻。\n\n同栝楼根、天门冬、枸杞子、五味子、石斛、白芍药、黄连、甘草、芦根汁、童便、竹叶，治消渴。\n\n庞安常方：温病发哕，因饮水多者，枇杷叶去毛炙香，茅根各半斤，水四升，煎二升，稍稍饮之。\n\n《圣惠方》衄血不止：枇杷叶去毛，焙研末，茶服一二钱，日二服。\n\n【简误】\n       胃寒呕吐，及肺感风寒咳嗽者，法并忌之。","videoMemo":"","fangList":[],"bieMing":"枇杷叶"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '14、枇杷叶', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r6JYZauBmqW', 4, '{"title":"第400107313条・卷之二十三_果部三品","description":"<p>13、乌芋</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107313,"note":"      味苦、甘，微寒，无毒。主消渴痹热，温中益气。一名荸脐。\n\n       疏：乌芋，禀土金之气以生。本经味苦、甘，气微寒，无毒。然详其用，味应有辛，辛能散，苦能泄，故主痹热。甘寒能除热而生津，故主消渴。热去则气自益，气益则中自温，自然之道也。孟诜主下丹石，消黄疸，除胸中实热气。汪机主疗五种膈气，消宿食，治误吞铜物，及今人治腹胀下血等证，皆取其辛寒消散除热之功也。\n\n【主治参与】\n乌芋去皮，填入雄猪肚肉，线缝，砂器煮糜食之，勿入盐，治腹满胀大。\n\n善毁铜，铜器中煮之即烊。\n\n误吞铜物，以乌芋合胡桃食一二斤许，即消。\n\n一味晒干，为末服，能辟蛊毒。\n\n《神秘方》大便下血：荸脐捣汁大半钟，入酒少许，温服，三日见效。\n\n【简误】\n孟诜云：乌芋性冷，先有冷气人不可食。多食令人患脚气。又孕妇忌之。","videoMemo":"","fangList":[],"bieMing":"乌芋"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '13、乌芋', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oIs71nuv8Zm', 4, '{"title":"第400107312条・卷之二十三_果部三品","description":"<p>12、柿</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107312,"note":"   味甘，寒，无毒。主通鼻耳气，肠澼不足。\n\n    疏：柿禀地中之阴气以生，故味甘，气寒，无毒。入手、足太阴经。鼻者，肺之窍也。耳者，肾之窍也。金水二脏最忌火热，二脏有火上炎，则外窍闭而不通。得甘寒之气，俾火热下行，窍自清利矣。肺与大肠为表里，湿热伤血分，则为肠澼不足。甘能益血，寒能除热，脏气清而腑病亦除也。\n\n干柿：寒气稍减，能厚肠胃，补不足，润肺止渴，功同于前。\n\n柿霜：清心肺间热，生津止渴，化痰宁嗽，治喉舌口疮。总之其功长于清肃上焦火邪，兼能益脾开胃，故三者所主虽不同，而其源皆归于一义也。\n\n【主治参与】\n        柿霜得桑根白皮、百部、天麦门冬、沙参、贝母、苏子、枇杷叶、橘红、栝楼根，作丸噙化，治肺经有火，咳嗽生痰。\n\n【简误】\n柿性寒，肺经无火，因客风寒作嗽者，忌之。冷痢滑泄，肠胃虚脱者，忌之。脾家素有寒积，及感寒腹痛、感寒呕吐者，皆不得服。不宜与蟹同食，令人腹痛作泻。","videoMemo":"","fangList":[],"bieMing":"柿"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '12、柿', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nPmyee339RR', 4, '{"title":"第400107311条・卷之二十三_果部三品","description":"<p>11、木瓜实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107311,"note":"       味酸，温，无毒，主湿痹脚气，霍乱大吐下，转筋不止。\n\n        疏：木瓜实得春生之气，禀曲直之化，故其味酸，气温性无毒。气薄味厚，降多于升，阳中阴也。入足太阴、阳明，兼入足厥阴。其主湿痹脚气者，以脾主四肢，又主肌肉，性恶湿而喜燥，湿侵肌肉，则为湿痹，伤足络则成脚气。木瓜温能通肌肉之滞，酸能敛濡满之湿，则脚气、湿痹自除也。霍乱大吐下，转筋不止者，脾胃病也。夏月暑湿饮食之邪伤于脾胃，则挥霍撩乱，上吐下泻，甚则肝木乘脾而筋为之转也。酸温能和脾胃，固虚脱，兼之入肝而养筋，所以能疗肝脾所生之病也。藏器治脚气冲心，强筋骨，下冷气，止呕逆。大明主吐泻，水肿，心腹痛。好古治腹胀善噫，心下烦痞。无非取其去湿和胃，滋脾益肺，利筋骨，调荣卫，通行收敛，有并行不悖之功也。\n\n【主治参与】\n得白扁豆、藿香、白茯苓、橘皮、白梅、人参、白术、甘草、砂仁、香薷，治伤暑霍乱，吐泻不止。加入石斛、鸡舌香，治转筋。\n\n同当归、石斛、牛膝、续断、芍药、橘皮，治血虚转筋。\n\n同薏苡仁、术、茯苓、五加皮、石斛、萆薢、黄檗，治湿热脚气。\n\n同人参、白茯苓、麦门冬、藿香、白豆蔻、竹茹、枇杷叶，治胃虚呕吐。\n\n一味末之，白汤吞三钱，日五服，治杨梅结毒有效。\n\n入六和汤，治暑月霍乱。\n\n《圣惠方》治霍乱转筋：木瓜一两，酒一升，煎服。不饮酒者，煎汤服。仍煎汤浸青布裹其足。\n\n《御药院方》四蒸木瓜丸：治肝肾脾三经气虚，为风寒暑湿相搏，流注经络。凡遇时令不和，七情怫郁，必致发动，或肿满，或顽痹，憎寒壮热，呕吐自汗，霍乱吐利，用宣州大木瓜四个，切盖剜空听用。一个入黄耆、续断末各半两于内，一个入苍术、橘皮末各半两于内，一个入乌药、黄松节末各半两于内，黄松节即茯神心中木也，一个入威灵仙、苦葶苈末各半两于内。以原盖盖好拴定，用酒浸透，入甑内蒸熟，晒干，再浸蒸，如此三度，捣末，以榆皮末水和，糊丸如梧子大。每服五十丸，温酒、盐汤任下。\n\n《医林集要》翻花痔疮：木瓜为末，以鱓鱼身上涎，调贴之，以纸护住。\n\n【简误】\n      下部腰膝无力，由于精血虚，真阴不足者，不宜用。伤食，脾胃未虚，积滞多者，不宜用。入药忌犯铁器。","videoMemo":"","fangList":[],"bieMing":"木瓜实"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '11、木瓜实', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5OOb5Y2kbRo', 4, '{"title":"第400107310条・卷之二十三_果部三品","description":"<p>10、梅实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107310,"note":"      味酸，平，无毒。主下气，除热烦满，安心，肢体痛，偏枯不仁，死肌，去青黑痣，恶疾，止下痢，好唾口干。\n\n       疏：梅实，即今之乌梅也。梅得木气之全，故其味最酸，所谓曲直作酸是也。《经》曰：热伤气。邪客于胸中，则气上逆而烦满，心为之不安。乌梅味酸，能敛浮热，能吸气归元，故主下气，除热烦满，及安心也。下痢者，大肠虚脱也。好唾口干者，虚火上炎，津液不足也。酸能敛虚火，化津液，固肠脱，所以主之也。其主肢体痛，偏枯不仁者，盖因湿气侵于经络，则筋脉弛纵，或疼痛不仁。肝主筋，酸入肝而养筋，肝得所养，则骨正筋柔，机关通利，而前证除矣。其主去死肌、青黑痣、恶肉者、白梅之功也。白梅味咸，咸能软坚故也。又能消痰，醒睡，止霍乱，解酒毒。弘景云：生梅、乌梅、白梅功用大约相似，第乌梅较良，资用更多。\n\n【主治参与】\n乌梅同川黄连、白芍药、滑石、甘草、莲肉、白扁豆、葛根、升麻、红曲、橘红作丸，治滞下如神。\n\n一味作汤，代茶饮，治火炎头痛。\n\n仲景乌梅丸：治蛔厥，蛔上入膈，故烦，须臾复止，得食而呕，又烦者，蛔闻食即出故耳。用乌梅三百个，细辛、附子、人参、桔梗、黄檗各六两，当归、蜀椒各四两，黄连一斤，干姜十两，捣乌梅肉和丸桐子大。先食饮服十丸，日三服。\n\n《刘涓子鬼遗方》蚀恶疮努肉：用乌梅肉烧为灰，傅上，恶肉立尽。\n\n《圣惠方》赤痢腹痛：乌梅肉、黄连各四两，炼蜜丸梧子大。每米饮下二十丸，日三服。\n\n《图经本草》治劳疟，用乌梅十四枚，豆豉二合，甘草三寸，生姜一块，以童便二升，煎去一半，温服即止。\n\n治暑气霍乱：白梅一个，和仁捣碎，入丝瓜叶一叶，或扁豆叶，再捣烂，用新汲水调，灌下即解。\n\n【简误】\n      《素问》云：味过于酸，肝气以津。又云：酸走筋，筋病无多食酸。以肝主筋，性喜升发，酸味敛束，是违其性之所喜也。梅实过酸，不宜多食。齿痛及病当发散者，咸忌之。","videoMemo":"","fangList":[],"bieMing":"梅实"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '10、梅实', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5jhcxA8IZZ5', 4, '{"title":"第400107309条・卷之二十三_果部三品","description":"<p>9、芡实,鸡头实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107309,"note":"     味甘，平、寒，无毒。主补中养神，益气力，除百疾。久服轻身耐老，不饥延年。\n\n     疏：藕实得天地清芳之气，禀土中冲和之味，故味甘气平。《别录》寒，无毒。入足太阴、阳明，兼入手少阴经。土为万物之母，后天之元气藉此以生化者也。母气既和则血气生，神得所养而疾病无由来 \n矣。藕实正禀稼穑之化，乃脾家之果，故主补中养神，益气力，除百疾，及久服轻身耐老，不饥延年也。孟诜主五脏不足伤中，益十二经脉血气。大明主止渴去热，安心，止痢，治腰痛及泄精。多食令人喜，皆资其补益心脾之功也。\n\n【主治参与】\n得川黄连、白芍药、白扁豆、干葛、升麻、红曲、橘红、甘草、滑石、乌梅为丸，治滞下如神。\n\n下痢饮食不入，俗名噤口痢。此证大危，用鲜莲肉一两，黄连五钱，人参五钱，水煎浓。细细与呷，服完思食便瘥。同菟丝子、五味子、山茱萸、山药、车前子、肉豆蔻、砂仁、橘红、芡实、人参、补骨脂、巴戟天，治脾肾俱虚，五更溏泻。有肺热者去人参、肉豆蔻。\n\n孟诜《食疗》服食不饥：石莲肉蒸熟去心，为末，炼蜜丸梧子大。日服三十丸。此仙家方也。\n\n《普济方》白浊遗精：石莲肉、龙骨、益智仁等分，为末。每服二钱，空心米饮下。\n\n《直指方》心虚赤浊：莲子六一汤：用石莲肉六两，炙甘草一两，为末。每服一钱，灯心汤下。\n\n《丹溪心法》久痢噤口：石莲肉炒为末，每服二钱，陈仓米汤调下，便觉思食，甚妙。\n\n君山药、白茯苓、白术、人参、莲肉、薏苡仁、白扁豆，为补脾胃要药。\n\n一味捣末，熬金樱子煎，和丸。服之补下元益人，谓之水陆丹。\n\n《经验方》鸡头粥法：用鸡头实三合，煮熟去壳，粳米一合煮粥，日日空心食。能益精气，强志意，利耳目。\n\n《永类钤方》四精丸：治思虑色欲过度，损伤精气，小便数，遗精。用秋石、白茯苓、芡实、莲肉各二两，为末，蒸枣和丸梧子大。每服三十丸，空心盐汤送下。\n\n【简误】\n芡实生食味涩，动风冷气，小儿不宜多食，以其难消化也。","videoMemo":"","fangList":[],"bieMing":"芡实,鸡头实"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '9、芡实,鸡头实', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wenRK4ZWYA8', 4, '{"title":"第400107308条・卷之二十三_果部三品","description":"<p>8、覆盆子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107308,"note":"     味甘，平，无毒。主益气轻身，令发不白。\n\n     疏：覆盆子得木气而生，本经味甘，气平，无毒；甄权微热，宗奭酸甘，深得其义。入足少阴经。其主益气者，言益精气也。肾藏精，肾纳气，精气充足则身自轻，发不白也。苏恭：立补虚续绝，强阴健阳，悦泽肌肤，安和脏腑。甄权：主男子肾精虚竭，阴痿。女子食之有子。大明：主安五脏，益颜色，养精神，长发，强志。皆取其益肾添精，甘酸收敛之义耳。\n\n【主治参与】\n同黄檗、沙苑蒺藜、莲须、五味子、砂仁、鱼胶、山茱萸，治梦遗泄精。\n\n同车前子、五味子、菟丝子、蒺藜子，为五子衍宗丸。治男子精气亏乏，中年无子。\n\n加入巴戟天、腽肭脐、补骨脂、鹿茸、白胶、山茱萸、肉苁蓉，治阳虚阴痿，临房不举，或精寒精薄。\n\n【简误】\n强阳不倒者忌之。","videoMemo":"","fangList":[],"bieMing":"覆盆子"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '8、覆盆子', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('71O3X9rFK4Y', 4, '{"title":"第400107307条・卷之二十三_果部三品","description":"<p>7、大枣</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107307,"note":"     味甘，平，无毒。主心腹邪气，安中养脾，助十二经，平胃气，通九窍，补少气、少津液、身中不足，大惊，四肢重，和百药，补中益气强力，除烦闷，疗心下悬，肠澼。久服轻身延年，不饥神仙。\n\n      疏：大枣纯得土之冲气，兼感天之微阳以生。《本经》味甘，气平，无毒。东垣、孟诜言温。气味俱厚，阳也。入足太阴、阳明经。《经》曰：里不足者，以甘补之。又曰：形不足者，温之以气。甘能补中，温能益气，甘温能补脾胃而生津液，则十二经脉自通，九窍利，四肢和也。正气足则神自安，故主心腹邪气，及大惊。中得缓则烦闷除，故疗心下悬急，及少气。脾得补则气力强，肠胃清，故主身中不足及肠澼。甘能解毒，故主和百药。脾胃足，气血充，后天生气借此而盈溢，故久服轻身长年，不饥神仙也。然亦指辟谷修炼者言之，非恒人所能耳。\n\n【主治参与】\n大枣甘温，能和阴阳，调荣卫，生津液。凡邪在荣卫者，辛甘以解之，故仲景桂枝汤，用姜、枣以和荣卫，助脾胃，生津液，令出汗也。\n\n仲景治伤寒水饮胁痛，咳而干呕者，有十枣汤，取其益土而胜水也。\n\n又方，发汗后，小便利，其人脐下悸，欲作奔豚者，茯苓桂枝甘草大枣汤主之。茯苓能伐肾邪，桂枝泄奔豚，甘草、大枣之甘，滋助脾土，以平肾气。\n\n许叔微《本事方》治妇人脏躁，悲伤欲哭，象若神凭，数欠者，大枣汤：大枣十枚，小麦一升，甘草二两，每服一两，水煎服之。\n\n【简误】\n         枣虽能补脾胃、益气，然而味过于甘，中满者忌之。小儿疳病不宜食，齿痛及患痰热者不宜食。生者尤不利人，多食致寒热。","videoMemo":"","fangList":[],"bieMing":"大枣"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '7、大枣', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lnDVWITDGi8', 4, '{"title":"第400107306条・卷之二十三_果部三品","description":"<p>6、橘叶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107306,"note":"       古今方书不载，能散阳明、厥阴经滞气。妇人妒乳、内外吹、乳岩、乳痈用之皆效。以诸证皆二经所生之病也。","videoMemo":"","fangList":[],"bieMing":"橘叶"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '6、橘叶', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('398B5jYRJSR', 4, '{"title":"第400107305条・卷之二十三_果部三品","description":"<p>5、橘核</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107305,"note":"     主腰痛，膀胱气，肾冷。炒去壳，酒服良。\n      按：橘核出日华子，其味苦温而下气，所以能入肾与膀胱，除因寒所生之病也。疝气方中多用。","videoMemo":"","fangList":[],"bieMing":"橘核"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '5、橘核', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fT8S2oHSgwK', 4, '{"title":"第400107304条・卷之二十三_果部三品","description":"<p>4、青皮,青橘</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107304,"note":"    主气滞，下食，破积结及膈气。\n\n     疏：青皮古方无用者，至宋时医家始用之。其色青，其味极苦而辛，其气温而无毒。气味俱厚，沉而降，阴也。入足厥阴、少阳。苦泄、辛散，性复刻削，所以主气滞，下食，破结积及膈气也。元素：破坚癖，散滞气，治左胁肝经积气。亦此意耳。\n\n【主治参与】\n青皮同人参、鳖甲，能消疟母。\n\n同枳壳、肉桂、川芎，治左胁痛。\n\n同人参、白术、三棱、蓬茂、阿魏、矾红、山查、红曲、木香，消痃癖气块，及一切肉食坚积。\n\n【简误】\n       青皮性最酷烈，削坚破滞是其所长。然误服之，立损人真气，为害不浅。凡欲使用，必与人参、术、芍药等补脾药同用，庶免遗患，必不可单行也。肝脾气虚者，概勿施用。","videoMemo":"","fangList":[],"bieMing":"青皮,青橘"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '4、青皮,青橘', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v6idTkbWN9m', 4, '{"title":"第400107303条・卷之二十三_果部三品","description":"<p>3、陈皮,橘皮</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107303,"note":"       味辛，温，无毒。主胸中瘕热逆气，利水谷，下气止呕咳，除膀胱留热停水，五淋，利小便，主脾不能消谷，气冲胸中，吐逆霍乱，止泄，去寸白。久服去臭，下气通神，轻身长年。（按：橘、柚实两种，《本经》作一条，盖传误也。今改正。）\n\n        疏：橘皮，花开于夏，实成于秋，得火气少，金气多，故味辛苦，气温无毒。味薄气厚，降多升少，阳中之阴也。入手足太阴、足阳明经。其主胸中瘕热逆气，气冲胸中呕咳者，以肺主气，气常则顺，气变则逆，逆则热聚于胸中而成瘕。瘕者，假也。如痞满郁闷之类也。辛能散，苦能泄，温能通行，则逆气下，呕咳止，胸中瘕热消矣。脾为运动磨物之脏，气滞则不能消化水谷，为吐逆霍乱，泄泻等证，苦温能燥脾家的湿，使滞气运行，诸证自瘳矣。肺为水之上源，源竭则下流不利，热结膀胱。肺得所养而津液贯输，气化运动，故膀胱留热停水，五淋皆通也。去臭及寸白者，辛能散邪，苦能杀虫也。通神轻身长年者，利脾肺之极功也。\n\n【主治参与】\n橘皮留白，补脾胃和中；去白，消痰理肺气。同白术则补脾，同甘草则补肺，同补气药则益气，同泄气药则破气，同消痰药则能去痰，同消食药则能化食，各从其类以为用也。\n\n同人参、何首乌、桂枝、当归、姜皮，治三日疟寒多。\n\n得白豆蔻、生姜、藿香、半夏，治胃家有寒痰，或偶感寒气，伤冷食，呕吐不止。\n\n同人参、白术、白茯苓、甘草、山药、白豆蔻、藿香、麦芽、山查、白扁豆，治脾胃虚，饮食不化，或不欲食，食亦无味。\n\n同苏子、贝母、枇杷叶、麦门冬、桑根白皮、沙参、栝楼根、五味子、百部，治上气咳嗽，能消痰下气。\n\n同枳壳、乌药、木香、草豆蔻、槟榔，治气实人暴气壅胀。\n\n同苍术、厚朴、甘草，为平胃散，治胸中胀满。\n\n入二陈汤，治脾胃湿痰及寒痰痰饮。\n\n仲景方：橘皮汤：治男女伤寒，并一切杂病呕哕，手足逆冷者，用橘皮四两，生姜一两，水二升，煎一升，徐徐呷之即止。\n\n《百一选方》霍乱吐泻，但有一点胃气存者，服之即生：广陈皮去白五钱，真藿香五钱，水二盏，煎一盏，时时温服。\n\n《食疗》治脚气冲心，或心下结硬，腹中虚冷：陈皮一斤和杏仁五两去皮尖熬，少许蜜捣和，丸如梧桐子大，每日食前米饮下三十丸。\n\n《普济方》大肠闭塞：陈皮连白，酒煮焙干，研末。每服二钱，米饮下。\n\n《适用方》脾寒诸疟，不拘老少孕妇，只两服便止：真橘皮去白切，生姜自然汁浸过一指，银石器内重汤煮干，焙，研末，每服三钱，用隔年青州枣十个，去核，水一盏，煎半盏，发前服，以枣下之。\n张氏方：妇人乳痈，未成者即散，已成者即溃，痛极者不痛，神验不可言。用真橘皮汤浸去白，晒干，面炒微黄，为末。每服二钱，麝香调酒下，初发一服见效。\n\n【简误】\n         橘皮味辛气温，能耗散真气，中气虚，气不归元者，忌与耗气药同用。胃虚有火呕吐，不宜与温热香燥药同用。阴虚咳嗽生痰，不宜与半夏、南星等同用。疟非寒甚者，亦勿施。","videoMemo":"","fangList":[],"bieMing":"陈皮,橘皮"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '3、陈皮,橘皮', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dFQ39r7Tf3p', 4, '{"title":"第400107302条・卷之二十三_果部三品","description":"<p>2、藕</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107302,"note":"     《唐本》注：主热渴，散血生肌。久服令人心欢。《药性论》云：藕汁，味甘，能消瘀血不散。藕节，捣汁主吐血不止，或口鼻出血。孟诜云：生食之，主霍乱后虚渴烦闷不能食。其产后忌生冷物，惟藕不同生冷，为能破血故也。蒸食甚补五脏，实下焦。陈藏器云：消食止泄，除烦，解酒毒，及病后热渴。日华子云：止霍乱，开胃消食，除烦止闷，口干渴疾，止怒，令人喜，破产后血闷，捣罯金疮并伤折，止暴痛。\n\n       疏：藕禀土气以生，其味甘，生寒熟温。入心、脾、胃三经。生者甘寒，能凉血止血，除热清胃，故主消散瘀血，吐血，口鼻出血，产后血闷，罯金疮伤折，及止热渴，霍乱烦闷，解酒等功。熟者甘温，能健脾开胃，益血补心，故主补五脏，实下焦，消食止泄，生肌，及久服令人心欢止怒也。本生于污泥之中，而体至洁白，味甚甘脆，孔窍玲珑，丝纶内隐，疗血止渴，补益心脾，真水果中之嘉品也。又能解蟹毒。\n\n       莲蕊须，一名佛座须，味甘涩，气温。本经不收，而古方固真补益方中，往往用之。详其主治，乃是足少阴经药，也能通手少阴经。能清心入肾，固精气，乌须发，止吐血，疗滑泄。同黄檗、砂仁、沙苑蒺藜、鱼胶、五味子、覆盆子、生甘草、牡蛎，作丸。治梦遗精滑，最良。\n","videoMemo":"","fangList":[],"bieMing":"藕"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2、藕', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6JxsmzJLChh', 4, '{"title":"第400107301条・卷之二十三_果部三品","description":"<p>1、莲子,藕实</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107301,"note":"    味甘，平、寒，无毒。主补中养神，益气力，除百疾。久服轻身耐老，不饥延年。\n\n     疏：藕实得天地清芳之气，禀土中冲和之味，故味甘气平。《别录》寒，无毒。入足太阴、阳明，兼入手少阴经。土为万物之母，后天之元气藉此以生化者也。母气既和则血气生，神得所养而疾病无由来矣。藕实正禀稼穑之化，乃脾家之果，故主补中养神，益气力，除百疾，及久服轻身耐老，不饥延年也。孟诜主五脏不足伤中，益十二经脉血气。大明主止渴去热，安心，止痢，治腰痛及泄精。多食令人喜，皆资其补益心脾之功也。\n\n【主治参与】\n得川黄连、白芍药、白扁豆、干葛、升麻、红曲、橘红、甘草、滑石、乌梅为丸，治滞下如神。\n\n下痢饮食不入，俗名噤口痢。此证大危，用鲜莲肉一两，黄连五钱，人参五钱，水煎浓。细细与呷，服完思食便瘥。同菟丝子、五味子、山茱萸、山药、车前子、肉豆蔻、砂仁、橘红、芡实、人参、补骨脂、巴戟天，治脾肾俱虚，五更溏泻。有肺热者去人参、肉豆蔻。\n\n孟诜《食疗》服食不饥：石莲肉蒸熟去心，为末，炼蜜丸梧子大。日服三十丸。此仙家方也。\n\n《普济方》白浊遗精：石莲肉、龙骨、益智仁等分，为末。每服二钱，空心米饮下。\n\n《直指方》心虚赤浊：莲子六一汤：用石莲肉六两，炙甘草一两，为末。每服一钱，灯心汤下。\n\n《丹溪心法》久痢噤口：石莲肉炒为末，每服二钱，陈仓米汤调下，便觉思食，甚妙。\n\n【简误】\n        藕实，脾家果也。甘平无毒，于诸疾并无相迕。第生者食之过多，微动冷气胀人。石莲子乃九月经霜后采，坚黑如石者，破房得之，堕水入泥者良。今肆中一种石莲子，状如榧子，其味大苦，产广中，出树上，木实也，不宜入药。","videoMemo":"","fangList":[],"bieMing":"莲子,藕实"}}', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '2024-12-30T04:02:11.000Z', '1、莲子,藕实', '2024-12-30T04:02:11.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'T2UcJ5VsJT7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CooZFDY3Gtb', 4, '{"title":"第400107404条・卷之二十四_米谷部上品","description":"<p>4、 饴糖</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107404,"note":"      味甘，微温。主补虚乏，止渴，去血。\n\n      疏：饴糖用麦蘖或谷蘖同诸米渍熬炼而成，故其味甘气温无毒。入足太阴，亦入手太阴经。甘入脾，而米麦皆养脾胃之物，故主补虚乏，仲景建中汤用之是也。肺胃有火，则发渴。火上炎迫血妄行，则吐血。甘能缓火之标，则火下降而渴自止，血自去也。思邈又谓其有消痰，润肺，止嗽，治咽痛、吐血等功。\n\n【主治参与】\n入建中汤，治脾虚腹痛。\n\n《简便方》误吞稻芒：白饧频食，效。\n\n《千金方》：服药过剂，闷乱者，饴糖食之。\n\n【简误】\n       饴糖成于湿热，少用虽能补脾润肺，然而过用之则动火生痰。凡中满吐逆，酒病牙疳，咸忌之。肾病尤不可服。","videoMemo":"","fangList":[],"bieMing":" 饴糖"}}', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '4、 饴糖', '2024-12-30T05:53:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ymKiky3s1Gf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aBWZhCxHme3', 4, '{"title":"第400107403条・卷之二十四_米谷部上品","description":"<p>3、胡麻油</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107403,"note":"     微寒。利大肠，胞衣不落。生者摩疮肿，生秃发。（此即乌脂麻油也。功用与白麻油相同，而力更胜。入药当以乌者为佳。）\n\n      疏：麻油，甘寒而滑利，故主胞衣不下，及利大肠。生者气更寒，能解毒凉血，故摩疮肿，生秃发也。藏器主天行热閟，肠内热结。服一合，取利为度。孟诜主瘖痖，杀五黄，下三焦热毒气，通大小肠，治蛔心痛，傅一切恶疮疥癣，杀一切虫。日华子：煎膏，生肌长肉止痛，消痈肿，补皮裂。皆取其甘寒滑利，除湿润燥，凉血解毒之功也。\n\n【主治参与】\n入血余一味熬膏，铅丹收好，能傅一切疮毒，排脓止痛。\n\n诸熬膏，必用真胡麻油，以其凉血解毒也。惟湿气膏不用。岭南解蛊法：以清油多饮，取吐效。\n\n《卫生易简方》：解河豚毒，一时仓卒无药，以清麻油多灌，取吐出毒物，即效。亦能解砒毒。\n\n《胎产须知》：妇人难产，因血枯涩者，用清油半两，好蜜一两，同煎数十沸，温服，胎滑即下。他药无益，以此助血为效。\n\n《直指方》：痈疽发背初起，即服此，使毒气不内攻。以麻油一斤，银石器内煎二十余沸，和醇醋二碗，分五次，一日服尽。\n\n《百一选方》肿毒初起：麻油煎葱黑色，趁热通手旋涂，自消。\n\n又方，丹石毒发，发热者不得食热物，不得用火，但着厚衣暖卧，取清油一匙含咽。\n\n刘禹锡《传信方》：蚰蜒入耳，用麻油煎作饼，枕卧，须臾自出。\n\n【简误】\n       麻油生者过寒，多食发冷疾，及脾胃虚寒作泻者，不宜食。熬熟治饮食甚美，但须逐日熬用，不可过宿，若经宿则火性反复，能助热动气也。","videoMemo":"","fangList":[],"bieMing":"胡麻油"}}', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '3、胡麻油', '2024-12-30T05:53:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ymKiky3s1Gf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zrudiJG6SgG', 4, '{"title":"第400107402条・卷之二十四_米谷部上品","description":"<p>2、麻子仁,麻子,大麻仁</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107402,"note":"        味甘，平，无毒。主补中益气，中风汗出，逐水，利小便，破积血，复血脉，乳妇产后余疾，长发，可为沐药。久服肥健，不老神仙。\n\n         疏：麻子，即大麻仁，禀土气以生。《本经》味甘平无毒。然其性最滑利，甘能补中，中得补则气自益。甘能益血，血脉复则积血破，乳妇产后余疾皆除矣。风并于卫，则卫实而荣虚。荣者，血也，阴也。《经》曰：阴弱者，汗自出。麻仁益血补阴，使荣卫调和，风邪去而汗自止也。逐水利小便者，滑利下行，引水气从小便而出也。好古云：入手、足阳明，足太阴经。阳明病汗多，及胃热便难，三者皆燥也，用之以通润。《经》曰：脾欲缓，急食甘以缓之。麻仁之甘以缓脾润燥，故仲景脾约丸用之。\n\n【主治参与】\n《食医心镜》麻子仁粥：治风水腹大，腰脐重痛，不可转动，用冬麻子半升，研碎，水滤取汁，入粳米二合，煮稀粥，下葱、椒、盐豉，空心食。\n\n仲景方：麻子仁丸：治脾约，大便秘而小便数。麻子仁二升，芍药半斤，厚朴一尺，大黄、枳实各一斤，杏仁一升，熬研，炼蜜丸梧子大。每以浆水下十丸，日三服。不知再加。\n\n《本事方》产后秘塞，许学士云：产后汗多则大便必秘，难于用药，惟麻子粥最稳。不惟产后可服，凡老人诸虚风秘，皆妙。用大麻子仁、紫苏子各二合，洗净研细，再以水研，滤取汁一盏，分二次煮粥啜之。\n\n夏子益《奇疾方》：截肠怪病，大肠头出寸余，痛苦，干则自落，又出，名为截肠病，若肠尽则不治。但初觉截时，用器盛脂麻油坐浸之，饮大麻子汁数升，即愈也。\n\n【简误】\n陈士良云：多食损血脉，滑精气，痿阳事。妇人多食即发带疾，以其滑利下行，走而不守也。","videoMemo":"","fangList":[],"bieMing":"麻子仁,麻子,大麻仁"}}', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '2、麻子仁,麻子,大麻仁', '2024-12-30T05:53:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ymKiky3s1Gf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FNWjO1hwdPi', 4, '{"title":"第400107401条・卷之二十四_米谷部上品","description":"<p>1、胡麻</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107401,"note":"     味甘，平，无毒。主伤中虚羸，补五内，益气力，长肌肉，填髓脑，坚筋骨。疗金疮止痛，及伤寒、温疟大吐后，虚热羸困。久服轻身不老，明耳目，耐饥渴，延年。一名巨胜。\n\n      疏：胡麻禀天地之冲气，得稼穑之甘味，故味甘气平无毒。入足太阴，兼入足厥阴、少阴。气味和平，不寒不热，益脾胃，补肝肾之佳谷也。弘景云：八谷之中，惟此为良。仙家作饭饵之，断谷长生。故主伤中虚羸，补五内，益气力，长肌肉，坚筋骨，填髓脑，及伤寒、温疟大吐后，虚热羸困。久服明耳目，耐饥渴，轻身不老延年也。金刃伤血则瘀而作痛，甘平益血润燥，故疗金疮止痛也。日华子：主补中益气，润养五脏，补肺气，止心惊，利大小肠，逐风湿气，游风，头风，劳气，产后羸困。李廷飞云：风病人久服，则步履端正，语言不蹇。陈士良：生嚼涂小儿头疮，煎汤浴恶疮，及妇人阴疮。皆取其甘平益血脉，补虚羸，入肝脾肾之功耳。刘河间曰：麻，木谷而治风。又云：治风先治血，血活则风去。胡麻入肝益血，故风药中不可阙也。\n\n【主治参与】\n得何首乌、茅山苍术、白茯苓、菖蒲、桑叶、牛膝、当归、续断、地黄、桑上寄生，治风湿痹。\n\n同甘菊花、天门冬、黄檗、生地黄、何首乌、柏子仁、桑叶、牛膝、枸杞子、麦门冬作丸，治似中风口眼㖞斜，半身不遂。久服不辍，有神验。\n\n一味九蒸九曝，加茅山苍术，乳蒸晒三次，作丸。能健脾燥湿，益气延年。\n\n抱朴子服食胡麻法：用上党胡麻三斗，淘净蒸令气透，日干，以水淘去沫再蒸，如此九度。去壳，炒香为末，白蜜或枣膏丸弹子大。每温酒化下一丸，日三服。忌毒鱼、狗肉、生莱菔至百日。能除一切痼疾，一年病色光泽不饥，二年白发还黑，三年齿落更生，久服常生不老矣。\n\n《外台秘要》解下胎毒：小儿初生，嚼生脂麻，绵包，与儿咂之，其毒自下。\n\n《简便方》小儿瘰疬：脂麻、连翘等分，为末。频频食之。\n\n《经验方》蜘蛛及一切虫咬伤，油麻研烂傅之。\n\n《三因方》：谷贼尸咽，喉中痛痒，此因误吞谷芒，戟刺痒痛也。用脂麻炒研，白汤调下。\n\n甘平无毒，补益为用，仙家服食所须。故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"胡麻"}}', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '2024-12-30T05:53:57.000Z', '1、胡麻', '2024-12-30T05:53:57.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'ymKiky3s1Gf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6UHC8GZKpEi', 4, '{"title":"第400107511条・卷之二十五_米谷部中品","description":"<p>11、绿豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107511,"note":"   味甘，寒，无毒。主丹毒，烦热，风疹，药石发动。热气奔豚，生研绞汁服。亦煮食，消肿下气，压热解石。用之勿去皮，令人小壅。\n\n    疏：绿豆禀土中之阴气，故其味甘气寒无毒。入足阳明经。夫丹石之药，气悍而性热，多服则火动，上升为烦热，甚则口鼻出血，狂闷躁扰。甘寒能除热下气解毒，故主服丹石药人毒发烦热也。阳明客热，则发出风疹，以胃主肌肉，热极生风故也。解阳明之热，则风疹自除。胀满者，湿热侵于脾胃也。热气奔豚者，湿热客于肾经也。除湿则肿消，压热则气下，益脾胃而肾邪亦自平也。孙思邈：主寒热热中，止泄痢，卒澼，利小便胀满。日华子：主厚肠胃。作枕，明目，治头风头痛，益气，除热毒风。孟诜：主去浮风，益气力，治消渴，和五脏，安精神。可常食之，功效不可备述。\n\n【主治参与】\n扁鹊三豆饮：治天行痘疮，预服此饮，疏解热毒，纵出亦少。用绿豆、赤小豆、黑豆各一升，甘草节二两，以水八升，煮极熟。任意吞豆饮汁，七日乃止。\n\n《医学正传》：痘后痈毒初起，以三豆膏治之，神效。绿豆、赤小豆、黑大豆等分，为末。醋调时时扫涂，即消。\n\n《全幼心鉴》小儿丹肿：绿豆五钱，大黄二钱，为末，用生薄荷汁入蜜调涂。中砒毒者，研汁饮之。\n\n【简误】\n     脾胃虚寒滑泄者，忌之。","videoMemo":"","fangList":[],"bieMing":"绿豆"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '11、绿豆', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XkaSxrhrp51', 4, '{"title":"第400107510条・卷之二十五_米谷部中品","description":"<p>10、豉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107510,"note":"   味苦，寒，无毒。主伤寒头痛寒热，瘴气恶毒，烦躁满闷，虚劳喘吸，两脚疼冷。\n\n     疏：豉，诸豆皆可为之，惟黑豆者入药。有盐、淡二种，惟江右淡者治病。经云：味苦，寒，无毒。然详其用，气应微温。盖黑豆性本寒，得蒸晒之，气必温。非苦温则不能发汗开腠理，治伤寒头痛寒热，及瘴气恶毒也。苦以涌吐，故能治烦躁满闷。以热郁胸中，非宣剂无以除之。如伤寒短气烦躁，胸中懊憹，饥不欲食，虚烦不得眠者，用栀子豉汤吐之是也。又能下气调中，辟寒，故主虚劳喘吸，及两脚冷疼。\n\n【主治参与】\n《肘后方》云：伤寒有数种，庸人卒不能分别者，今取一药兼疗之。凡初觉头痛身热，脉洪，一二日，以葱豉汤治之。用葱白一虎口，豉一升，绵裹，水三升，煮一升。顿服取汗。\n\n仲景栀子豉汤：治伤寒汗下后虚烦，用栀子十四枚，香豉四合绵裹，以水四升，先煮栀子得二升半，内豉，煮取一升半，去滓。分二服，温进一服，得吐，止后服。\n\n又枳实栀子豉汤：治大病瘥后劳复，用枳实三枚，栀子十四枚，豉一升，以清浆水七升，空煮取四升，纳枳实、栀子，取二升，下豉更煮五六沸，去滓。分温再服，令微似汗。伤寒之邪自外入，劳复之邪自内发，发汗、吐下，当随宜施治也。治伤寒食早成食复，前汤中加大黄如博棋子大五枚。\n\n《梅师方》辟除温疫：豉和白术，浸酒，常服之。\n\n甄权方：伤寒暴痢腹痛者，豉一升，薤白一握切，以水三升，先煮薤，内豉更煮。汤色黑，去豉，分二服，不瘥更服。亦治血痢。\n\n孟诜：治久患盗汗，以豉一升，熬令香，清酒三升渍，满三日取汁，冷暖任服，不瘥更作，二剂即止。\n\n《简要济众方》：伤寒后余毒攻手足，及身体虚肿，用豉五合微炒，以酒一升半，同煎五七沸，任性饮之。\n\n《千金方》：蠼螋尿疮，杵豉傅之良。\n\n《卫生易简方》中牛马毒：豉汁和人乳，频服之，效。\n\n《千金方》中酒成病：豉、葱白各半升，水二升，煮一升，顿服。\n\n又方：服药过剂闷乱者，豉汁饮之。\n\n《肘后方》肿从脚起：豉汁饮之，以滓傅之。\n\n弘景云：春夏之气不和，以豉蒸炒，酒渍，服之至佳。\n\n【简误】\n       凡伤寒传入阴经，与夫直中三阴者，皆不宜用。热结胸中烦闷不安者，此欲成结胸，法当下，不宜复用汗吐之药，并宜忌之。","videoMemo":"","fangList":[],"bieMing":"豉"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '10、豉', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g0oGO7RCa0i', 4, '{"title":"第400107509条・卷之二十五_米谷部中品","description":"<p>9、扁豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107509,"note":"    味甘，微温。主和中下气。\n\n     叶：主霍乱吐下不止。\n\n     疏：扁豆禀土中冲和之气，其味甘，气香，性温、平，无毒。入足太阴、阳明经气分，通利三焦，升清降浊，故专治中宫之病，和中下气，消暑除湿而解毒也。孟诜：主霍乱吐利不止，及呕逆，久食头不白。日华子云：补五脏。苏颂：主女子带下，解酒毒、河豚鱼毒。寇宗奭：主霍乱转筋。皆取其益脾开胃，和中气，除湿热之功耳。\n\n叶：气味相同，故主霍乱。\n\n花有紫、白二色，豆有黑、白二种。入药惟紫花、豆白者良。豆黑色及紫色者，名鹊豆，不入药，亦不益人。\n\n【主治参与】\n白扁豆，同山药、白茯苓、人参、莲肉、薏苡仁、芡实，为补脾胃之上药。中焦有湿者加白术。\n\n同黄连、干葛、白芍药、升麻、红曲、滑石、乌梅、橘红、甘草、莲肉，治滞下如神。\n\n同麦门冬、五味子、黄连、干葛，能解酒毒。\n\n同木瓜、石斛、橘皮、藿香、茯苓、缩砂、香薷，治霍乱吐泻转筋。\n\n入十味香需饮，能消暑气，健脾。\n\n《奇效良方》血崩不止：白扁豆花，焙干为末。每服二钱，空心炒米煮饮，入盐少许，调下，即效。\n\n治霍乱秘法：用白扁豆叶一叶，同白梅一枚，并仁研烂。新汲水调服，神效。\n\n苏恭：治吐利后转筋。用白扁豆叶一把，捣，入醋少许，绞汁服，立瘥。\n\n【简误】\n       弘景云：患寒热者不可食。盖指伤寒寒热，外邪方炽，不可用此补益之物耳。如脾胃虚，及伤食劳倦发寒热者，不忌。","videoMemo":"","fangList":[],"bieMing":"扁豆"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '9、扁豆', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2zYfXlaOrr8', 4, '{"title":"第400107508条・卷之二十五_米谷部中品","description":"<p>8、曲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107508,"note":"     味甘，大暖。疗藏腑中风气，调中下气，开胃，消宿食，主霍乱，心膈气，痰逆，除烦，破癥结，补虚，去冷气，除肠胃中塞，不下食，令人有颜色。六月作者良。\n\n      神曲：使，无毒。能化水谷宿食，癥气。健脾暖胃。\n\n      疏：古人用曲，即造酒之曲。其气味甘温，性专消导，行脾胃滞气，散脏腑风冷，故主疗如诸家所言也。\n\n     神曲，乃后人专造以供药用，力倍于酒曲。盖取诸神聚会之日造之，又取各药物以象六神之用，故得神名。陈久者良。入药炒令香用。六畜食米多。胀欲死者，煮曲汁灌之立消。\n\n    造神曲法：用五月五日，或六月六日，以白面百斤，青蒿自然汁三升，赤小豆末、杏仁泥各三升，苍耳自然汁、野蓼自然汁各三升，以配白虎、青龙、朱雀、玄武、勾陈、腾蛇六神，用汁和面、豆、杏仁作饼，麻叶或楮叶包罯，如造酱黄法，待生黄衣，晒干收之。\n\n【主治参与】\n神曲，开胃健脾，消食止泄，同山查、麦蘖、谷蘖、缩砂、陈皮、草果、藿香、白术、干葛、莲肉等用，效。\n\n《百一选方》疗痞满暑泄，曲术丸：用神曲炒，苍术泔制炒，等分为末，糊丸梧子大。每米饮下五十丸。\n\n《和剂局方》：健胃思食，治脾胃俱虚，不能消化水谷，胸膈痞闷，腹胁膨胀，连年累月，食减嗜卧，口无味。神曲六两，麦蘖炒三两，干姜炮四两，乌梅肉焙四两，为末，蜜丸梧子大。每米饮下五十丸，日三服。\n\n《摘玄方》食积心痛：陈神曲一块烧红，淬酒二大碗，服之。\n\n【简误】\n      脾阴虚，胃火盛者，不宜用。能落胎，孕妇宜少食。","videoMemo":"","fangList":[],"bieMing":"神曲,曲"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '8、曲', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1MOn3m4SEaX', 4, '{"title":"第400107507条・卷之二十五_米谷部中品","description":"<p>7、大麦</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107507,"note":"      味咸，温、微寒，无毒。主消渴，除热，益气，调中。又云：令人多热，为五谷长。（蜜为之使。）\n\n       疏：大麦功用与小麦相似，而其性更平凉滑腻，故人以之佐粳米同食，或歉岁全食之，而益气补中，实五脏，厚肠胃之功，不亚于粳米矣。陈士良云：补虚劣，壮血脉，化谷食，止泄泻，不动风气，久食令人肥白，滑肌肤。为面无燥热，胜于小麦。苏恭云：平胃止渴，消食疗胀满。其为效可知。本经末云：令人多热。与上文及诸说相背，必是误入也。\n\n麦蘖\n苏颂云：化宿食，破冷气，止心腹胀满。日华子：温中，下气，开胃，止霍乱，除烦，消痰，破癥结。\n\n      疏：麦蘖，以水渍大麦而成。其味咸，气温，无毒。功用与米蘖相同，而此消化之力更紧。咸能软坚，温主通行。其发生之气，又能助胃气上升，行阳道而主健运。故主开胃补脾，消化水谷，及一切结积，冷气，胀满，如上所言等证也。好古曰：麦芽、神曲二药，胃气虚人宜服之，以代戊己腐熟水谷。豆蔻、缩砂、乌梅、木瓜、芍药、五味子为之使。\n\n【主治参与】\n麦蘖同山查、红曲、橘皮、草果、砂仁、厚朴、苍术，消食积。\n\n快膈进食：麦芽四两，神曲二两，白术、橘皮各一两，为末，蒸饼丸梧子大。每人参汤下三五十丸。\n\n李绛《兵部手集》：产后腹胀不通转，气急，坐卧不安，以麦蘖一合，为末。和酒服，良久通转，神验。\n\n《妇人经验方》：产后青肿，乃血水渍也。干漆、大麦蘖等分，为末。新瓦中铺漆一层，孽一层，重重令满，盐泥固济，煅赤，研末。热酒调服二钱，产后诸疾并宜。\n\n丹溪方：产后回乳：产妇无子食乳，乳不消，令人发热恶寒，用大麦蘖二两炒，为末。每服五钱，白汤下，甚良。\n\n【简误】\n     麦蘖能消导米面、诸果食积。无积滞，脾胃虚者，不宜用。久服消肾气，堕胎。","videoMemo":"","fangList":[],"bieMing":"大麦"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '7、大麦', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MytLlaahCcx', 4, '{"title":"第400107506条・卷之二十五_米谷部中品","description":"<p>6、小麦</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107506,"note":"       味甘，微寒，无毒。主除热，止燥渴咽干，利小便，养肝气，止漏血、唾血。以作曲，温。消谷，止痢。以作面，温。不能消热止烦。\n\n       疏：小麦禀四时中和之气，故其味甘，气微寒，无毒。入手少阴经。少阴有热，则燥渴咽干，解少阴之热，则燥渴咽干自止。心与小肠为表里，脏气清，腑病亦自除，故利小便。肝、心为子母之脏，子能令母实，故主养肝气。甘寒走二经而能益血凉血，故止漏血、唾血也。\n\n曲：性温，所以能消谷，止痢。\n\n面：性热，故不能消热止烦。北方霜雪多，地气厚，热性减，凡入药以北来者为胜。\n\n浮麦：即水淘浮起者，能止自汗、盗汗，亦以北方者良。古方有用寒食面者，寒食日，以纸袋盛面，悬风处，数十年亦不坏。取其热性去而无毒也。\n\n【主治参与】\n《奉亲书》老人五淋，身热腹满：小麦一升，通草二两，水三升，煮一升。饮之，良。\n\n《生生编》走气作痛：用小麦麸拌，酽醋炒热，袋盛熨之。\n\n面作蒸饼和药，取其易消也。\n\n【简误】\n      小麦寒气全在皮，故面去皮则热，热则壅滞动气，发渴助湿，令人体浮，皆其害也。凡大人脾胃有湿热，及小儿食积疳胀，皆不宜服。然北人以之代饭，常御而不为患者，此其地势高燥，无湿热熏蒸之毒，故面性亦温平，能厚肠胃，强气力，补虚助五脏，其功不减于稻粟耳。东南卑湿，春多雨水，其湿热之气郁于内，故食之过多，每能发病也。夏月疟、痢人，尤不宜食。","videoMemo":"","fangList":[],"bieMing":"小麦"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '6、小麦', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0DrZdTndvZF', 4, '{"title":"第400107505条・卷之二十五_米谷部中品","description":"<p>5、蘖米,稻蘖</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107505,"note":"     味苦，无毒。主寒中，下气，除热。\n\n    疏：蘖米，即稻蘖也。味甘，气温，无毒。具生化之性，故为消食健脾，开胃和中之要药。脾胃和则中自温，气自下，热自除也。\n【主治参与】\n《澹寮方》启脾进食，谷神丸：用谷蘖四两，为末，入姜汁、盐少许，和作饼，焙干，入炙甘草、砂仁、白术麸炒各一两，为末。白汤点服，或丸服。","videoMemo":"","fangList":[],"bieMing":"蘖米,稻蘖"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '5、蘖米,稻蘖', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bJkkN2FK5Kw', 4, '{"title":"第400107504条・卷之二十五_米谷部中品","description":"<p>4、粳米</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107504,"note":"     味甘、苦，平，无毒。主益气，止烦，止泄。\n\n      疏：粳米，即人所常食米，感天地冲和之气，同造化生育之功，为五谷之长，人相赖以为命者也。《经》曰：安谷则昌，绝谷则亡。仲景曰：人受气于水谷以养神，水谷尽而神去。自上古圣人树艺，至今不可一日无此也。禀土德之正，其味甘而淡，其性平而无毒。虽专主脾胃，而五脏生气，血脉、精髓，因之以充溢周身；筋骨、肌肉、皮肤，因之而强健。本经益气，止烦、止泄，特其余事耳。\n\n【主治参与】\n入白虎汤，治作劳人伤寒发热，虚羸少气，气逆上冲欲吐。少阴病下痢脓血，或腹满下如鱼脑者，桃花汤主之。粳米一升，赤石脂一斤，一半全，一半末，干姜一两，以水七升，煮米令熟，去滓。温服七合，内赤石脂末方寸匕，日三服。若一服愈，余勿服。以上仲景法。\n\n《普济方》：小儿初生无皮，色赤，但有红筋，乃受胎未足也。用早白米粉扑之，肌肤自生。\n\n《千金方》：嗜食生米成瘕，用白米五合，鸡屎一升，同炒焦，为末，水一升，顿服。少时吐出瘕，如研米汁，或白沫淡水，乃愈也。","videoMemo":"","fangList":[],"bieMing":"粳米"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '4、粳米', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QC570WoJRI3', 4, '{"title":"第400107503条・卷之二十五_米谷部中品","description":"<p>3、酒</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107503,"note":"      味苦、甘、辛，大热，有毒。主行药势，杀百邪恶毒气。\n\n      疏：酒，品类极多，醇醨不一，惟米造者入药用。经云：酒者，热谷之液，其气悍。弘景云：大寒凝海，惟酒不冰。明其性热，独冠群物。制药多用之，以藉其势。人饮多则体弊神昏，是其有毒故也。《博物志》云：昔三人冒雾晨行，一人饮酒，一人饱食，一人空服。空腹者死，饱食者病，饮酒者健。此酒势辟邪恶毒气之效，胜于他物也。藏器主通血脉，厚肠胃，润皮肤，消忧发怒，宣言畅意。无非取其横行经络，走散皮肤，开发宣通之功耳。\n\n【主治参与】\n诸药可造酒者：五加皮、女贞实、仙灵脾、薏苡仁、天门冬、麦门冬、地黄、菖蒲、枸杞子、人参、何首乌、甘菊花、黄精、桑椹、术、蜜、仙茅、松节、柏叶、竹叶、胡麻、磁石、蚕沙、乌白蛇、鹿茸、羊羔、腽肭脐、黑豆之类。各视其所生之病，择其所主之药，入曲、米，如常酿酒法，酿成饮。或袋盛入酒内，浸数日，饮之。\n\n《肘后方》：鬼击诸病，卒然着人，如刀刺状，胸胁腹内切痛，不可抑按，或吐血、鼻血、下血。以醇酒吹两鼻内，良。\n\n又方，马气入疮，或马汗、马毛入疮，皆致肿痛烦热，入腹则杀人。多饮醇酒，至醉即愈。\n\n《千金方》三十年耳聋：酒三升，渍牡荆子一升，七日去滓，任性饮之。\n\n《梅师方》产后血闷。清酒一升，和生地黄汁煎服。\n\n【简误】\n       王好古曰：酒能引诸经不止，与附子相同。味之辛者能散，苦者能下，甘者能居中而缓，用为导引，可以通行一身之表，至极高之分。古人惟以麦造曲酿黍，已为辛热有毒。今之醖者，加以乌头、巴豆、桂、姜之类大毒大热之药，以增其气味。岂不伤冲和，损精神，涸荣卫，竭天癸，而夭夫人寿耶？朱震亨云：《本草》止言酒热而有毒，不言湿中发热，近于相火。醉后振寒战慓可见矣。又性喜升，气必随之。痰郁于上，溺涩于下，恣饮寒凉，其热内郁于肺与大肠。其始也病浅，或呕吐，或疮疥，或鼻皶，或泄利，或心脾痛，尚可散而去之。其久也病深，或消渴，或内疽，或肺痈，或鼓胀，或喉哑，或哮喘，或劳瘵，或痔漏，为状不一，非具眼未易处也。扁鹊云：过饮腐肠烂胃，溃髓蒸筋，生痰动火，亡精耗血，伤神损寿。孟诜云：软筋骨，动气痢，醉卧当风则成癜风，醉浴冷水成痈痹。陈士良云：凡服丹砂、钟乳诸石药，并不可长用酒下，能引石药气入四肢，滞血化为痈疽。藏器云：凡饮酒，忌甜物。同牛肉食，令人生虫。合乳饮，令人气结。诸如此类，不可胜载。今人有喜以火逼极热，恣饮为快。不知酒性既热，又以火济火，鲜有不为害者。曾见一人好饮火酒，不几年患一恶证，吐脓血瘀肉而毙。盖肺为火热腐烂也。酒能合欢解忧，御寒祛疾，自上古至今，循习为常用之物。然而如上等害，不可不晓。惟在樽节度量，寒温适宜，不至沉湎荒乱，斯得酒中之趣者。古人终日饮，不及乱，用此道耳。震亨又云：醇酒冷饮有三益，予谓三益未必。然而伤肺生痰，动火损胃之害，可差免矣。","videoMemo":"","fangList":[],"bieMing":"酒"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '3、酒', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4FH8FBxKQas', 4, '{"title":"第400107502条・卷之二十五_米谷部中品","description":"<p>2、赤小豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107502,"note":"       味甘、酸，平，无毒。主下水，排痈肿脓血，寒热，热中，消渴，止泄，利小便，吐逆，卒澼，下胀满。\n\n        疏：赤小豆，禀秋燥之气以生。本经味甘酸，气平，无毒。然详其用，味应有辛，非辛平则不能排痈肿脓血，及疗寒热，热中，消渴也。凡水肿胀满，泄泻，皆湿气伤脾所致，小豆健脾燥湿，故主下水肿胀满，止泄，利小便也。十剂云：燥可去湿。赤小豆之属是矣。吐逆者，气逆上升也。卒澼者，大肠湿热也。甘酸敛逆气，辛平散湿热，故亦主之。\n\n【主治参与】\n陈藏器《本草》：赤小豆和桑根白皮煮食，去湿气痹肿。\n\n孟诜《食疗》：和鲤鱼煮食，甚治脚气。\n\n《金匮要略》：伤寒狐惑病，脉数，无热微烦，默默但欲卧，汗出。初得之三四日，目赤如鸠眼；七八日，目四眦黄黑。若能食者，脓已成也。赤豆当归散主之：赤小豆三升，浸令芽出，当归三两，为末。浆水服方寸匕，日三服。\n\n甄权《药性》热毒痈肿：赤小豆为末，鸡子白调涂。\n\n苏颂《图经》治脚气：以袋盛此豆，置足下，朝夕辗转践踏之，遂愈。\n\n【简误】\n陶弘景云：小豆逐津液，利小便，久服令人枯燥。凡水肿胀满，总属脾虚，当杂补脾胃药中用之。病已即去，勿过剂也。其治消渴，亦借其能逐胃中热，从小便利去。若用之过多，则津液竭而渴愈甚，不可不戒也。","videoMemo":"","fangList":[],"bieMing":"赤小豆"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2、赤小豆', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aKcrtWvjNLE', 4, '{"title":"第400107501条・卷之二十五_米谷部中品","description":"<p>1、生大豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107501,"note":"       味甘，平，涂痈肿。煮汁饮，杀鬼毒，止痛。逐水胀，除胃中热痹，伤中淋露，下瘀血，散五藏结积内寒。杀乌头毒。久服令人身重。炒为屑，味甘，主胃中热，去肿除痹，消谷，止腹胀。（恶五参、龙胆。得前胡、杏仁、牡蛎良。）\n\n       疏：生大豆，苏颂云：有黑白二种，黑者入药，白者不用。其紧小者为雄，入药尤佳。禀土气以生，而色黑则象水，故味甘气平无毒。平即兼凉，为肾家之谷也。甘平能活血解毒，祛风散热，故主涂痈肿，止痛，杀鬼毒，乌头毒，除胃中热痹，伤中淋露，下瘀血，散五脏结积内寒，消谷也。色黑属水，同气相求，故能逐水肿腹胀。仙方修治末服之，可以辟谷度饥。然初服时似乎身重，一年以后便觉轻健也。陈藏器：炒令黑，烟未断，及热投酒中饮之，治风痹瘫缓，口噤，产后诸风，及风痉，阴毒腹痛。食罢生吞半两，去心胸烦热，热风。孟诜主中风脚弱，产后诸疾。同甘草煮汤饮，去一切热毒气，及风毒脚气。同桑柴灰煮食，下水鼓腹胀。捣涂一切肿毒。日华子：主调中气，通关脉，制金石药毒，解牛马瘟病。皆取其活血散风，除热解毒，下气利水之功耳。\n\n【主治参与】\n同泽兰、益母草、苏木、人参、牛膝、荆芥、生地黄、童便、蒲黄，治产后血晕闷绝。\n\n同蔓荆子、土茯苓、金银花、甘菊花、玄参、川芎、天麻、芽茶、荆芥、乌梅，治偏头风痛，有神。\n\n古方紫汤：破血去风，除气散热，产后两日，尤宜服之。用黑豆五升，清酒一斗，将豆炒令烟绝，投酒中，待酒紫赤色，去豆。量性饮之，神验。中风口噤，加鸡屎白二升和炒，投之。\n\n《广利方》脚气冲心，烦闷不识人：以大豆一升，水三升，浓煮汁服。未定，再服。\n\n扁鹊方：三豆饮子：能稀痘，见绿豆条内。\n\n大豆壳同蜜蒙花、谷精草、黄连、木贼草、决明子、甘菊花、金银花、生地黄、羚羊角、羊肝，治小儿痘后目翳。\n\n【简误】\n        生大豆，歧伯云：生温，熟寒。藏器云：生平，炒食极热，煮食极寒。观《本经》及孟诜云：生捣涂肿毒，则生者非温矣。经又云：炒为屑，主胃中热，则炒者又非极热矣。应是生平、炒温、煮寒无疑。忌猪肉，小儿以炒豆、猪肉同食，必壅气致死，十有八九。十岁以上，则无害也。服萆麻子者，忌炒豆，犯之胀满致死。服厚朴者亦忌之，最能动气故也。","videoMemo":"","fangList":[],"bieMing":"生大豆"}}', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '2024-12-30T06:17:29.000Z', '1、生大豆', '2024-12-30T06:17:29.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '9C1BHOm6jgC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lwgqHGLWErw', 4, '{"title":"第400107603条・卷之二十六_米谷部下品","description":"<p>3、酱</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107603,"note":"    味咸、酸，冷利。主除热，止烦满，杀百药、热汤及火毒。\n\n     疏：按酱之品不一，惟豆酱陈久者入药。其味咸酸冷利，故主除热，止烦满，及汤火伤毒也。能杀一切鱼肉菜蔬蕈毒。本经云：杀百药毒者，误也。圣人不得其酱不食。朱子云：食肉用酱，各有所宜。玩一宜字，则不宜者必有伤害于人，非特悦口而已。如食蟹用橙酱，或姜酱，煮鱼用茱萸酱，取其能杀毒之义耳。又有榆仁酱，味辛美，杀诸虫，利大小便，心腹恶气。芜荑酱主疗相同。茱萸酱作法不用面、豆、盐，只以河水，量茱萸多少，稍稍加石灰掺入拌匀，瓮藏。杀一切鱼腥毒。用时洗去石灰，擂烂，烹水入之良。\n","videoMemo":"","fangList":[],"bieMing":"酱"}}', '2024-12-30T08:46:02.000Z', '2024-12-30T08:46:02.000Z', '2024-12-30T08:46:02.000Z', '3、酱', '2024-12-30T08:46:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'VVwj3fEuItw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FgWonyMnJR9', 4, '{"title":"第400107602条・卷之二十六_米谷部下品","description":"<p>2、稻米</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107602,"note":"   味苦。主温中，令人多热，大便坚。\n\n    疏：稻米，即今之糯米也。禀土中之阳气，其味应甘，气应温无毒。造酒必用之者，以其性近于热也。为补脾胃，益肺气之谷。脾胃得补，则中自温，大便亦坚实。温能养气，气充则身自多热。大抵脾肺虚寒者宜之，为其能益气温中也。故又有止泄利，缩小便，收自汗，发痘疮等用。\n\n【主治参与】\n《松篁经验方》久泄食减：以糯米一升，水浸一宿，沥干，炒熟磨筛，入怀山药一两，每日清晨用半盏，入白砂糖二匙，胡椒末少许，以滚汤调食。大有滋补。久服更能令人精暖有子。\n\n《医方大成》癫犬咬伤：糯米一合，斑猫七枚，同炒熬黄去之；再入七枚，再炒黄去之；又入七枚，待米出烟，去猫，为末。水调服之，小便利下，佳。亦可油调外傅。\n\n又方，虚劳不足：糯米入猪肚内，蒸熟，日食。\n\n【简误】\n糯米，孟诜云：发风动气，久食令人多睡。藏器云：久食令人身软；妊娠杂肉食之，令子不利。萧炳云：拥诸经络气，使四肢不收，发风昏昏。陈士良云：久食发心悸，及痈疽疮疖中痛，合酒食之醉难醒。然愚意观之，其为害未必如此之甚。盖天生五谷以食人，皆禀土中冲和之气，可常御而无害者。第糯米气温，性粘滞，惟不利于上焦有痰热，及脾病不能转运，小儿难于克化者，余皆无害。诸家之言，不可尽信也。","videoMemo":"","fangList":[],"bieMing":"稻米"}}', '2024-12-30T08:46:02.000Z', '2024-12-30T08:46:02.000Z', '2024-12-30T08:46:02.000Z', '2、稻米', '2024-12-30T08:46:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'VVwj3fEuItw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NLCE3Pr2JLf', 4, '{"title":"第400107601条・卷之二十六_米谷部下品","description":"<p>1、苦酒,醋</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107601,"note":"    味酸，温，无毒。主消痈肿，散水气，杀邪毒。（一名苦酒。）\n\n     疏：醋惟米造者入药，得温热之气，故从木化，其味酸，气温，无毒。酸入肝，肝主血，血逆热壅则生痈肿。酸能敛壅热，温能行逆血，故主消痈肿。其治产后血晕，癥块血积，亦此意耳。散水气者，水性泛滥，得收敛而宁谧也。杀邪毒者，酸苦涌泻，能吐出一切邪气毒物也。日华子主下气除烦，妇人心痛血气，并产后，及伤损金疮出血迷闷，杀一切鱼肉菜毒。取其酸收，而又有散瘀解毒之功也。故外科傅药中多资用。\n\n【主治参与】\n仲景方：少阴病，脉微细，但欲寐，咽中伤，生疮，不能言语，声不出者，苦酒汤主之。用半夏十四枚，鸡子一枚去黄，以苦酒、半夏着鸡子壳中，置刀环中，安火上，令三沸，去滓，少少含咽之。不瘥，更用三剂。\n\n仲景《金匮》方：黄耆芍药苦酒汤，治黄汗，汗出沾衣，正黄如药汁。因汗出时入水中浴，水从汗孔入得之。用黄耆五两，芍药三两，桂枝三两，以苦酒一斗，水七升，相和，煮取三升，温服一升。当心烦，服至六七日乃解。\n\n《衍义》云：产妇房中，常以火炭沃醋气为佳，酸气能敛血，使下也。\n\n孟诜《食疗》：青木香，以醋磨汁服，止卒心痛。\n\n浸黄檗，含之，治口疮。\n\n《千金方》身体卒肿：醋和蚯蚓屎傅之。\n\n又方，舌肿不消：以酢和釜底墨，厚傅舌之上下，脱则更傅，须臾即消。\n\n又方汤火伤灼，即以酸酢淋洗，并以酢泥涂之良，亦无瘢痕。喉痹咽痛，以酽醋探吐之。\n\n【简误】\n《经》曰：酸走筋，筋病毋多食酸。凡筋挛、偏痹、手足屈伸不便，皆忌之。又曰：味过于酸，肝气以津，脾气乃绝。多食酸则肉皱而唇揭，言能助肝贼脾。凡脾病者，亦不宜过食。","videoMemo":"","fangList":[],"bieMing":"苦酒,醋"}}', '2024-12-30T08:46:02.000Z', '2024-12-30T08:46:02.000Z', '2024-12-30T08:46:02.000Z', '1、苦酒,醋', '2024-12-30T08:46:02.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'VVwj3fEuItw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J8Jyse7m0aE', 4, '{"title":"第400107708条・卷之二十七_菜部上品","description":"<p>8、苜蓿</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107708,"note":"     味苦，平，无毒。主安中利人，可久食。\n\n     疏：苜蓿，草也，嫩时可食，处处田野中有之，陕陇人亦有种者。本经云苦平无毒。主安中利人。可久食。然性颇凉，多食动冷气，不益人。根苦寒，主热病烦满，目黄赤，小便黄，酒疸。捣汁一升服，令人吐利，即愈。其性苦寒，大能泄湿热故耳。以其叶煎汁多服，专治酒疸大效。\n","videoMemo":"","fangList":[],"bieMing":"苜蓿"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '8、苜蓿', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PfcWu7Xxy2S', 4, '{"title":"第400107707条・卷之二十七_菜部上品","description":"<p>7、苦菜,苦苣,苦荬</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107707,"note":"     味苦，寒，无毒。主五藏邪气，厌（伏也）谷胃痹，肠澼，渴热中疾，恶疮。久服安心益气，聪察少卧，轻身耐老，耐饥寒，高气不老。\n\n     疏：苦菜与苦苣、苦荬一物，而形稍异，功用则相同也。禀天地之阴气，故其味苦气寒，无毒。入心、脾、胃三经。其主五脏邪气者，邪热客于心也。胃痹、渴热中疾者，热在胃也。肠澼者，热在大肠也。恶疮者，热瘀伤血肉也。苦寒总除诸热，故主之也。热去则神自清，故久服安心益气，聪察少卧也。轻身耐老，耐饥寒，高气不老者，总言其热退阴生，安心益气之极功也。\n\n【主治参与】\n寇宗奭《衍义》：治疔疮，以苦苣捣汁傅之，殊验。青苗叶阴干，以备冬月需用，为末，水调傅之。\n\n唐瑶《经验方》对口恶疮：野苦苣，擂汁一钟，入姜汁一匙，和酒服，以渣傅，一二次即愈。\n\n《肘后方》中沙虱毒：沙虱在水中，人澡浴则着人身，钻入皮里。初得皮上正赤，如小豆、黍、粟，摩之痛如刺，三日后发寒热，发疮毒，若入骨杀人，岭南多此。即以茅叶刮去，以苦菜汁涂之，佳。\n\n【简误】\n脾胃虚寒者忌之","videoMemo":"","fangList":[],"bieMing":"苦菜,苦苣,苦荬"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '7、苦菜,苦苣,苦荬', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6VzJBqLXjpI', 4, '{"title":"第400107706条・卷之二十七_菜部上品","description":"<p>6、莱菔</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107706,"note":"     根味辛、甘，温，无毒。散服及炮煮服食，大下气，消谷，去痰癖。肥健人。生捣汁服，主消渴，试大有验。\n\n     疏：莱菔根禀土金之气以生。本经味辛甘，气温无毒。孟诜云：性冷。大明云：平。详其功用，应是生者味辛性冷，熟者味甘温平。故本经下气，消谷，去痰癖，肥健人，及温中补不足，宽胸膈，利大小便，化痰消导者，煮熟之用也。止消渴，制面毒，行风气，去邪热气，治肺痿吐血，肺热痰嗽，下痢者，生食之用也。大抵入手足太阴、手足阳明经。故所主皆脾、肺、肠、胃之病。\n\n      子：味辛过于根。生研汁服，吐风痰。同醋研，消肿毒。炒熟，下气定喘，消食除胀，止气痛。以其性辛甚，故升降之功亦烈于根也。朱震亨云：莱菔子治痰，有推墙倒壁之功。是矣！\n\n【主治参与】\n《医学集成》（鼻勾）喘痰促，遇厚味即发者：用蔔子淘净，蒸熟晒研，姜汁浸，蒸饼丸绿豆大。每服三十丸，以口津咽下，日三服。治年远脾泄，百药不效。单煮白莱菔，终日啖之不辍，必瘥。\n\n【简误】\n莱菔根叶皆可食，生熟皆宜，乃蔬中之至贱，而能止渴充饥者。歉岁，农人种之最有利益。但性专下气，复能耗血，故多食则髭发早白。服地黄、何首乌者，不可食。\n子，消痰下气更速，凡虚弱人忌之。","videoMemo":"","fangList":[],"bieMing":"莱菔"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '6、莱菔', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hF3SvJtVhO9', 4, '{"title":"第400107705条・卷之二十七_菜部上品","description":"<p>5、芥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107705,"note":"     味辛，温，无毒。归鼻。主除肾邪气，利九窍，明耳目，安中。久食温中。\n\n     疏：芥所禀与白芥同。今人以醋、椒同芥心作辣齑食之，则脑额酸楚，泪涕俱出，即归鼻利窍，明耳目之验也。辛温能利气消痰，开胃辟寒，故主安中，及久食温中也。其主除肾邪气者，辛能润肾，温能暖水脏故也。\n\n子：功用与白芥子相同，力稍不逮。\n\n【主治参与】\n     治肺痈，用百年芥菜卤，久窨地中者，饮数匙立效。其义以芥菜辛温，得盐水久窨之气，变为辛寒。辛寒能散痰热，芥菜主通肺气，所以治肺痈，真良法也。\n\n【简误】\n   与白芥子同。其主利九窍，明耳目者，盖言辛散走窜，豁痰引涎，暂用一时，使邪去而正自复，非谓其真能利窍明耳目也。用者详之。","videoMemo":"","fangList":[],"bieMing":"芥"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '5、芥', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C0r8P42ReJl', 4, '{"title":"第400107704条・卷之二十七_菜部上品","description":"<p>4、白芥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107704,"note":"     味辛，温，无毒。主冷气。色白，甚辛美。\n\n      子：主射工，及疰气，上气，发汗，胸膈痰冷，面黄。\n\n      疏：芥禀火金之气以生，而白芥则又得金气之胜，故味辛气温无毒。辛温入肺而发散，故有温中除冷，发汗辟邪，豁痰利气之功。朱震亨云：痰在胁下及皮里膜外，非白芥子莫能达。古方控涎丹用之，正此义尔。\n\n【主治参与】\n       韩懋《医通》云：凡老人，苦于痰气喘嗽，胸满懒食，不可妄投燥利之药，反耗真气。因有人求治其亲，遂制三子养亲汤治之，随试随效。用白芥子、紫苏子、白莱菔子，各微炒研破，看所主为君，每剂不过三四钱，用绢袋盛，入汤煮饮之。勿煎大过，则味苦辣。若大便素实者，入蜜一匙。冬月加姜一片。\n\n苏恭：主疰气发无常处，及射工毒，以芥子丸服之。或捣末醋和涂之，随手有验。\n\n【简误】\n       白芥子，味极辛，气温，能搜剔内外痰结，及胸膈寒痰，冷涎壅塞者殊效。然而肺经有热，与夫阴火虚炎，咳嗽生痰者，法在所忌。其茎叶煮食，动风动气，有疮疡痔疾便血者，咸忌之。","videoMemo":"","fangList":[],"bieMing":"白芥"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '4、白芥', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gIb9Zg2YkuY', 4, '{"title":"第400107703条・卷之二十七_菜部上品","description":"<p>3、白冬瓜</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107703,"note":"      味甘，微寒。主除小腹水胀，利小便，止渴。\n\n      疏：白冬瓜内禀阴土之气，外受霜露之侵，故其味甘，气微寒，而性冷利，无毒。水属阴，瓜性亦属阴，气类相从，故能利小便，除小腹水胀也。甘寒解胃中之热，故又能止渴也。弘景：止消渴烦闷，解毒，孟诜：益气耐老，除心胸满，去头面热。大明：消热毒痈肿，切片摩疿子。苏颂：利大小肠，压丹石毒。皆得其旨者也。\n\n【主治参与】\n孟诜《食疗》积热消渴：白冬瓜去皮，每食后嚼二三两，五七度良。\n\n《古今录验》：产后痢渴，久病津液枯竭，四肢浮肿，口舌干燥，用冬瓜一枚，黄土泥厚五寸煨熟，绞汁饮良。亦治伤寒痢渴。\n\n《杨氏家藏方》：十种水气浮肿喘满，用大冬瓜一枚，切盖去瓤，以赤小豆填满，盖合签定，以纸筋泥固济，日干。用糯糠两大箩，入瓜在内，煨至火尽，取出切片，同赤豆焙干为末，水糊丸梧子大。每服七十丸，煎冬瓜子汤下，日三服，小便利为度。\n\n冬瓜仁，味甘寒，能开胃醒脾。同橘红、石斛、竹茹、枇杷叶、白芍药、芦根汁、人参、白茯苓，治胃虚呕吐。\n\n同人参、茯神、竹沥、白茯苓、黄耆、甘草、白芍药、酸枣仁，治小儿慢脾风。\n\n【简误】\n       冬瓜性冷利，凡脏腑有热者宜之。若虚寒肾冷，久病滑泄者，不得食。未经霜者，不宜多食。九月后食之乃佳。","videoMemo":"","fangList":[],"bieMing":"白冬瓜"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '3、白冬瓜', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hUXukkRK0Ea', 4, '{"title":"第400107702条・卷之二十七_菜部上品","description":"<p>2、瓜蒂</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107702,"note":"      味苦，寒，有毒。主大水，身面四肢浮肿，下水杀蛊毒，咳逆上气，及食诸果，病在胸腹中，皆吐下之。去鼻中息肉。疗黄疸。\n\n      疏：瓜蒂感时令之火热，禀地中之伏阴，故其味苦，气寒有小毒。气薄味厚，浮而升，阴多于阳，酸苦涌泄为阴故也。入手太阴、足阳明、足太阴经。其主大水，身面四肢浮肿，黄疸者，皆脾胃虚，水气湿热乘虚而客之也。苦以涌泄，使水湿之气外散，故能主之。\n\n    《经》曰：在高者，因而越之。病在胸膈，则气不得归元而为咳逆上气，吐出胸中之邪，则气自顺，咳逆止矣。杀蛊毒者，亦取吐出之义。去鼻中息肉者，以其苦寒能除肺家之热也。日华子：治脑寒热齆，眼昏吐痰。好古：得麝香、细辛，治鼻不闻香臭，及吐风热痰涎，风眩头痛，癫痫，喉痹，头面有湿气，伤寒客水胸中，伤食胀满，下部无脉等证，皆借其宣发涌泄，引涎追泪之功耳。\n\n【主治参与】\n仲景《伤寒论》：病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞硬，气上冲咽喉，不得息者，此胸中有寒也。当吐之，宜瓜蒂散。用瓜蒂、赤小豆，等分为散，取一钱，以香豉一合，用热汤七合，煮作稀糜，去滓，取汁和散顿服之。不吐，少少加，得快吐乃止。\n\n湿家病身上疼痛，发热面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈，瓜蒂散主之。\n\n太阳中暍，身热疼重，而脉微弱，此因夏月伤冷水，水行皮中所致。宜吐之，瓜蒂散。\n\n病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利日十余行，其脉反微，寸口脉微滑，此可吐之，吐之则利自止。\n\n宿食在上脘者，当吐之。\n\n病人手足厥冷，脉乍结，以客气在胸中，心下满而烦，欲食不能食者，当吐之。\n\n懊憹烦躁不得眠，未经汗下者，谓之实烦，当吐之。已上悉用瓜蒂散。皆仲景法。\n\n东垣曰：《难经》云上部有脉，下部无脉，其人当吐，不吐者死。此饮食内伤，填塞胸中，食伤太阴，则风木生发之气伏于下，宜瓜蒂散吐之。《内经》所谓木郁达之也。吐去上焦有形之物，则木得舒畅，天地交而万物通矣。诸亡血家，不可与瓜蒂散。\n\n寇氏《衍义》：风涎暴作，气塞倒仆，用瓜蒂末二钱，腻粉一钱匕，以水半合调灌，良久涎自出。不出，含沙糖一块，下咽即涎出也。\n\n《千金翼》热病发黄：瓜蒂为末，以大豆许吹鼻中，取出黄水乃愈。\n\n孟诜《食疗》阴黄黄疸：取瓜蒂、丁香、赤小豆各七枚，为末。吹豆许鼻中，少时黄水流出，隔一日用，瘥乃止。并治身面浮肿。\n\n《活人书》湿家头痛：瓜蒂末一字，㗜入鼻中，口含冷水，取出黄水愈。\n\n《圣惠方》鼻中息肉：瓜蒂末，白矾末，各半钱，锦裹塞之。或以猪脂和挺子塞之，日一换。\n\n【简误】\n        瓜蒂极苦而性上涌，能损胃伤血，耗气损神，凡胸中无寒，胃家无食，皮中无水，头面无湿，及胃虚气弱，诸亡血，诸产后，似中风倒仆，心虚有热，癫痫，女劳、谷疸，元气尪羸，脾虚浮肿，切勿误用。误用则为害非细，伤生不浅。戒之！慎之！","videoMemo":"","fangList":[],"bieMing":"瓜蒂"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2、瓜蒂', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RcUtUuAxttX', 4, '{"title":"第400107701条・卷之二十七_菜部上品","description":"<p>1、胡荽</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107701,"note":"    味辛，温（一云微寒），微毒。消谷，治五藏，补不足，利大小肠，通小腹气，拔四肢热，止头痛。疗沙疹、豌豆疮不出，作酒喷之，立出，通心窍。\n\n    疏：胡荽禀金气多，火气少，故味辛香，气温微毒。入足太阴、阳明经。辛香走窜而入脾，故主消谷，利大小肠，通少腹气。脾胃为邪热所干，则头痛四肢热。辛温发散二经之邪，则头痛四肢热自拔。沙疹、痘疮出不快者，外为风寒所侵，或秽气所触也。辛温祛风寒，香窜辟秽气，则腠理通畅而沙疹痘疮皆出矣。通心窍，治五脏补不足者，总言其辛香内通心脾，外达肠胃，除一切不正之气，则真气安和，斯有补益之道耳。\n\n子：亦能发痘疹，杀鱼腥。\n\n【主治参与】\n《经验后方》疹痘出不快：同胡荽二两切，以酒二大盏，煎沸沃之，以物盖定，勿令泄气。候冷去滓，微微含喷，从项背至足令遍，勿噀头面。\n\n《子母秘录》肛门脱出：胡荽一升切，烧烟熏之，即入。\n\n《外台秘要》牙齿疼痛：胡荽子五升，水五升，煮取一升，含嗽。\n\n【简误】\n      胡荽，辛香发散，气虚人不宜食。疹痘出不快，非风寒外侵及秽恶之气触犯者，不宜用。孟诜云：多食损人精神。华佗云：胡臭、口臭、䘌齿、脚气，皆不可食，令病加甚。陈藏器云：久食令人多忘，发腋臭。根发痼疾。凡服一切补药，及药中有白术牡丹者，咸忌之。","videoMemo":"","fangList":[],"bieMing":"胡荽"}}', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '2024-12-30T09:00:40.000Z', '1、胡荽', '2024-12-30T09:00:40.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'Sk93E9AK1uY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('spDrD3yF4xZ', 4, '{"title":"第400107802条・卷之二十八_菜部中品","description":"<p>2、韭</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107802,"note":"     味辛、微酸，温，无毒。归心，安五藏，除胃中热，利病人，可久食。\n\n      疏：韭禀春初之气而生，而兼得金水木之性，故其味辛，微酸，气温而无毒。生则辛而行血，熟则甘而补中、益肝、散滞、导瘀，是其性也。以其微酸，故入肝而主血分。辛温能散结，凡血之凝滞者，皆能行之，是血中行气药也。心主血，专理血分，故曰归心。五脏之结滞去，则气血条畅而自安矣。胃中热，乃胃中有瘀滞而发热也，瘀血行，热自除矣。病人之气抑郁者多，凡人气血，惟利通和，韭性行而能补，故可久食。\n\n     韭子：味辛，甘，温，无毒。主梦中泄精，溺血。盖韭乃入足厥阴、少阴经。肾主闭藏，肝主疏泄。《素问》云：足厥阴病则遗尿。思想无穷，入房太甚，发为筋痿，及为白淫。韭子入厥阴而甘温，补肝及命门之不足，故主泄精溺血。\n\n【主治参与】\n有一贫叟，病噎膈，食入即吐，胸中刺痛。或令取韭汁，入盐、梅、卤汁少许，细呷，得入渐加，忽吐稠涎数升而愈。此亦仲景治胸痹痛用薤白，皆取辛温能散胃脘痰饮恶血之义也。\n\n一人腊月饮酒三杯，自后食必屈曲，下膈硬涩微痛，右脉甚涩，关脉沉。此污血在胃脘之口，气因郁而成痰，隘塞食道也。以韭汁半盏，细细冷呷，尽半斤而愈。\n\n《食疗本草》：胸痹急痛如锥刺，不得俯仰，自汗出，或彻背上，不治或至死。取生韭及根五斤，洗捣汁，服之瘥。\n\n《金匮要略》风忤邪恶：韭根一把，乌梅十四个，吴茱萸炒半升，水一斗，煮之，仍以病人栉内入，煮三沸。栉浮者生，沉者死。煮至三升，分三服。\n\n《千金方》：刺伤中水肿痛，煮韭热搨之。\n\n【简误】\n韭性辛温通利，虽曰补益，然多食能令人神昏，最为养性所忌。胃气虚而有热者勿服。韭黄未出于土者勿服，食之滞气，以其气尚抑郁未申故也。花食之亦动风。","videoMemo":"","fangList":[],"bieMing":"韭"}}', '2024-12-30T09:15:14.000Z', '2024-12-30T09:15:14.000Z', '2024-12-30T09:15:14.000Z', '2、韭', '2024-12-30T09:15:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '5Wz34zIHc2J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ud5FEUL7ZmV', 4, '{"title":"第400107801条・卷之二十八_菜部中品","description":"<p>1、葱白</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107801,"note":"       辛，平。可作汤，主伤寒寒热，出汗，中风面目肿，伤寒骨肉痛，喉痹不通，安胎，归目，除肝邪气，安中利五藏，益目睛，杀百药毒。\n\n      葱实：味辛，温，无毒。主明目，补中不足。\n\n      葱根：主伤寒头痛。\n\n      葱汁：平，温。主溺血，解藜芦毒。（弘景云：葱有寒热，白冷青热。伤寒汤中不用青也。）\n\n     疏：葱禀天之阳气，得地之金味，中空象肺，其味辛平，平即凉也，而性无毒。气厚味薄，升也，阳也。入手太阴、足厥阴、足阳明经。辛能发散，能解肌，能通上下阳气，故外来怫郁诸证，悉皆主之。伤寒寒热，邪气并也。中风面目肿，风热郁也。伤寒骨肉痛，邪始中也。喉痹不通，君相二火上乘于肺也。辛凉发散，得汗则火自散，而喉痹通也。肝开窍于目。散肝中邪热，故云归目、除肝邪气。邪气散则正气通，血自和调，而有安胎、安中、利五脏之功矣。其曰益目睛、杀百药毒者，则是辛润利窍而兼解散通气之力也。\n\n【主治参与】\n《活人书》治伤寒头痛如破：连须葱白半斤，生姜二两，水煎温服。\n\n《济生秘览》：时疾头痛发热者，以连根葱白二十根，和米煮粥，入醋少许，热食取汗即解。数种伤寒一二日，初起不能分别者，亦用之取汗。\n\n风湿身痛：用生葱捣烂，入香油数点，水煎，调川芎、郁金末一钱服，取吐。\n\n《杨氏产乳》：六月孕动，困笃难救者，葱白一大握，水三升，煎一升，去滓顿服。\n\n《深师方》：胎动下血，病痛抢心，用葱白煮浓汁饮之，未死即安，已死即出。未效再服。一方加川芎。\n\n阴毒腹痛厥逆，唇青，卵缩，六脉欲绝者，用葱一束，去根及青，留白二寸，烘热，安脐上，以熨斗火熨之。葱坏则易，良久热气透入，手足温，有汗即瘥。乃服四逆汤。若熨而手足不温，不可治。\n\n华佗救卒病方：脱阳危证，凡人大吐大泄之后，四肢厥冷，不省人事，或与女子交后少腹坚痛，外肾搐缩，冷汗出，厥逆，须臾不救。先以葱白炒热熨脐，后以葱白三七茎，捣烂，用酒煮灌之，阳气即回。加人参为要。\n\n《本事方》小便闭胀，不治杀人：葱白三斤，剉、炒，帕盛二个，更互熨小腹，气透即通。\n\n刘禹锡《传信方》打扑损见血，取葱新折者，煻火煨热，剥皮，其间有涕，便将罨损处，仍多煨，续续易热者，立愈。\n\n张氏《经验方》：金疮折伤出血，用葱白连叶煨热，或锅烙炒热，捣烂傅之，冷即再易，神验。\n\n【简误】\n病人表虚易汗者，勿食。病已得汗，勿再进。","videoMemo":"","fangList":[],"bieMing":"葱白"}}', '2024-12-30T09:15:14.000Z', '2024-12-30T09:15:14.000Z', '2024-12-30T09:15:14.000Z', '1、葱白', '2024-12-30T09:15:14.000Z', 1, NULL, 'OsOP62cyp3j', 'section', '5Wz34zIHc2J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('omoj53BbWT0', 4, '{"title":"第400107904条・卷之二十九_菜部下品","description":"<p>4、鱼腥草,蕺</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107904,"note":"       味辛，微温。主蠼螋溺疮。多食令人气喘。（俗呼鱼腥草。）\n\n        疏：蕺，生于下湿之地，得阴中之阳，故其味辛，气温。入手太阴经。能治痰热蕴肺，发为肺痈吐脓血之要药。辛温主散，故能治蠼螋溺疮。肺主气，辛温能散气，故多食令人气喘。肺与大肠为表里，大肠湿热盛则为痔疮。得辛温之气，则大肠清宁，故又为痔疮必须之药。\n\n【主治参与】\n单用捣汁，入年久芥菜卤饮之，治肺痈有神。\n\n《救急方》：痔疮肿痛。鱼腥草一握，煎汤熏洗，仍以滓傅，即愈。\n\n【简误】\n蕺，只能消肺痈，治痔疮，余非所长。况多食令人气喘，发虚弱，损阳气，发脚气等害。慎之！慎之！","videoMemo":"","fangList":[],"bieMing":"鱼腥草,蕺"}}', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '4、鱼腥草,蕺', '2024-12-30T09:22:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'WXYqojhhCQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4njlYiI8Mal', 4, '{"title":"第400107903条・卷之二十九_菜部下品","description":"<p>3、茄子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107903,"note":"     味甘，寒。久冷人不可多食，损人动气，发疮及痼疾。\n\n      根及枯茎叶：主冻脚疮，可煮作汤渍之，良。\n\n      疏：茄，内禀地中一阴之气，外受南方热火之阳，故其花实皆紫。本经虽云甘寒，必是湿中有火，使非湿热，则不能动气，发疮及痼疾也。湿胜则久冷人多食有损，热胜故能主冻脚疮也。孟诜云：主寒热五脏劳。大明：治温疾，传尸劳气。皆非正治，惟肿毒家用之为当耳。\n\n【主治参与】\n《灵苑方》肠风下血：经霜茄，连蒂烧存性，为末。每日空心温酒服二钱匕。\n\n丹溪方：治乳头裂，用茄子老黄者，烧灰傅之。\n\n鲜茄蒂、鲜何首乌，等分煮饮，治对口疮有神。\n\n茄秆烧灰淋汁，和入桑硇、碱等药，诸痈肿疔疮有效。\n\n【简误】\n茄，观本经所说，止是损人，并无利益，后人虽有处治之法，然终与本经相失。凡有痼疾及虚冷人，切不可食。近世为茹菜中常用之物，尊生者当慎之。","videoMemo":"","fangList":[],"bieMing":"茄子"}}', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '3、茄子', '2024-12-30T09:22:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'WXYqojhhCQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mJkd1GQlgCF', 4, '{"title":"第400107902条・卷之二十九_菜部下品","description":"<p>2、马齿苋</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107902,"note":"      主目盲白翳，利大小便，去寒热，杀诸虫，止渴，破癥结，痈疮。服之长年不白。和梳垢封疔疮。又烧为灰，和多年醋滓，先灸疔肿，以封之，即根出。生捣绞汁服，当下恶物，去白虫。煎为膏，涂白秃。又主三十六种风结疮，以一釜煮，澄清，内腊三两，重煎成膏，涂疮上，亦服之。\n\n       疏：马齿苋禀天之阴寒，兼得地中之金气以生。故叶节间有水银，以其得金气多也。味应辛苦，气寒无毒。《经》云：荣气不从，逆于肉里，乃生痈肿。《原病式》云：诸痛痒疮疡，皆属心火。辛寒能凉血散热，故主癥结，痈疮疔肿，白秃，及三十六种风结疮。捣敷则肿散疔根拔，绞汁服则恶物当下，内外施之皆得也。辛寒通利，故寒热去，大小便利也。苦能杀虫，寒能除热，故主杀诸虫，去寸白，止渴。辛寒能散肺家之热，故主目盲白翳也。长年不白，总言其凉血、益血，病去身轻之功耳。方士多采取用，以其亦有代砂结汞之能也。\n\n【主治参与】\n崔元亮：治赤白带下，不问老幼孕妇悉可服。取马齿苋，捣绞汁三大合，和鸡子白一枚，微温顿服之。不过再作则愈。\n\n又方：疗多年恶疮，百方不瘥，或痛焮走不已者。并烂捣马齿苋敷上，不过三两遍，即愈。\n\n《广利方》小儿火丹热如火，绕脐即损人：马齿苋捣涂之。\n\n崔元亮方：疔疮肿毒，马齿苋二分，石灰三分，为末，鸡子白和傅之。\n\n【简误】\n马齿苋辛寒滑利，凡脾胃虚寒、肠滑作泄者，勿用煎饵。方中不得与鳖甲同入，令化作小鳖伤人也。","videoMemo":"","fangList":[],"bieMing":"马齿苋"}}', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '2、马齿苋', '2024-12-30T09:22:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'WXYqojhhCQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vwffdTN2YsD', 4, '{"title":"第400107901条・卷之二十九_菜部下品","description":"<p>1、蒜,葫</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400107901,"note":"     味辛，温，有毒。主散痈肿，䘌疮，除风邪，杀毒气。独子者亦佳。归五脏，久食伤人，损目明。\n\n      疏：葫，大蒜也。禀火金之气以生。故其味辛气温。辛温太甚，故其性有毒，熏臭异常，不宜多食。入足阳明、太阴、厥阴经。辛温能辟恶散邪，故主除风邪，杀毒气，及外治散痈肿䘌疮也。辛温走窜，无处不到，故主归五脏。脾胃之气最喜芳香，熏臭损神耗气，故久食则伤人。肝开窍于目，目得血而能视，辛温太过，则血耗而目损矣。总之其功长于通达走窍，去寒湿，辟邪恶，散痈肿，化积聚，暖脾胃，行诸气。故苏恭主下气消谷，化肉。藏器主风湿，破冷气，烂痃癖，伏邪恶，宣通温补。日华子主健脾胃，治肾气，止霍乱转筋腹痛，除邪祟，解温疫等用也。\n\n【主治参与】\n《外台秘要》：关格胀满，大小便不通，独头蒜烧熟，去皮绵裹，纳下部，气立通。\n\n又方：治金疮中风，角弓反张。取蒜一大升，破去心，无灰酒四升，煮令极烂，并滓服一大升，须臾得汗则瘥。\n\n《简要济众》治鼻血不止，服药不应，用蒜一枚，去皮，细研如泥，摊一饼子如钱大，厚一豆许。左鼻血出，贴左脚心；右鼻血出，贴右脚心。两鼻俱出，皆贴之，立瘥。血止，急以温水洗脚心。\n\n《外科精要》背疮灸法：凡觉背上肿硬疼痛，以湿纸贴寻疮头。用大蒜十颗，淡豆豉半合，乳香一钱，细研匀，随疮头大小，用竹片作圈圈定，填药于内，二分厚，著艾灸之。痛灸至痒，痒灸至痛，以百壮为率，效。\n《永类钤方》干湿霍乱转筋：用大蒜捣涂足心，立愈。\n\n《普济方》寒疟冷痢：端午日以独头蒜十个，黄丹二钱，捣丸梧子大。每服九丸，长流水下，妙。\n\n《衍义》暴下血病：用葫五七枚，去皮研膏，入豆豉，捣丸梧子大。每米饮下五六十丸，无不愈者。\n\n华佗行道，见车载一人，病咽塞食不下，呻吟。佗视曰：饼店家蒜齑、大酢三升，饮之当自痊。果吐大蛇一枚而愈。\n\n【简误】\n蒜性温，属火，气味臭烈。凡肺胃有热，肝肾有火，气虚血弱之人，切勿沾唇。虽有暖脾胃、祛寒湿之功，亦宜暂用，切勿过施。过则生痰动火，伤神散气，损目耗血。切戒！切戒！","videoMemo":"","fangList":[],"bieMing":"蒜,葫"}}', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '2024-12-30T09:22:04.000Z', '1、蒜,葫', '2024-12-30T09:22:04.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'WXYqojhhCQJ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3QCph7TB4Vd', 4, '{"title":"第400108033条・卷之三十_补遗","description":"<p>33、红曲</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108033,"note":"      味甘，温，无毒。\n主消食，活血，健脾，燥胃。\n治赤白痢下水谷。\n\n疏：红曲，以白粳米杂曲母蒸罨为之，亦奇术也。\n人之水谷入于胃，受中焦湿热熏蒸，精气变化而赤为血。\n红曲以白米饭受湿热郁蒸而变为红，皆造化自然之微妙也。\n故红曲治脾胃荣血之功，有同气相求之理。\n消食健脾胃，与神曲相同。\n而活血和伤，惟红曲为能，故治血痢，尤为要药。\n\n【主治参与】\n得番降香、通草、鲮鲤甲、没药，治上部内伤，胸膈作痛。\n\n或怒伤吐血，和童便服，有神效。\n\n同黄连、白扁豆、莲肉、黄芩、白芍药、升麻、干葛、乌梅、甘草、滑石、橘红，治滞下有神。\n\n同续断、番降香、延胡索、当归、通草、红花、牛膝、没药、乳香。\n\n治内伤血瘀作痛。\n\n同泽兰、牛膝、地黄、续断、蒲黄、赤芍药，治产后恶露不尽，腹中痛。\n\n《丹溪心法》湿热泄痢，青六丸：用六一散加炒红曲五钱，为末，蒸饼和丸梧子大。\n\n每六七十丸白汤下，日三服。\n\n《摘玄方》心腹作痛：赤曲、香附、乳香，等分为末，酒服。\n\n【简误】\n性能消导，无积滞者勿用。\n又善破血，无瘀血者禁使。\n","videoMemo":"","fangList":[],"bieMing":"红曲"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '33、红曲', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yNk3Yge87yG', 4, '{"title":"第400108032条・卷之三十_补遗","description":"<p>32、刀豆子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108032,"note":"      味甘，微温。\n主温中下气，止呃逆。\n昔有人病后患呃逆不止，声闻邻家。\n或令取刀豆子烧存性，为末。\n白汤调服二钱即止。\n此即下气归元之验也。","videoMemo":"","fangList":[],"bieMing":"刀豆子"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '32、刀豆子', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CZh4Xb51Qbd', 4, '{"title":"第400108031条・卷之三十_补遗","description":"<p>31、豇豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108031,"note":"      味甘、咸，平，无毒。\n补肾健胃，与诸疾无禁，可常食之。\n昔卢廉夫教人补肾气，每日空心煮豇豆，入盐少许食之，甚效。","videoMemo":"","fangList":[],"bieMing":"豇豆"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '31、豇豆', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tj49yk5nW0G', 4, '{"title":"第400108030条・卷之三十_补遗","description":"<p>30、蚕豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108030,"note":"     味甘，微辛，无毒。\n能厚肠胃，和脏腑。\n万表《积善堂方》言：一女子误吞针入腹，诸医不能治，一人教令煮蚕豆同韭菜食之，针自大便同出。\n今人有误吞金银物者，用之皆有效。\n实救急之良方也。","videoMemo":"","fangList":[],"bieMing":"蚕豆"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '30、蚕豆', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4IuubmN1v04', 4, '{"title":"第400108029条・卷之三十_补遗","description":"<p>29、豌豆,胡豆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108029,"note":"     即今之小豌豆也。\n一名胡豆。\n陈藏器云：煮食治消渴。\n孙思邈治寒热热中，吐逆，泄澼，及胀满利小便。\n应是甘平无毒，入脾胃，清利除热之物也。\n又能治痈肿痘毒。\n牛都御史秘传四圣丹，治小儿痘中有疔，或紫黑而大，或黑坏而臭，或中有紫线，此证十死八九，惟此方点之最妙。\n用豌豆四十九粒烧存性，头发灰三分，真珠十四粒研为末，以油胭脂同杵成膏，先以簪挑疔破，咂去恶血，以少许点之，即时变红活色。\n《千金》、《外台》洗面澡头方：盛用毕豆面，取其白腻去䵟（黑曾），令人光泽也。","videoMemo":"","fangList":[],"bieMing":"豌豆,胡豆"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '29、豌豆,胡豆', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Avm6B3Knj9', 4, '{"title":"第400108028条・卷之三十_补遗","description":"<p>28、绿豆粉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108028,"note":"       甘，凉，无毒。\n主解诸热，益气，解酒食诸毒。\n治发背痈疮肿，及汤火伤灼。\n\n     疏：绿豆粉，所禀气味与绿豆同。\n故能解诸热，及酒食毒，汤火伤灼也。\n发背痈疽疮肿，皆热毒所致，甘寒解阳明之热，则毒气不至犯胃而呕恶，肠胃清凉而诸肿散矣。\n热伤气，除热故能益气也。\n\n【主治参与】\n李嗣立《外科精要》护心散，又名内托散、乳香万全散：凡有疽疾，一日至十三日内，宜连进十余服，方免变证，使毒气出外。\n\n服之稍迟，毒气内攻，渐生呕吐，或鼻生疮菌，不食即危矣。\n\n四五日亦宜间服之。\n\n用真绿豆粉一两，乳香半两，灯心同研和匀，以生甘草煎浓汤，调下一钱，时时呷之。\n\n若毒气冲心有呕逆之证，大宜服此。\n\n盖绿豆压热下气，消肿解毒，乳香消诸痈肿毒。\n\n服至一两，则香彻疮孔中，真圣药也。\n\n一方有丹砂二钱半。\n\n《卫生易简》解砒石毒：绿豆、寒水石等分，以蓝汁调服三五钱。\n\n又方，夏月痱疮：绿豆粉二两，滑石一两，和匀扑之。\n\n一方加蛤粉。\n《生生编》杖疮疼痛：绿豆粉炒研，以鸡子白和涂之，妙。\n\n《澹寮方》打扑伤损：用绿豆粉炒紫色，新汲水调傅，以杉木皮缚定，其效如神。\n\n绿豆皮：能解热毒，退目翳。\n\n《直指方》通神散：治斑痘后目生翳，用绿豆皮、甘菊花、谷精草等分，为末。\n\n每服一钱，以干柿饼一枚，粟米泔一盏，同煮干。\n\n食柿，日三服。\n浅者五七日见效，远者半月见效。\n\n【简误】\n绿豆粉性凉，脾胃虚寒易泄者，勿多食。","videoMemo":"","fangList":[],"bieMing":"绿豆粉"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '28、绿豆粉', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HuqFqxiJGFT', 4, '{"title":"第400108027条・卷之三十_补遗","description":"<p>27、阿芙蓉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108027,"note":"    罂粟花之津液也。\n\n     罂粟结青苞时，午后以大针刺其外面青皮，勿损里面硬皮，或三五处，次早津出，以竹刀刮取，入磁器，阴干用之。\n\n其气味与粟壳相同，而此则止痢之功尤胜。\n\n故小儿痘疮行浆时，泄泻不止，用五厘至一分，未有不愈，他药莫逮也。\n","videoMemo":"","fangList":[],"bieMing":"阿芙蓉"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '27、阿芙蓉', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f2ewUtWm3fw', 4, '{"title":"第400108026条・卷之三十_补遗","description":"<p>26、罂子粟</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108026,"note":"      味甘，平，无毒。\n主丹石发动不下食。\n和竹沥煮作粥，食之极美。\n\n疏：罂粟，其花至有千叶者，红、白、紫、黑色，有数种。\n\n一罂内子凡数千万粒，细如葶苈子而色白。\n\n本经味甘，平，无毒。\n\n苏颂性寒。\n\n甘寒除热解毒，下气和中，故主丹石发动不下食，及《图经》行风气，逐邪热，止反胃，去胸中痰滞也。","videoMemo":"","fangList":[],"bieMing":"罂子粟"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '26、罂子粟', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OpnGhe563mA', 4, '{"title":"第400108025条・卷之三十_补遗","description":"<p>25、粟壳</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108025,"note":"      味酸、涩，微温，无毒。\n\n古方治嗽，及泻痢、脱肛、遗精，多用之，今人亦效尤辄用，殊为未妥。\n\n不知咳嗽惟肺虚无火，或邪尽嗽不止者，用此敛其虚耗之气。\n\n若肺家火热盛，与夫风寒外邪未散者，误用则咳愈增而难治。\n\n泻痢脱肛由于下久滑脱，肠虚不禁；遗精由于虚寒滑泄者，借用酸涩收敛之气以固虚脱。\n\n如肠胃积滞尚多，湿热方炽，命门火盛，湿热下流为遗精者，误用之则邪气无从而泄，或腹痛不可当，或攻入手足骨节肿痛不能动，或遍身发肿，或呕吐不下食，或头面俱肿，或精窍闭塞，水道不通，变证百出而淹延不起矣。\n可不慎哉！","videoMemo":"","fangList":[],"bieMing":"粟壳"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '25、粟壳', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JIPJFHeEcyd', 4, '{"title":"第400108024条・卷之三十_补遗","description":"<p>24、亚麻</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108024,"note":"     即鳖虱胡麻，出兖州威胜军，今陕州亦种之。\n其味甘，气温，无毒。\n足厥阴经血分药也。\n厥阴藏血，为风木之脏。\n凡大风疮癣，总厥阴血热所致。\n甘温益血而通行，则血自活，风自散，疠疾疥癞疮癣俱除矣。\n\n【主治参与】\n得漆叶、苦参、荆芥、天门冬、生地黄、青黛、百部、白花蛇、何首乌、半枝莲、豨莶叶、刺蒺藜、甘菊花，治大麻风。\n\n同金银花、连翘、萆薢、土茯苓、何首乌、苍术、木瓜、薏苡仁、生地黄、黄檗，治湿热太甚，遍身脓窠疮。\n","videoMemo":"","fangList":[],"bieMing":"亚麻"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '24、亚麻', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tWHU3kTIenR', 4, '{"title":"第400108023条・卷之三十_补遗","description":"<p>23、鳜鱼胆</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108023,"note":"        此鱼最能发湿，惟胆能治鱼骨鲠，及竹木刺误吞入喉不出，或吞入腹，腹中作痛隐隐，皆效。\n状如鲈鱼者是。","videoMemo":"","fangList":[],"bieMing":"鳜鱼胆"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '23、鳜鱼胆', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fzMS29n4M6G', 4, '{"title":"第400108022条・卷之三十_补遗","description":"<p>22、羊胫骨</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108022,"note":"    本经无文。\n      《纲目》载其主虚冷劳，及脾弱肾虚不能摄精，白浊，除湿热，健腰脚，固牙齿，去䵟（黑曾），治误吞铜铁金银等证。\n按《名医录》云：昔汉上张成忠女，年七八岁，误吞金馈子一只，胸膈痛不可忍，忧惶无措。\n一银匠炒末药三钱，米饮服之，次早大便取下。\n叩求其方，乃羊胫灰一物。\n盖羊胫骨灰可以磨镜，羊头骨灰可以消铁，故能治如是之证。\n谈野翁亦有此方。\n乃秘妙神效之法也。\n\n【主治参与】\n《食鉴》：擦牙固齿。\n\n羊胫骨灰一两，升麻一两，黄连五钱，为末，入青盐和匀，日用。\n\n《圣惠方》：咽喉骨鲠。\n\n羊胫骨灰，米饮下一钱。","videoMemo":"","fangList":[],"bieMing":"羊胫骨"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '22、羊胫骨', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CXqUP0zLx03', 4, '{"title":"第400108021条・卷之三十_补遗","description":"<p>21、山獭阴茎</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108021,"note":"       味甘，热，无毒。\n主阳虚阴痿精寒。\n此物出广之宜州嵠峒，及南丹州。\n土人号为插翅。\n其性淫毒，山中有此物，凡牝兽皆避去。\n獭无偶则抱木而枯。\n徭女春时成群入山，以采物为事。\n獭闻妇人气，必跃来抱之，刺骨而入，牢不可脱，因扼杀之。\n负归取其阴，一枚值金一两。\n若得抱木死者，尤奇贵。\n峒獠甚珍重之，私货出界者，罪至死。\n本地亦不常有，多伪者。\n试之之法，但令妇女摩手极热，取置掌心，以气呵之，跃然而动者为真","videoMemo":"","fangList":[],"bieMing":"山獭阴茎"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '21、山獭阴茎', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2cXDfpein6z', 4, '{"title":"第400108020条・卷之三十_补遗","description":"<p>20、狗宝</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108020,"note":"     狗宝，如牛之有黄也。\n第狗性热，其宝定是苦温之物。\n世人用治噎证，以其苦能下泄，温能通行耳。\n又能主痈疽疔肿，同蟾酥、脑、麝、雄黄、乳香、没药等用。\n\n【简误】\n狗宝性热，善消噎病。\n由于痰及虚寒而得者，犹可暂用取效。\n若因血液衰少以致噎膈者，法所当忌。\n世医不谙药理，不察病本，一概妄投，致病增剧。\n戒之！戒之！\n又，凡有脾胃虚弱，羸瘦不振之病，尤不宜用。","videoMemo":"","fangList":[],"bieMing":"狗宝"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '20、狗宝', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('80Of8ETrUVg', 4, '{"title":"第400108019条・卷之三十_补遗","description":"<p>19、霞天膏</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108019,"note":"       味甘，温，无毒。\n主中风偏废，口眼歪斜，痰涎壅塞，五藏六腑留痰、宿饮、癖块，手足皮肤中痰核。\n其法用肥嫩雄黄牛肉三四十斤，洗极净，水煮成糜，滤去滓，再熬成膏用。\n\n      疏：胃属土，为水谷之海，无物不受。\n胃病则水谷不能以时运化，羁留而为痰饮。\n壅塞经络，则为积痰、老痰、结痰等证。\n阴虚内热生痰，则为偏废、口眼歪斜。\n留滞肠胃，则为宿饮、癖块。\n随气上涌，则为喘急迷闷。\n流注肌肉，则为结核。\n王隐君论人之诸疾，悉由于痰。\n然而痰之所生，总由于脾胃虚，不能运化所致。\n惟用霞天膏以治诸痰证者，盖牛，土畜也。\n黄，土色也。\n肉者，胃之味也。\n熬而为液，虽有形而无浊质也。\n以脾胃所主之物，治脾胃所生之病，故能由肠胃而渗透肌肤毛窍，搜剔一切留结也。\n阴虚内热之人，往往多痰，此则由于水涸火炽，煎熬津液，凝结为痰。\n胶固难散者，亦须以此和竹沥、贝母、橘红、苏子、栝楼根、枸骨叶之类消之。\n或以橘皮、白茯苓、苏子、白豆蔻仁、半夏、苍术为麯，治脾胃积痰。\n或以橘皮、贝母、苏子、栝楼根及仁、蓬砂为麯，治积热痰结。","videoMemo":"","fangList":[],"bieMing":"霞天膏"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '19、霞天膏', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t12Iz7ADcvD', 4, '{"title":"第400108018条・卷之三十_补遗","description":"<p>18、黄明胶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108018,"note":"   味甘，平，无毒。\n\n主诸吐血，下血，血淋，妊妇胎动下血，风湿走注疼痛，打扑伤损，汤火灼疮，一切痈疽肿毒，活血止痛。\n（即牛皮胶。）\n\n按《本经》白胶，一名鹿角胶，煮鹿角作之。\n\n阿胶，一名傅致胶，煮牛皮或驴皮作之。\n\n其说甚明。\n黄明胶，即今水胶，乃牛皮所作，其色黄明，非白胶也，亦非阿井水所作。\n\n甄权以黄明为鹿角白胶，唐慎微又采黄明诸方附于白胶后，并误矣。\n\n其气味与阿胶同，故其所主亦与阿胶相似。\n\n以非阿井水及驴皮同造，故不能疏利下行。\n\n以其性味皆平补，亦宜于血虚有热者。\n\n若鹿角胶，则性味温补，非虚热者所宜，不可不详辨也。\n\n【主治参与】\n蔺氏方：跌扑损伤：真牛皮胶一两，干冬瓜皮一两，剉，同炒存性，研末。\n\n每服五钱，热酒一钟调服。\n\n仍饮酒二三盏，暖卧微汗痛止。\n\n《本事方》诸般痈肿：黄明胶一两，水半升化开，入黄丹一两，煮匀，以鹅翎扫上疮口。\n\n如未成者，涂其四围自消。\n\n阮氏《经验方》：背疽初起，用黄明牛皮胶四两，入酒重汤顿化，随意饮尽。\n\n不能饮者，滚白汤饮之。\n\n服此，毒不内攻。\n\n一方加穿山甲四片，炒成末，其妙无比。","videoMemo":"","fangList":[],"bieMing":"黄明胶"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '18、黄明胶', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9NvPvRY2RZD', 4, '{"title":"第400108017条・卷之三十_补遗","description":"<p>17、人气</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108017,"note":"     主下元虚冷。\n日令童男女，以时隔衣进气脐中，及两腰肾间，甚良。\n凡人身体骨节痹痛，令人更互呵熨，久久经络通透。\n盖气属阳，为一身之健运，即真火也。\n天非此火不能生物，人非此火不能有生。\n故老人、虚人，与二七以前少阴同寝，藉其熏蒸，最为有益，下元虚冷，火气衰也。\n得外入之少火，乃所以补其不足。\n骨节疼痹，血泣不行也。\n血不自行，随气而行，故能使骨节通畅也。\n近时术士，令童女以气进入鼻窍、脐中、精门，以通三田，谓之接补。\n此亦小法，不得其道者，反以致疾。","videoMemo":"","fangList":[],"bieMing":"人气"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '17、人气', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wiBVIGoTtQm', 4, '{"title":"第400108016条・卷之三十_补遗","description":"<p>16、蛀竹屑</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108016,"note":"      年久枯竹中蠹屑也。\n竹之余气尚存，其气味必甘平无毒。\n甘能解毒，平则兼散，故可用为蚀脓长肉之药也。\n\n【主治参与】\n同象牙末、真珠、白矾等药，能消漏管。方见象牙条下。\n\n朱氏《集验方》：耳出臭脓，用蛀竹屑、胭脂胚子等分，麝香少许，为末，吹之。\n\n《普济方》：耳脓作痛，因水入耳中者，蛀竹屑一钱、腻粉一钱、麝香五分，为末。\n\n以绵杖绞净，送药入耳，以绵塞定。\n\n有恶物，放令流出，甚者三度必愈。\n\n又方湿毒臁疮：蛀竹屑、黄檗末等分，先以葱椒茶汤洗净，搽之。\n\n日一次，效。\n《外台秘要》汤火灼疮：蛀竹屑末，傅之愈。","videoMemo":"","fangList":[],"bieMing":"蛀竹屑"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '16、蛀竹屑', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1XrUBnrcgKb', 4, '{"title":"第400108015条・卷之三十_补遗","description":"<p>15、樟脑</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108015,"note":"      得纯阳之气，其味辛，其气热。\n初时以水煎成，后得火则焰炽不息，其禀龙火之性者乎？\n气亦香窜，能通利关窍，逐中恶邪气，复能去湿杀虫。\n凡一切疥癣风瘙，湿毒疮疡等证，皆所须用。","videoMemo":"","fangList":[],"bieMing":"樟脑"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '15、樟脑', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xbI0AM7wp4D', 4, '{"title":"第400108014条・卷之三十_补遗","description":"<p>14、大风子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108014,"note":"       禀火金之气以生，故其味辛苦，气热，有毒，辛能散风，苦能杀虫燥湿，温热能通行经络。\n世人用以治大风疠疾，乃风癣疥癞诸疮，悉此意耳。\n然性热而燥，伤血损阴，不宜多服。\n用之外治，其功不可备述也。","videoMemo":"","fangList":[],"bieMing":"大风子"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '14、大风子', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cVcyw9fjvvT', 4, '{"title":"第400108013条・卷之三十_补遗","description":"<p>13、肥皂荚</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108013,"note":"       生于盛夏六阳之令，而成于秋金之月。\n得火金之气，故其味辛，气温有毒。\n凡肠胃有垢腻，秽恶之气郁于中，则外生瘰疬恶疮肿毒。\n泄于外，则为肠风下痢脓血。\n此药专能荡涤垢腻，宣通秽积，肠胃洁净，则诸证自除也。\n\n【主治参与】\n秘方：治瘰疬，用肥皂去核，入斑猫在内，扎紧蒸，去斑猫，加入贝母、天花粉、玄参、甘草、牛旁子、连翘，为丸。\n\n每服一钱，白汤下，服后腹疼勿虑，此药力追毒之故。\n\n独核仁，同猪胰子、金银花、皂角刺、芭蕉根、雪里红、五加皮、土茯苓、皂荚子、白僵蚕、木瓜、蝉蜕、白鲜皮，治霉疮。\n\n久虚者，加人参、黄耆、薏苡仁，兼治结毒。\n\n《普济方》肠风下血：独子肥皂烧存性一片，为末，糊丸。\n\n米饮下。\n又方，治腊梨头疮：用独核肥皂，去核，填入沙糖，入巴豆二枚，扎定，盐泥固煅存性，再入槟榔、轻粉六七分，研匀，香油调搽。\n\n先以汤洗净，拭干乃搽。\n\n一宿见效。\n\n除疮毒外，无他用，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"肥皂荚"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '13、肥皂荚', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FBKpY8w3zmb', 4, '{"title":"第400108012条・卷之三十_补遗","description":"<p>12、木绵子</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108012,"note":"    得地中之阳气，复感秋金之气以成。\n其味辛，其气热，其性有毒。\n入肝、入肾，祛风湿、寒湿之药也。\n惟其辛，故能散风邪；惟其热，故能除寒湿。\n凡下部有风寒湿邪者宜之。\n然而性热有毒，肝肾虚者不宜用。\n一切阴虚火炽，痿弱下体无力者，咸忌之。","videoMemo":"","fangList":[],"bieMing":"木绵子"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '12、木绵子', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tqoJvi3F1Bm', 4, '{"title":"第400108011条・卷之三十_补遗","description":"<p>11、山茶花</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108011,"note":"      得一阳之气以生，故其花开于冬末春初之时。\n其味甘而微辛，气平而微寒，色赤而入血分，故主吐血，衄血，肠风下血。\n并为末，入童溺及酒调服。\n","videoMemo":"","fangList":[],"bieMing":"山茶花"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '11、山茶花', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YIm07zBMN0b', 4, '{"title":"第400108010条・卷之三十_补遗","description":"<p>10、木芙蓉</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108010,"note":"      禀夏末秋初之气，故其味辛。\n辛属金化，故能清肺，其气平，平即凉也，故能凉血散热解毒，兼治一切痈疽肿毒恶疮，排脓止痛，小儿疳积。\n\n【主治参与】\n《简便方》痈疽肿毒：重阳前取芙蓉叶，研末，端午前取苍耳烧存性，研末，等分，蜜水调涂四周。\n\n其毒自不走散。名铁井栏。\n\n他用甚稀，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"木芙蓉"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '10、木芙蓉', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UpQ4kivTSPA', 4, '{"title":"第400108009条・卷之三十_补遗","description":"<p>9、方诸水</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108009,"note":"     味甘，寒，无毒。\n主明目，定心，去小儿热烦，止渴。\n方诸，大蚌也。\n向月取之，得二三合，水亦如朝露，又名明水。\n得至阴之精华，故能明目定心，及止渴除烦热也。\n又为丹灶家所须。","videoMemo":"","fangList":[],"bieMing":"方诸水"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '9、方诸水', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sxfPCo6JW7J', 4, '{"title":"第400108008条・卷之三十_补遗","description":"<p>8、炉甘石</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108008,"note":"      味甘，温，无毒。\n主止血，消肿毒，生肌，明目去翳退赤，收湿除烂。\n同龙脑，点治目中一切病。\n\n疏：炉甘石，受金气而结。\n味应甘辛，气温无毒，其性带涩。\n《经》曰：荣气不从，逆于肉里，乃生痈肿。\n甘温能通畅血脉，则肿痛散，血自止，肌肉生也。\n又目得血而能视，风热上壅则目为赤烂浮翳。\n甘入脾而益血，辛温能散风热，性涩则能粘物，故同除翳药点目翳，及治目中一切病也。\n\n【主治参与】\n一切目疾：真炉甘石半斤，用黄连四两，剉碎，入银石器内，水二碗，煮二伏时，去黄连，以甘石为末，入龙脑香二钱半，研匀，罐收。\n\n每点少许，频用取效。\n\n邵真人方：下疳阴疮，炉甘石煅，醋淬七次，一两，孩儿茶三钱，为末，麻油调敷，立效。\n","videoMemo":"","fangList":[],"bieMing":"炉甘石"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '8、炉甘石', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bEVqwbLjuop', 4, '{"title":"第400108007条・卷之三十_补遗","description":"<p>7、银朱</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108007,"note":"      乃硫黄同汞升炼而成。\n其性燥烈，过服能使人龈烂筋挛。\n其味辛气温，有毒。\n亦能破积滞，散结，疗癣疥恶疮，杀虫。\n不宜服食。\n今人多以黄丹、矾红杂之，不堪用。\n\n【主治参与】\n李楼《怪症方》火焰丹毒：银朱调鸡子清涂之。\n\n《多能鄙事》汤火灼伤：银朱研细，菜油调敷。\n\n《应急良方》：日久顽疮不收者。银朱一钱、地龙骨（即年久石灰）五分、松香五钱，为末，香油一两，化摊纸上贴之。\n\n兼能治湿毒臁疮。","videoMemo":"","fangList":[],"bieMing":"银朱"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '7、银朱', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j0PUOBEyL6H', 4, '{"title":"第400108006条・卷之三十_补遗","description":"<p>6、石碱</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108006,"note":"      味辛、苦、涩，气温，微毒。\n性能除垢腻，磨积块，过服能损人。\n同石灰、桑硇，透肌肉，溃痈瘰疬，去瘀肉，点痣靥疣赘。\n今人用以浣衣。\n（出山东济宁、大同诸处。彼入采蒿蓼之属，开窖浸水，漉起晒干，烧灰，以原水淋汁，每百斤入粉面一二斤，则凝定如石，连汁货之。）\n\n【简误】\n      碱乃软坚消积之物，食之使人泄泻。\n以其阴湿之性，润下软坚透肉，故于肠胃非宜。\n作泄胃薄者忌之。","videoMemo":"","fangList":[],"bieMing":"石碱"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '6、石碱', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6aaFY7q3W5K', 4, '{"title":"第400108005条・卷之三十_补遗","description":"<p>5、烟胶</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108005,"note":"      味辛，苦，气微温。\n辛能散风，苦能燥湿杀虫。\n故主头疮，白秃，疥疮，风癣痒痛流水。\n取焇牛皮灶岸烟膏为末，麻油调涂，或入轻粉少许。\n（此即熏焇牛皮灶上黑土也。）","videoMemo":"","fangList":[],"bieMing":"烟胶"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '5、烟胶', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WaKLpCdhUJV', 4, '{"title":"第400108004条・卷之三十_补遗","description":"<p>4、乌爹泥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108004,"note":"     味苦、涩，平，无毒。\n主清上膈热，化痰生津，涂金疮，一切诸疮，生肌定痛，止血收湿。\n一名孩儿茶。\n（出南番爪哇暹罗诸国。今云南、老挝、暮云场地方造之。云是细茶末，入竹筒中，坚塞两头，埋乌泥沟中，日久取出，捣汁熬制而成。其块小而润泽者为上，大而焦枯者次之。）\n\n         疏：乌爹泥本是茶末，又得土中之阴气，其味苦涩，气应作寒，性无毒。\n其主清上膈热，化痰生津者，茶之用也。\n得地中之阴气，能凉血清热，故主金疮止血，及一切诸疮，生肌定痛也。\n苦能燥，涩能敛，故又主收湿气。\n\n【主治参与】\n《积德堂方》牙疳口疮：孩儿茶、硼砂等分，为末搽之。\n\n《纂奇方》下疳阴疮：孩儿茶一钱，真珠一分，片脑半分，为末傅之。\n\n董炳方：脱肛气热。孩儿茶二分，熊胆五分，片脑一分，为末，人乳调搽肛上，热汁自下而肛收也。亦治痔疮。\n\n今人多用外治，内服甚少，故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"乌爹泥"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '4、乌爹泥', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xSoKRtehZjK', 4, '{"title":"第400108003条・卷之三十_补遗","description":"<p>3、粪坑底泥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108003,"note":"    大寒，无毒。\n治发背，诸恶疮。\n阴干为末，新水调傅，其痛立止。\n《圣济总录》治疔肿：粪下土、蝉蜕、全蝎等分，捣作钱大饼，香油煎滚，温服。\n以滓傅疮四围，疔自出也。\n今人以热粪盛核桃壳内，覆疔肿上，云疔根即烂出，即此意也。","videoMemo":"","fangList":[],"bieMing":"粪坑底泥"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '3、粪坑底泥', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U0jq648m3oG', 4, '{"title":"第400108002条・卷之三十_补遗","description":"<p>2、蚯蚓泥</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108002,"note":"      即蚯蚓屎也。\n味甘，气寒，无毒。\n赤白久热痢，取一升炒，烟尽，沃汁半升，滤净饮之。\n盖久痢乃湿热甚于肠胃，得甘寒之气，则湿热自除矣。\n日华子主小儿阴囊忽虚热肿痛，以生甘草汁入轻粉末调涂之。\n以盐研，傅疮去热毒，及蛇犬伤。\n苏恭主傅狂犬伤，出犬毛者，神效。\n皆取甘寒除热解毒之力耳。\n【主治参与】\n《外台秘要》：一切丹毒，水和蚯蚓泥傅之。\n\n丹溪方：时行腮肿，柏叶汁调蚯蚓泥涂之。\n\n《摘玄方》燕窝生疮：韭地蛐蟮屎，米汁水和，煅过，入百草霜，等分研末，香油调涂之。\n\n又方：治下部杨梅结毒，韭地上蚯蚓泥、硫黄，等分研匀，用泥封固，作团煨过，取出研细，生桐油调搽。\n\n【简误】\n虚寒滑利，不宜用。","videoMemo":"","fangList":[],"bieMing":"蚯蚓泥"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2、蚯蚓泥', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n2BfwNqZNXW', 4, '{"title":"第400108001条・卷之三十_补遗","description":"<p>1、黄土</p>","content_format":"html","_microfeed":{"bookId":"OsOP62cyp3j","receiptNo":400108001,"note":"     味甘，平，无毒。\n\n       主泄痢冷热赤白，腹中热毒绞结痛，下血。\n取入地干土，以水煮三五沸，绞去滓，暖服一二升。\n又解诸药毒，中肉毒，合口椒毒，野菌毒。\n（张司空云：三尺以上曰粪，三尺以下曰土。凡用当去上恶物，勿令入客水。）\n\n        疏：土为万物之母，黄乃中央正色，在人脏腑则脾胃应之。\n故万物非土不生，人身五脏六腑非脾胃无以养。\n是以黄土入药，治泄痢冷热赤白，脾中热毒绞结痛者，取其补助戊己之功也。\n味甘而气和，故能安和脾胃，止下血，及解百毒，如经所言也。\n\n【主治参与】\n《小儿秘诀》：乌沙惊风，遍身都黑者，急推向下，将黄土一碗，捣末，入酢一钟，炒热包定，熨之，引下至足，刺破为妙。\n\n气味和平，与物无迕。故不著 “简误”。","videoMemo":"","fangList":[],"bieMing":"黄土"}}', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '2024-12-31T02:23:47.000Z', '1、黄土', '2024-12-31T02:23:47.000Z', 1, NULL, 'OsOP62cyp3j', 'section', 'w5J05RTCWIU');
